INSERT INTO dataset_versions (id, source_name, source_version, generated_from, publication_status, verification_status, record_count, content_hash, imported_at) VALUES ('dataset.hisn.legacy.2026-07-11-v2', 'Hisn al-Muslim legacy import', '2026-07-11-v2', 'Fortress_of_Muslim.docx', 'active', 'pending', 135, 'd1382f6d7fb454a7dc3fa94210992dbf7b4823c490755f31c712325f4267bc39', '2026-07-18T00:00:00.000Z');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.001', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-001', 1, 'When waking up', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.001.part.001', 'dua.hisn.001', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.001.part.001.segment.001', 'dua.hisn.001.part.001', 1, 'arabic', 'ar', 'Arab', 'الحَمْـدُ لِلّهِ الّذي أَحْـيانا بَعْـدَ ما أَماتَـنا وَإليه النُّـشور');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.001.part.001.segment.002', 'dua.hisn.001.part.001', 2, 'transliteration', 'ar-Latn', 'Latn', 'Alhamdu lillahil-lathee ahyana baAAda ma amatana wa-ilayhin-nushoor.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.001.part.001.segment.003', 'dua.hisn.001.part.001', 3, 'translation', 'en', 'Latn', '‘All praise is for Allah who gave us life after having taken it from us and unto Him is the resurrection.’en it from us and unto Him is the resurrection.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.001.part.002', 'dua.hisn.001', 2);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.001.part.002.segment.001', 'dua.hisn.001.part.002', 1, 'comment', 'en', 'Latn', 'The Prophet (saws) said : ‘Whoever awakes at night and then says:');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.001.part.002.segment.002', 'dua.hisn.001.part.002', 2, 'arabic', 'ar', 'Arab', 'لا إلهَ إلاّ اللّهُ وَحْـدَهُ لا شَـريكَ له، لهُ المُلـكُ ولهُ الحَمـد، وهوَ على كلّ شيءٍ قدير، سُـبْحانَ اللهِ، والحمْـدُ لله، ولا إلهَ إلاّ اللهُ واللهُ أكبَر، وَلا حَولَ وَلا قوّة إلاّ باللّهِ العليّ العظيم.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.001.part.002.segment.003', 'dua.hisn.001.part.002', 3, 'transliteration', 'ar-Latn', 'Latn', 'La ilaha illal-lahu wahdahu la shareeka lah, lahul-mulku walahul-hamd, wahuwa AAala kulli shay-in qadeer, subhanal-lah, walhamdu lillah, walailaha illal-lah wallahu akbar, wala hawla wala quwwata illa billahil-AAaliyyil AAatheem.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.001.part.002.segment.004', 'dua.hisn.001.part.002', 4, 'translation', 'en', 'Latn', '‘None has the right to be worshipped except Allah, alone without associate, to Him belongs sovereignty and praise and He is over all things wholly capable.How perfect Allah is, and all praise is for Allah, and none has the right to be worshipped except Allah, Allah is the greatest and there is no power nor might except with Allah, The Most High, The Supreme.');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.001.part.003', 'dua.hisn.001', 3);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.001.part.003.segment.001', 'dua.hisn.001.part.003', 1, 'comment', 'en', 'Latn', 'and then supplicates:');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.001.part.003.segment.002', 'dua.hisn.001.part.003', 2, 'arabic', 'ar', 'Arab', 'رَبِّ اغْفرْ لي.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.001.part.003.segment.003', 'dua.hisn.001.part.003', 3, 'transliteration', 'ar-Latn', 'Latn', 'Rabbigh-fir lee');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.001.part.003.segment.004', 'dua.hisn.001.part.003', 4, 'translation', 'en', 'Latn', '‘O my Lord forgive me.’will be forgiven’Al-Waleed said, “or hesaid: ‘and then asks, he will be answered.If he then performs ablution and prays, his prayer will be accepted’.”');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.001.part.004', 'dua.hisn.001', 4);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.001.part.004.segment.001', 'dua.hisn.001.part.004', 1, 'arabic', 'ar', 'Arab', 'الحمدُ للهِ الذي عافاني في جَسَدي وَرَدّ عَليّ روحي وَأَذِنَ لي بِذِكْرِه.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.001.part.004.segment.002', 'dua.hisn.001.part.004', 2, 'transliteration', 'ar-Latn', 'Latn', 'Alhamdu lillahil-lathee AAafanee fee jasadee waradda AAalayya roohee wa-athina lee bithikrih.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.001.part.004.segment.003', 'dua.hisn.001.part.004', 3, 'translation', 'en', 'Latn', '‘All praise is for Allah who restored to me my health and returned my soul andhas allowed me to remember Him.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.001.part.005', 'dua.hisn.001', 5);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.001.part.005.segment.001', 'dua.hisn.001.part.005', 1, 'arabic', 'ar', 'Arab', 'إِنَّ فِي خَلْقِ السَّمَاوَاتِ وَالْأَرْضِ وَاخْتِلَافِ اللَّيْلِ وَالنَّهَارِ لَآيَاتٍ لِأُولِي الْأَلْبَابِ ۞ الَّذِينَ يَذْكُرُونَ اللهَ قِيَامًا وَقُعُودًا وَعَلَى جُنُوبِهِمْ وَيَتَفَكَّرُونَ فِي خَلْقِ السَّمَاوَاتِ وَالْأَرْضِ رَبَّنَا مَا خَلَقْتَ هَذَا بَاطِلًا سُبْحَانَكَ فَقِنَا عَذَابَ النَّارِ ۞ رَبَّنَا إِنَّكَ مَنْ تُدْخِلِ النَّارَ فَقَدْ أَخْزَيْتَهُ وَمَا لِلظَّالِمِينَ مِنْ أَنْصَارٍ ۞ رَبَّنَا إِنَّنَا سَمِعْنَا مُنَادِيًا يُنَادِي لِلْإِيمَانِ أَنْ آمِنُوا بِرَبِّكُمْ فَآمَنَّا رَبَّنَا فَاغْفِرْ لَنَا ذُنُوبَنَا وَكَفِّرْ عَنَّا سَيِّئَاتِنَا وَتَوَفَّنَا مَعَ الْأَبْرَارِ ۞ رَبَّنَا وَآتِنَا مَا وَعَدْتَنَا عَلَى رُسُلِكَ وَلَا تُخْزِنَا يَوْمَ الْقِيَامَةِ إِنَّكَ لَا تُخْلِفُ الْمِيعَادَ ۞ فَاسْتَجَابَ لَهُمْ رَبُّهُمْ أَنِّي لَا أُضِيعُ عَمَلَ عَامِلٍ مِنْكُمْ مِنْ ذَكَرٍ أَوْ أُنْثَى بَعْضُكُمْ مِنْ بَعْضٍ فَالَّذِينَ هَاجَرُوا وَأُخْرِجُوا مِنْ دِيَارِهِمْ وَأُوذُوا فِي سَبِيلِي وَقَاتَلُوا وَقُتِلُوا لَأُكَفِّرَنَّ عَنْهُمْ سَيِّئَاتِهِمْ وَلَأُدْخِلَنَّهُمْ جَنَّاتٍ تَجْرِي مِنْ تَحْتِهَا الْأَنْهَارُ ثَوَابًا مِنْ عِنْدِ اللهِ وَاللهُ عِنْدَهُ حُسْنُ الثَّوَابِ ۞ لَا يَغُرَّنَّكَ تَقَلُّبُ الَّذِينَ كَفَرُوا فِي الْبِلَادِ ۞ مَتَاعٌ قَلِيلٌ ثُمَّ مَأْوَاهُمْ جَهَنَّمُ وَبِئْسَ الْمِهَادُ ۞ لَكِنِ الَّذِينَ اتَّقَوْا رَبَّهُمْ لَهُمْ جَنَّاتٌ تَجْرِي مِنْ تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا نُزُلًا مِنْ عِنْدِ اللهِ وَمَا عِنْدَ اللهِ خَيْرٌ لِلْأَبْرَارِ ۞ وَإِنَّ مِنْ أَهْلِ الْكِتَابِ لَمَنْ يُؤْمِنُ بِاللهِ وَمَا أُنْزِلَ إِلَيْكُمْ وَمَا أُنْزِلَ إِلَيْهِمْ خَاشِعِينَ للهِ لَا يَشْتَرُونَ بِآيَاتِ اللهِ ثَمَنًا قَلِيلًا أُولَئِكَ لَهُمْ أَجْرُهُمْ عِنْدَ رَبِّهِمْ إِنَّ اللهَ سَرِيعُ الْحِسَابِ ۞ يَا أَيُّهَا الَّذِينَ آمَنُوا اصْبِرُوا وَصَابِرُوا وَرَابِطُوا وَاتَّقُوا اللهَ لَعَلَّكُمْ تُفْلِحُونَ. آل عمران 190 – 200');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.001.part.005.segment.002', 'dua.hisn.001.part.005', 2, 'transliteration', 'ar-Latn', 'Latn', '''Inna fee khalqis-samaawaati wal''ardhi wakhtilaafil-layli wannahaari la''aayaatil-li''oolil-''albaab. Allatheena yathkuroon-allaaha qiyaaman wa qu''oodan vua''alaa junoobihim wa yatafakkaroona fee khalqis-samaawaati wal''ardhi Rabbanaa maa khalaqta haathaa baatilan subhaanaka faqinaa''athaaban-naar. Rabbanaa''innaka man tudkhilin-naara faqad''akhzaytahu wa maa lidhdhalimeena rain''ansaar. Rabbanaa''innanaa sami''naa munaadiyan yunaadee lil''eemaani''an''aaminoo birabbikum fa''aamannaa, Rabbanaa faghfir lanaa thunoobanaa wa kaffir''annaa sayyi''aatinaa wa tawaffanaa ma''al-''abraar. Rabbanaa wa''aatinaa maa wa''adtanaa''alaa rusulika wa laa tukhzinaa yawmal-qiyaamati,''innaka laa tukhliful-mee''aad. Fastajaaba lahum Rabbuhum''annee laa''udhee''u''amala''aanulim-minkum min thakarin''aw''unthaa, ba''dhukum mim ba''dh, fallatheena haajaroo wa''ukhrijoo min diyaarihim wa''oothoo fee sabeelee wa qaataloo wa qutiloo la''ukaffiranna''anhum sayyi''aatihim wa la''udkhilannahum jannaatin tajree min tahtihal-''anhaaru thawaaban min''indillaah, wallaahu''indahu husnuth-thawaab. Laa yaghur-rannaka taqallubul-latheena kafaroo fil-bilaad. Mataa''un qaleelun thumma ma''waahum jahannam, wa bi''sal-mihaad. Laakinil-latheenat-taqaw Rabbahum lahumjannaatun tajree min tahtihal-''anhaaru khaalideena feehaa nuzulam-min''indillaah, wa maa''indallaahi khayrul-lil''abraar. Wa''inna min''ahlil-kitaabi laman yu''minu billaahi wa maa''unzila''ilaykum wa maa''unzila''ilayhim khaashi''eena lillaahi laa yashtaroona bi''aayaatillaahi thamanan qaleela,''oolaa''ika lahum''ajruhum''inda Rabbihim,''innallaaha saree''ul-hisaab. Yaa''ayyuhal-latheena''aamanus-biroo wa saabiroo wa raabitoo wattaqul-laaha la''allakum tuflihoon.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.001.part.005.segment.003', 'dua.hisn.001.part.005', 3, 'translation', 'en', 'Latn', 'Verily! In the creation of the heavens and the earth, and in the alternation of night and day, there are indeed Signs for men of understanding. Those who remember Allah standing, sitting and lying down on their sides, and think deeply about the creation of the heavens and the earth, (saying:)''Our LordA You. have not created this without purpose, glory is to You! Give us salvation from the torment of the Fire. Our Lord! Verily, whom You admit to the Fire, indeed, You have disgraced him, and never will the oppressors find any helpers. Our Lord! Verily, we have heard the call of one calling to Faith (saying:)''Believe in your Lord,''and we have believed. Our Lord! Forgive us our sins and expiate from us our evil deeds, and make us die in the state of righteousness together with the pious and righteous slaves. Our Lord! Grant us what You promised us through Your Messengers, and disgrace us not on the Day of Resurrection, for You never break (Your) promise.''So, their Lord answered them (saying):''Never will I allow to be lost the work of any of you, be he male or female. You issue forth one from another, so those who emigrated and were driven out from their homes, and suffered harm in My Cause and who fought, and were killed in My Cause, verily, I will expiate from them their evil deeds and admit them into Gardens under which rivers flow ; a reward from Allah , and with Allah is the best of rewards.''Let not the free disposal of the disbelievers through out the land deceive you. A brief enjoyment ; then , their ultimate abode is Hell ; and worst indeed is that place for rest. But , for those who fear their Lord, are Gardens under which rivers flow ; therein are they to dwell forever , and entertainment from Allah ; and that which is with Allah is the best for the pious and righteous slaves. And there are , certainly , among the people of the Scripture , those who believe in Allah and in that which has been revealed to you , and in that which has been revealed to them , hum bling themselves before Allah. They do not sell the Verses of Allah for a little price, for them is a reward with their Lord. Surely , Allah is Swift in account. O you who believe! Have patience and contend in patience, be vigilant and informed, and fear Allah , so that you may be successful.');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.002', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-002', 2, 'Supplication when wearing a garment', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.002.part.001', 'dua.hisn.002', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.002.part.001.segment.001', 'dua.hisn.002.part.001', 1, 'arabic', 'ar', 'Arab', 'الحمدُ للهِ الّذي كَساني هذا (الثّوب) وَرَزَقَنيه مِنْ غَـيـْرِ حَولٍ مِنّي وَلا قـوّة.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.002.part.001.segment.002', 'dua.hisn.002.part.001', 2, 'transliteration', 'ar-Latn', 'Latn', 'Alhamdu lillahil-lathee kasanee hatha (aththawb) warazaqaneehi min ghayri hawlin minnee wala quwwah.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.002.part.001.segment.003', 'dua.hisn.002.part.001', 3, 'translation', 'en', 'Latn', '‘All Praise is for Allah who has clothed me with this garment and provided it for me, with no power nor might from myself.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.003', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-003', 3, 'Supplication said when wearing a new garment', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.003.part.001', 'dua.hisn.003', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.003.part.001.segment.001', 'dua.hisn.003.part.001', 1, 'arabic', 'ar', 'Arab', 'اللّهُـمَّ لَـكَ الحَـمْـدُ أنْـتَ كَسَـوْتَنيهِ، أََسْأََلُـكَ مِـنْ خَـيرِهِ وَخَـيْرِ مَا صُنِعَ لَـه، وَأَعوذُ بِكَ مِـنْ شَـرِّهِ وَشَـرِّ مـا صُنِعَ لَـهُ.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.003.part.001.segment.002', 'dua.hisn.003.part.001', 2, 'transliteration', 'ar-Latn', 'Latn', 'Allahumma lakal-hamdu anta kasawtaneeh, as-aluka min khayrihi wakhayri ma suniAAa lah, wa-aAAoothu bika min sharrihi washarri ma suniAAa lah.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.003.part.001.segment.003', 'dua.hisn.003.part.001', 3, 'translation', 'en', 'Latn', '‘O Allah, for You is all praise, You have clothed me with it (i.e. the garment), I ask You for the good of it and the good for which it was made, and I seek refuge with You from the evil of it and the evil for which it was made.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.004', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-004', 4, 'Supplication said to someone wearing a new garment', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.004.part.001', 'dua.hisn.004', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.004.part.001.segment.001', 'dua.hisn.004.part.001', 1, 'arabic', 'ar', 'Arab', 'تُبْـلي وَيُـخْلِفُ اللهُ تَعَالى.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.004.part.001.segment.002', 'dua.hisn.004.part.001', 2, 'transliteration', 'ar-Latn', 'Latn', 'Tublee wayukhliful-lahu taAAala.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.004.part.001.segment.003', 'dua.hisn.004.part.001', 3, 'translation', 'en', 'Latn', '‘May you wear it out and Allah تعالى replace it (with another).’ The intended meaning: A supplication for long life. “');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.004.part.002', 'dua.hisn.004', 2);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.004.part.002.segment.001', 'dua.hisn.004.part.002', 1, 'arabic', 'ar', 'Arab', 'اِلبَـس جَديـداً وَعِـشْ حَمـيداً وَمُـتْ شهيداً');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.004.part.002.segment.002', 'dua.hisn.004.part.002', 2, 'transliteration', 'ar-Latn', 'Latn', 'Ilbas jadeedan waAAish hameedan wamut shaheedan.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.004.part.002.segment.003', 'dua.hisn.004.part.002', 3, 'translation', 'en', 'Latn', '‘Wear anew, live commendably and die a shaheed.’shaheed:One who dies fighting the kuffar in order to make the word of Allah superior or in defense of Islam.It also has other meanings found in the Sunnah such as: the one who dies defending his life, wealth or family; the woman who passes away due to childbirth; one who drownsetc.');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.005', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-005', 5, 'Before undressing', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.005.part.001', 'dua.hisn.005', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.005.part.001.segment.001', 'dua.hisn.005.part.001', 1, 'arabic', 'ar', 'Arab', 'بِسْمِ الله.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.005.part.001.segment.002', 'dua.hisn.005.part.001', 2, 'transliteration', 'ar-Latn', 'Latn', 'Bismil-lah');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.005.part.001.segment.003', 'dua.hisn.005.part.001', 3, 'translation', 'en', 'Latn', '‘In the name of Allah.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.006', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-006', 6, 'Before entering the toilet', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.006.part.001', 'dua.hisn.006', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.006.part.001.segment.001', 'dua.hisn.006.part.001', 1, 'arabic', 'ar', 'Arab', '(بِسْمِ الله) اللّهُـمَّ إِنِّـي أَعـوذُ بِـكَ مِـنَ الْخُـبْثِ وَالْخَبائِث.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.006.part.001.segment.002', 'dua.hisn.006.part.001', 2, 'transliteration', 'ar-Latn', 'Latn', '(Bismil-lah) allahumma innee aAAoothu bika minal-khubthi wal-khaba-ith');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.006.part.001.segment.003', 'dua.hisn.006.part.001', 3, 'translation', 'en', 'Latn', '‘(In the name of Allah).O Allah, I take refuge with you from all evil and evil-doers');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.007', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-007', 7, 'After leaving the toilet', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.007.part.001', 'dua.hisn.007', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.007.part.001.segment.001', 'dua.hisn.007.part.001', 1, 'arabic', 'ar', 'Arab', 'غُفْـرانَك.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.007.part.001.segment.002', 'dua.hisn.007.part.001', 2, 'transliteration', 'ar-Latn', 'Latn', 'Ghufranak');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.007.part.001.segment.003', 'dua.hisn.007.part.001', 3, 'translation', 'en', 'Latn', '‘I ask You (Allah) for forgiveness.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.008', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-008', 8, 'When starting ablution', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.008.part.001', 'dua.hisn.008', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.008.part.001.segment.001', 'dua.hisn.008.part.001', 1, 'arabic', 'ar', 'Arab', 'بِسْمِ الله.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.008.part.001.segment.002', 'dua.hisn.008.part.001', 2, 'transliteration', 'ar-Latn', 'Latn', 'Bismil-lah');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.008.part.001.segment.003', 'dua.hisn.008.part.001', 3, 'translation', 'en', 'Latn', '‘In the name of Allah.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.009', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-009', 9, 'Upon completing the ablution', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.009.part.001', 'dua.hisn.009', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.009.part.001.segment.001', 'dua.hisn.009.part.001', 1, 'arabic', 'ar', 'Arab', 'أَشْهَدُ أَنْ لا إِلَـهَ إِلاّ اللهُ وَحْدَهُ لا شَريـكَ لَـهُ وَأَشْهَدُ أَنَّ مُحَمّـداً عَبْـدُهُ وَرَسـولُـه.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.009.part.001.segment.002', 'dua.hisn.009.part.001', 2, 'transliteration', 'ar-Latn', 'Latn', 'Ashhadu an la ilaha illal-lahu wahdahu la shareeka lah, wa-ashhadu anna Muhammadan AAabduhu warasooluh.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.009.part.001.segment.003', 'dua.hisn.009.part.001', 3, 'translation', 'en', 'Latn', '‘I bear witness that none has the right to be worshipped except Allah, alone without partner, and I bear witness that Muhammad is His slave and Messenger.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.009.part.002', 'dua.hisn.009', 2);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.009.part.002.segment.001', 'dua.hisn.009.part.002', 1, 'arabic', 'ar', 'Arab', 'اللّهُـمَّ اجْعَلنـي مِنَ التَّـوّابينَ وَاجْعَـلْني مِنَ المتَطَهّـرين.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.009.part.002.segment.002', 'dua.hisn.009.part.002', 2, 'transliteration', 'ar-Latn', 'Latn', 'Allahummaj-AAalnee minat-tawwabeena wajAAalnee minal-mutatahhireen.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.009.part.002.segment.003', 'dua.hisn.009.part.002', 3, 'translation', 'en', 'Latn', '‘O Allah, make me of those who return to You often in repentance and make me of those who remain clean and pure.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.009.part.003', 'dua.hisn.009', 3);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.009.part.003.segment.001', 'dua.hisn.009.part.003', 1, 'arabic', 'ar', 'Arab', 'سُبْحـانَكَ اللّهُـمَّ وَبِحَمدِك أَشْهَـدُ أَنْ لا إِلهَ إِلاّ أَنْتَ أَسْتَغْفِرُكَ وَأَتوبُ إِلَـيْك.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.009.part.003.segment.002', 'dua.hisn.009.part.003', 2, 'transliteration', 'ar-Latn', 'Latn', 'Subhanakal-lahumma wabihamdika ashhadu an la ilaha illa anta astaghfiruka wa-atoobu ilayk.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.009.part.003.segment.003', 'dua.hisn.009.part.003', 3, 'translation', 'en', 'Latn', '‘How perfect You are O Allah, and I praise You, I bear witness that none has the right to be worshipped except You, I seek Your forgiveness and turn in repentance to You.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.010', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-010', 10, 'When leaving the home', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.010.part.001', 'dua.hisn.010', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.010.part.001.segment.001', 'dua.hisn.010.part.001', 1, 'arabic', 'ar', 'Arab', 'بِسْمِ اللهِ، تَوَكَّلْـتُ عَلى اللهِ وَلا حَوْلَ وَلا قُـوَّةَ إِلاّ بِالله.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.010.part.001.segment.002', 'dua.hisn.010.part.001', 2, 'transliteration', 'ar-Latn', 'Latn', 'Bismil-lah, tawakkaltu AAalal-lah, wala hawla wala quwwata illa billah.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.010.part.001.segment.003', 'dua.hisn.010.part.001', 3, 'translation', 'en', 'Latn', '‘In the name of Allah, I place my trust in Allah, and there is no might nor power except with Allah.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.010.part.002', 'dua.hisn.010', 2);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.010.part.002.segment.001', 'dua.hisn.010.part.002', 1, 'arabic', 'ar', 'Arab', 'اللّهُـمَّ إِنِّـي أَعـوذُ بِكَ أَنْ أَضِـلَّ أَوْ أُضَـل، أَوْ أَزِلَّ أَوْ أُزَل،أَوْ أَظْلِـمَ أَوْ أَُظْلَـم، أَوْ أَجْهَلَ أَوْ يُـجْهَلَ عَلَـيّ.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.010.part.002.segment.002', 'dua.hisn.010.part.002', 2, 'transliteration', 'ar-Latn', 'Latn', 'Allahumma innee aAAoothu bika an adilla aw odal, aw azilla aw ozall, aw athlima aw othlam, aw ajhala aw yujhala AAalay.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.010.part.002.segment.003', 'dua.hisn.010.part.002', 3, 'translation', 'en', 'Latn', '‘O Allah, I take refuge with You lest I should stray or be led astray, or slip or be tripped, or oppress or be oppressed, or behave foolishly or be treated foolishly.’slip: i.e. to commit a sin unintentionally');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.011', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-011', 11, 'Upon entering the home', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.011.part.001', 'dua.hisn.011', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.011.part.001.segment.001', 'dua.hisn.011.part.001', 1, 'arabic', 'ar', 'Arab', 'بِسْـمِ اللهِ وَلَجْنـا، وَبِسْـمِ اللهِ خَـرَجْنـا، وَعَلـى رَبِّنـا تَوَكّلْـنا.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.011.part.001.segment.002', 'dua.hisn.011.part.001', 2, 'transliteration', 'ar-Latn', 'Latn', 'Bismil-lahi walajna, wabismil-lahi kharajna, waAAala rabbina tawakkalna.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.011.part.001.segment.003', 'dua.hisn.011.part.001', 3, 'translation', 'en', 'Latn', '‘In the name of Allah we enter and in the name of Allah we leave, and upon our Lord we place our trust.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.012', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-012', 12, 'Supplication when going to the mosque', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.012.part.001', 'dua.hisn.012', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.012.part.001.segment.001', 'dua.hisn.012.part.001', 1, 'arabic', 'ar', 'Arab', 'اللّهُـمَّ اجْعَـلْ فِي قَلْبـي نُوراً، وَفي لِسَـانِي نُوراً، وَفِي سَمْعِي نُوراً, وَفِي بَصَرِيِ نُوراً, وَمِنْ فََوْقِي نُوراً , وَ مِنْ تَحْتِي نُوراً, وَ عَنْ يَمِينيِ نُوراَ, وعَنْ شِمَالِي نُوراً, وَمْن أَماَمِي نُوراً, وَمِنْ خَلْفيِ نُوراَ, واجْعَلْ فِي نَفْسِي نُوراً, وأَعْظِمْ لِي نُوراً, وَعظِّمْ لِي نُوراً, وَاجْعَلْ لِي نُوراً, واجْعَلنِي نُوراً, أللَّهُمَّ أَعْطِنِي نُوراً, واجْعَلْ فِي عَصَبِي نُوراً, وَفِي لَحْمِي نُوراً, وَفِي دَمِي نُوراً وَفِي شَعْرِي نُوراً, وفِي بَشَرِي نُوراً (أَللَّهُمَّ اجِعَلْ لِي نُوراً فِي قّبْرِي وَ نُوراَ فِي عِظاَمِي) (وَزِدْنِي نُوراً, وَزِدْنِي نُوراَ , وَزِدْنِي نُوراً) (وَهَبْ لِي نُوراً عَلَى نُوراً)');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.012.part.001.segment.002', 'dua.hisn.012.part.001', 2, 'transliteration', 'ar-Latn', 'Latn', 'Allaahummaj''al fee qalbee nooran, wa fee lisaaanee nooran, wa fee sam''ee nooran, wa fee basaree nooran, wa min fawqee nooran, wa min tahtee nooran, wa ''an yameenee nooran, wa ''an shimaalee nooran, wa min ''amaamee nooran, wa min khalfee nooran, waj''alfee nafsee nooran, wa ''a''dhim lee nooran, wa ''adhdhim lee nooran, wafal lee nooran, waj''alnee nooran, Allaahumma ''a''tinee nooran, waj''al fee ''asabee nooran, wafee lahmee nooran, wafee damee nooran, wa fee sha''ree nooran, wa fee basharee nooran. Allaahummaj''al lee nooran fee qabree wa nooran fee ''idhaamee. Wa zidnee nooran, wa zidnee nooran, wa zidnee nooran.Wa hab lee nooran ''alaa noor.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.012.part.001.segment.003', 'dua.hisn.012.part.001', 3, 'translation', 'en', 'Latn', 'O Allah, place light in my heart, and on my tongue light, and in my ears light and in my sight light, and above me light, and below me light, and to my right light, and to my left light, and before me light and behind me light. Place in my soul light. Magnify for me light, and amplify for me light. Make for me light and make me a light. O Allah, grant me light, and place light in my nerves, and in my body light and in my blood light and in my hair light and in my skin light.1 O Allah, make for me a light in my grave... and a light in my bones.. Increase me in light, increase me in light, increase me in light .');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.013', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-013', 13, 'Upon entering the mosque', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.013.part.001', 'dua.hisn.013', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.013.part.001.segment.001', 'dua.hisn.013.part.001', 1, 'arabic', 'ar', 'Arab', 'أَعوذُ باللهِ العَظيـم وَبِوَجْهِـهِ الكَرِيـم وَسُلْطـانِه القَديـم مِنَ الشّيْـطانِ الرَّجـيم، بِسْـمِ الله، وَالصَّلاةُ وَالسَّلامُ عَلى رَسولِ الله، اللّهُـمَّ افْتَـحْ لي أَبْوابَ رَحْمَتـِك.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.013.part.001.segment.002', 'dua.hisn.013.part.001', 2, 'transliteration', 'ar-Latn', 'Latn', 'aAAoothu billahil-AAatheem wabiwajhihil-kareem wasultanihil-qadeem minash-shaytanir-rajeem, bismil-lah, wassalatu wassalamu AAala rasoolil-lah , allahumma iftah lee abwaba rahmatik.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.013.part.001.segment.003', 'dua.hisn.013.part.001', 3, 'translation', 'en', 'Latn', '‘I take refuge with Allah, The Supreme and with His Noble Face, and His eternal authority from the accursed devil. In the name of Allah, and prayers and peace be upon the Messenger of Allah.O Allah, open the gates of Your mercy for me.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.014', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-014', 14, 'Upon leaving the mosque', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.014.part.001', 'dua.hisn.014', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.014.part.001.segment.001', 'dua.hisn.014.part.001', 1, 'arabic', 'ar', 'Arab', 'بِسمِ الله وَالصّلاةُ وَالسّلامُ عَلى رَسولِ الله، اللّهُـمَّ إِنّـي أَسْأَلُكَ مِـنْ فَضْـلِك، اللّهُـمَّ اعصِمْنـي مِنَ الشَّيْـطانِ الرَّجـيم.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.014.part.001.segment.002', 'dua.hisn.014.part.001', 2, 'transliteration', 'ar-Latn', 'Latn', 'Bismil-lah wassalatu wassalamu AAala rasoolil-lah, allahumma innee as-aluka min fadlik, allahumma iAAsimnee minash-shaytanir-rajeem.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.014.part.001.segment.003', 'dua.hisn.014.part.001', 3, 'translation', 'en', 'Latn', '‘In the name of Allah, and prayers and peace be upon the Messenger of Allah.O Allah, I ask You from Your favour.O Allah, guard me from the accursed devil.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.015', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-015', 15, 'Supplications related to the athan (the call to prayer)', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.015.part.001', 'dua.hisn.015', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.015.part.001.segment.001', 'dua.hisn.015.part.001', 1, 'comment', 'en', 'Latn', '‘One repeats just as the mu-aththin (one who calls to prayer) says, except when he says:');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.015.part.001.segment.002', 'dua.hisn.015.part.001', 2, 'arabic', 'ar', 'Arab', 'حَـيَّ عَلـى الصَّلاة (أَو) حَـيَّ عَلـى الْفَـلاح.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.015.part.001.segment.003', 'dua.hisn.015.part.001', 3, 'transliteration', 'ar-Latn', 'Latn', 'Hayya AAalas-salah (or) hayya AAalal-falah');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.015.part.001.segment.004', 'dua.hisn.015.part.001', 4, 'translation', 'en', 'Latn', '‘come to prayer, come to success’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.015.part.002', 'dua.hisn.015', 2);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.015.part.002.segment.001', 'dua.hisn.015.part.002', 1, 'comment', 'en', 'Latn', 'instead, one should say:');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.015.part.002.segment.002', 'dua.hisn.015.part.002', 2, 'arabic', 'ar', 'Arab', 'لا حَـوْلَ وَلا قُـوَّةَ إِلاّ بِالله.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.015.part.002.segment.003', 'dua.hisn.015.part.002', 3, 'transliteration', 'ar-Latn', 'Latn', 'La hawla wala quwwata illa billah.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.015.part.002.segment.004', 'dua.hisn.015.part.002', 4, 'translation', 'en', 'Latn', '‘There is no might nor power except with Allah.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.015.part.003', 'dua.hisn.015', 3);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.015.part.003.segment.001', 'dua.hisn.015.part.003', 1, 'comment', 'en', 'Latn', 'Immediately following the declaration of faith called by the mu-aththin');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.015.part.003.segment.002', 'dua.hisn.015.part.003', 2, 'comment', 'en', 'Latn', 'one says:');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.015.part.003.segment.003', 'dua.hisn.015.part.003', 3, 'arabic', 'ar', 'Arab', 'وَأَنا أَشْـهَدُ أَنْ لا إِلـهَ إِلاّ اللهُ وَحْـدَهُ لا شَـريكَ لَـه، وَأَنَّ محَمّـداً عَبْـدُهُ وَرَسـولُه، رَضيـتُ بِاللهِ رَبَّاً، وَبِمُحَمَّـدٍ رَسـولاً وَبِالإِسْلامِ دينَـاً.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.015.part.003.segment.004', 'dua.hisn.015.part.003', 4, 'transliteration', 'ar-Latn', 'Latn', 'Wa-ana ashhadu an la ilaha illal-lahu wahdahu la shareeka lah, wa-anna Muhammadan AAabduhu warasooluh, radeetu billahi rabban wabimuhammadin rasoolan wabil-islami deena.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.015.part.003.segment.005', 'dua.hisn.015.part.003', 5, 'translation', 'en', 'Latn', '‘And I too bear witness that none has the right to be worshipped except Allah, alone, without partner, and that Muhammad is His salve and Messenger.I am pleased with Allah as a Lord, and Muhammad as a Messenger and Islam as a religion.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.015.part.004', 'dua.hisn.015', 4);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.015.part.004.segment.001', 'dua.hisn.015.part.004', 1, 'arabic', 'ar', 'Arab', 'اللّهُـمَّ رَبَّ هَذِهِ الدّعْـوَةِ التّـامَّة وَالصّلاةِ القَـائِمَة آتِ محَـمَّداً الوَسيـلةَ وَالْفَضـيلَة وَابْعَـثْه مَقـامـاً مَحـموداً الَّذي وَعَـدْتَه إِنَّـكَ لا تُـخْلِفُ الميـعاد.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.015.part.004.segment.002', 'dua.hisn.015.part.004', 2, 'transliteration', 'ar-Latn', 'Latn', 'Allahumma rabba hathihid-daAAwatit-tammah, wassalatil-qa-imah ati Muhammadan alwaseelata wal-fadeelah, wabAAath-hu maqaman mahmoodan allathee waAAadtah, innaka la tukhliful-meeAAad.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.015.part.004.segment.003', 'dua.hisn.015.part.004', 3, 'translation', 'en', 'Latn', '‘One should then send prayers on the Prophet (saws) after answering the call of the mu-aththin’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.015.part.005', 'dua.hisn.015', 5);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.015.part.005.segment.001', 'dua.hisn.015.part.005', 1, 'comment', 'en', 'Latn', 'One should also supplicate for himself during the time between the athan and the iqamah as supplication at such time is not rejected.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.015.part.005.segment.002', 'dua.hisn.015.part.005', 2, 'translation', 'en', 'Latn', '‘O Allah, Owner of this perfect call and Owner of this prayer to be performed, bestow upon Muhammad al-waseelah and al-fadeelah and send him upon a praised platform which You have promised him.Verily, You never fail in Your promise.’al-waseelah: A station in paradise.al-fadeelah: A rank above the rest of creation.praised platform: One in which all of creation will praise him on, in order to bring about the account quickly and be relieved from the lengthy standing or the role of intercession.');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.016', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-016', 16, 'Supplication at the start of the prayer (after takbeer)', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.016.part.001', 'dua.hisn.016', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.016.part.001.segment.001', 'dua.hisn.016.part.001', 1, 'arabic', 'ar', 'Arab', 'اللّهُـمَّ باعِـدْ بَيـني وَبَيْنَ خَطـايايَ كَما باعَدْتَ بَيْنَ المَشْرِقِ وَالمَغْرِبْ، اللّهُـمَّ نَقِّنـي مِنْ خَطايايَ كَمـا يُـنَقَّى الثَّـوْبُ الأَبْيَضُ مِنَ الدَّنَسْ، اللّهُـمَّ اغْسِلْنـي مِنْ خَطايـايَ بِالثَّلـجِ وَالمـاءِ وَالْبَرَدْ.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.016.part.001.segment.002', 'dua.hisn.016.part.001', 2, 'transliteration', 'ar-Latn', 'Latn', 'Allahumma baAAid baynee wabayna khatayaya kama baAAadta baynal-mashriqi walmaghrib, allahumma naqqinee min khatayaya kama yunaqqath-thawbul-abyadu minad-danas, allahummagh-silnee min khatayaya biththalji walma/i walbarad.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.016.part.001.segment.003', 'dua.hisn.016.part.001', 3, 'translation', 'en', 'Latn', '‘O Allah, distance me from my sins just as You have distanced The East from The West, O Allah, purify me of my sins as a white robe is purified of filth, O Allah, cleanse me of my sins with snow, water, and ice.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.016.part.002', 'dua.hisn.016', 2);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.016.part.002.segment.001', 'dua.hisn.016.part.002', 1, 'arabic', 'ar', 'Arab', 'سُبْـحانَكَ اللّهُـمَّ وَبِحَمْـدِكَ وَتَبارَكَ اسْمُـكَ وَتَعـالى جَـدُّكَ وَلا إِلهَ غَيْرُك.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.016.part.002.segment.002', 'dua.hisn.016.part.002', 2, 'transliteration', 'ar-Latn', 'Latn', 'Subhanakal-lahumma wabihamdika watabarakas-muka wataAAala jadduka wala ilaha ghayruk.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.016.part.002.segment.003', 'dua.hisn.016.part.002', 3, 'translation', 'en', 'Latn', '‘How perfect You are O Allah, and I praise You.Blessed be Your name, and lofty is Your position and none has the right to be worshipped except You.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.016.part.003', 'dua.hisn.016', 3);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.016.part.003.segment.001', 'dua.hisn.016.part.003', 1, 'arabic', 'ar', 'Arab', 'وَجَّهـتُ وَجْهِـيَ لِلَّذي فَطَرَ السَّمـواتِ وَالأَرْضَ حَنـيفَاً وَمـا أَنا مِنَ المشْرِكين، إِنَّ صَلاتـي، وَنُسُكي، وَمَحْـيايَ، وَمَماتـي للهِ رَبِّ العالَمين، لا شَريـكَ لَهُ وَبِذلكَ أُمِرْتُ وَأَنا مِنَ المسْلِـمين. اللّهُـمَّ أَنْتَ المَلِكُ لا إِلهَ إِلاّ أَنْت،أَنْتَ رَبِّـي وَأَنـا عَبْـدُك، ظَلَمْـتُ نَفْسـي وَاعْـتَرَفْتُ بِذَنْبـي فَاغْفِرْ لي ذُنوبي جَميعاً إِنَّـه لا يَغْـفِرُ الذُّنـوبَ إلاّ أَنْت.وَاهْدِنـي لأَحْسَنِ الأَخْلاقِ لا يَهْـدي لأَحْسَـنِها إِلاّ أَنْـت، وَاصْـرِف عَـنّْي سَيِّئَهـا، لا يَصْرِفُ عَـنّْي سَيِّئَهـا إِلاّ أَنْـت، لَبَّـيْكَ وَسَعْـدَيْك، وَالخَـيْرُ كُلُّـهُ بِيَـدَيْـك، وَالشَّرُّ لَيْـسَ إِلَـيْك، أَنا بِكَ وَإِلَيْـك، تَبـارَكْتَ وَتَعـالَيتَ أَسْتَغْـفِرُكَ وَأَتوبُ إِلَـيك.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.016.part.003.segment.002', 'dua.hisn.016.part.003', 2, 'transliteration', 'ar-Latn', 'Latn', 'Wajjahtu wajhiya lillathee fataras-samawati wal-arda haneefan wama ana minal-mushrikeen, inna salatee wanusukee wamahyaya wamamatee lillahi rabbil-AAalameen, la shareeka lahu wabithalika omirtu wa-ana minal-muslimeen. Allahumma antal-maliku la ilaha illa ant. anta rabbee wa-ana AAabduk, thalamtu nafsee waAAtaraftu bithanbee faghfir lee thunoobee jameeAAan innahu la yaghfiruth-thunooba illa ant.wahdinee li-ahsanil-akhlaqi la yahdee li-ahsaniha illa ant, wasrif AAannee sayyi-aha la yasrifu AAannee sayyi-aha illa ant, labbayka wasaAAdayk,walkhayru kulluhu biyadayk, washsharru laysa ilayk, ana bika wa-ilayk, tabarakta wataAAalayt, astaghfiruka wa-atoobu ilayk.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.016.part.003.segment.003', 'dua.hisn.016.part.003', 3, 'translation', 'en', 'Latn', '‘I have turned my face sincerely towards He who has brought forth the heavens and the Earth and I am not of those who associate (others with Allah).Indeed my prayer, my sacrifice, my life and my death are for Allah, Lord of the worlds, no partner has He, with this I am commanded and I am of the Muslims. O Allah, You are the Sovereign, none has the right to be worshipped except You.You are my Lord and I am Your servant, I have wronged my own soul and have acknowledged my sin, so forgive me all my sins for no one forgives sins except You.Guide me to the best of characters for none can guide to it other than You, and deliver me from the worst of characters for none can deliver me from it other than You.Here I am, in answer to Your call, happy to serve you.All good is within Your hands and evil does not stem from You.I exist by your will and will return to you.Blessed and High are You, I seek Your forgiveness and repent unto You.’Allah does not create pure evil which does not have any good or contain any benefit, wisdom or mercy at all, nor does He punish anyone without having commited a sin. Something can be good in terms of its creation when viewed in a particularperspective and at the same time be evil when viewed in another way. Allah created the devil and by him, He tests His servants, so there are those who hate the devil, fight him and his way and they stand at enmity towards him and his followers and there are others who are at allegiance with the devil and follow his steps. So evil exists in His creatures by His will and wisdom, not in His actions or act of creating.');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.016.part.004', 'dua.hisn.016', 4);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.016.part.004.segment.001', 'dua.hisn.016.part.004', 1, 'arabic', 'ar', 'Arab', 'اللّهُـمَّ رَبَّ جِـبْرائيل، وَميكـائيل، وَإِسْـرافيل، فاطِـرَ السَّمواتِ وَالأَرْض، عالـِمَ الغَيْـبِ وَالشَّهـادَةِ أَنْـتَ تَحْـكمُ بَيْـنَ عِبـادِكَ فيـما كانوا فيهِ يَخْتَلِفـون. اهدِنـي لِمـا اخْتُـلِفَ فيـهِ مِنَ الْحَـقِّ بِإِذْنِك، إِنَّـكَ تَهْـدي مَنْ تَشـاءُ إِلى صِراطٍ مُسْتَقـيم.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.016.part.004.segment.002', 'dua.hisn.016.part.004', 2, 'transliteration', 'ar-Latn', 'Latn', 'Allahumma rabba jibra-eel, wameeka-eel, wa-israfeel fatiras-samawati walard, AAalimal-ghaybi washshahadah, anta tahkumu bayna AAibadika feema kanoo feehi yakhtalifoon. ihdinee limakh-tulifa feehi minal-haqqi bi-ithnik, innaka tahdee man tasha-o ila siratin mustaqeem.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.016.part.004.segment.003', 'dua.hisn.016.part.004', 3, 'translation', 'en', 'Latn', '‘O Allah, Lord of Jibra-eel, Meeka-eel and Israfeel (great angles), Creator of the heavens and the Earth, Knower of the seen and the unseen.You are the arbitratorbetween Your servants in that which they have disputed.Guide me to the truth by Your leave, in that which they have differed, for verily You guide whom You will to a straight path.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.016.part.005', 'dua.hisn.016', 5);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.016.part.005.segment.001', 'dua.hisn.016.part.005', 1, 'arabic', 'ar', 'Arab', 'اللهُ أَكْبَـرُ كَبـيرا، اللهُ أَكْبَـرُ كَبـيرا، اللهُ أَكْبَـرُ كَبـيرا، وَالْحَـمْدُ للهِ كَثـيرا، وَالْحَـمْدُ للهِ كَثـيرا، وَالْحَـمْدُ للهِ كَثـيرا، وَسُبْـحانَ اللهِ بكْـرَةً وَأَصيـلا. (ثَلاثاً)');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.016.part.006', 'dua.hisn.016', 6);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.016.part.006.segment.001', 'dua.hisn.016.part.006', 1, 'arabic', 'ar', 'Arab', 'أَعـوذُ بِاللهِ مِنَ الشَّـيْطانِ مِنْ نَفْخِـهِ وَنَفْـثِهِ وَهَمْـزِه.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.016.part.006.segment.002', 'dua.hisn.016.part.006', 2, 'transliteration', 'ar-Latn', 'Latn', 'Allahu akbaru kabeera, Allahu akbaru kabeera, Allahu akbaru kabeera, walhamdu lillahi katheera, walhamdu lillahi katheera, walhamdu lillahi katheera, wasubhanal-lahi bukratan wa-aseela. (three times)aAAoothu billahi minash-shaytani min nafkhihi wanafthihi wahamzih.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.016.part.006.segment.003', 'dua.hisn.016.part.006', 3, 'translation', 'en', 'Latn', '‘Allah is Most Great, Allah is Most Great, Allah is Most Great, much praise is for Allah, much praise is for Allah, much praise is for Allah, and I declare the perfection of Allah in the early morning and in the late afternoon.’(three times)');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.016.part.007', 'dua.hisn.016', 7);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.016.part.007.segment.001', 'dua.hisn.016.part.007', 1, 'comment', 'en', 'Latn', '’, The Prophet (saws) would say (as an opening supplication in prayer) when rising from sleep to perform prayers during the night:');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.016.part.007.segment.002', 'dua.hisn.016.part.007', 2, 'arabic', 'ar', 'Arab', 'اللّهُـمَّ لَكَ الْحَمْدُ أَنْتَ نـورُ السَّمـواتِ وَالأَرْضِ وَمَنْ فيـهِن، وَلَكَ الْحَمْدُ أَنْتَ قَـيِّمُ السَّـمواتِ وَالأَرْضِ وَمَنْ فيـهِن، وَلَكَ الْحَمْدُ أَنْتَ رَبُّ السَّـمواتِ وَالأَرْضِ وَمَنْ فيـهِن وَلَكَ الْحَمْدُ لَكَ مُلْـكُ السَّـمواتِ وَالأَرْضِ وَمَنْ فيـهِن وَلَكَ الْحَمْدُ أَنْتَ مَلِـكُ السَّـمواتِ وَالأَرْضِ  وَلَكَ الْحَمْدُ أَنْتَ الْحَـقّ وَوَعْـدُكَ الْحَـق، وَقَوْلُـكَ الْحَـق، وَلِقـاؤُكَ الْحَـق، وَالْجَـنَّةُحَـق، وَالنّـارُ حَـق، وَالنَّبِـيّونَ حَـق، وَمـحَمَّدٌحَـق، وَالسّـاعَةُحَـقاللّهُـمَّ لَكَ أَسْلَمت، وَعَلَـيْكَ تَوَكَّلْـت، وَبِكَ آمَنْـت، وَإِلَـيْكَ أَنَبْـت، وَبِـكَ خاصَمْت، وَإِلَـيْكَ حاكَمْـت. فاغْفِـرْ لي مـا قَدَّمْتُ، وَما أَخَّـرْت، وَما أَسْـرَرْت، وَما أَعْلَـنْت أَنْتَ المُقَـدِّمُ وَأَنْتَ المُـؤَخِّر، لا إِاـهَ إِلاّ أَنْـتأَنْـتَ إِلـهي لا إِاـهَ إِلاّ أَنْـت.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.016.part.007.segment.003', 'dua.hisn.016.part.007', 3, 'transliteration', 'ar-Latn', 'Latn', 'Allahumma lakal-hamd anta noorus-samawati wal-ardi waman feehin, walakal-hamd, anta qayyimus-samawati walardi waman feehin, walakal-hamd, anta rabbus-samawati walardi waman feehin, walakal-hamd, laka mulkus-samawati walardi waman feehin walakal-hamd, anta malikus-samawati walard walakal-hamd antal-haq, wawaAAdukal-haq, waqawlukal-haq, waliqa-okal-haq, waljannatu haq wannaru haq, wannabiyyoona haq, wa Muhammadun haq, wassaAAatu haq allahumma laka aslamt, waAAalayka tawakkalt, wabika amant, wa-ilayka anabt, wabika khasamt, wa-ilayka hakamt, faghfir lee ma qaddamt, wama akhkhart, wama asrart, wama aAAlant antal-muqaddim, wa-antal-mu-akhkhir, la ilaha illa ant anta ilahee la ilaha illa ant.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.016.part.007.segment.004', 'dua.hisn.016.part.007', 4, 'translation', 'en', 'Latn', '‘I take refuge with Allah from the devil, from his pride, his poetry and his madness.');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.016.part.008', 'dua.hisn.016', 8);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.016.part.008.segment.001', 'dua.hisn.016.part.008', 1, 'translation', 'en', 'Latn', '‘O Allah, to You belongs all praise, You are the Light of the heavens and the Earth and all that is within them.To You belongs all praise, You are the Sustainer of the heavens and the Earth and all that is within them.To You belongs all praise.You are Lord of the heavens and the Earth and all that is within them.To You belongs all praise and the kingdom of the heavens and the Earth and all that is within them.To You belongs all praise, You are the King of the heavens and the Earth and to You belongs all praise. You are The Truth, Your promise is true, your Word is true, and the Day in which we will encounter You is true, the Garden of Paradise is true and the Fire is true, and the Prophet (saws)s are true, Muhammadis true and the Final Hour is true.O Allah, unto You I have submitted, and upon You I have relied, and in You I have believed, and to You I have turned in repentance, and over You I have disputed, and to You I have turned for judgment.So forgive me for what has come to pass of my sins and what will come to pass, and what I have hidden and what I have made public.You are Al-Muqaddim and Al-Mu-akhkhir. None has the right to be worshipped except You, You are my Deity, none has the right to be worshipped except You.’Meaning of Al-Muqaddim and Al-Mu-akhkhir: Allah puts forward and favours whom He wills from amongst His creation just as He defers and holds back whom He wills in accordance to His wisdom.E.g. Favouring man over the rest of creation, favouring the Prophet (saws)s over the rest of mankind, favouring Muhammadover all the Prophet (saws)s and Messengersetc.');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.017', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-017', 17, 'While bowing in prayer (rukooAA)', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.017.part.001', 'dua.hisn.017', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.017.part.001.segment.001', 'dua.hisn.017.part.001', 1, 'arabic', 'ar', 'Arab', 'سُبْـحانَ رَبِّـيَ الْعَظـيم. (ثلاثاً)');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.017.part.001.segment.002', 'dua.hisn.017.part.001', 2, 'transliteration', 'ar-Latn', 'Latn', 'Subhana rabbiyal-AAatheem (three times)');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.017.part.001.segment.003', 'dua.hisn.017.part.001', 3, 'translation', 'en', 'Latn', '‘How perfect my Lord is, The Supreme.’(three times)');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.017.part.002', 'dua.hisn.017', 2);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.017.part.002.segment.001', 'dua.hisn.017.part.002', 1, 'arabic', 'ar', 'Arab', 'سُبْـحانَكَ اللّهُـمَّ رَبَّـنا وَبِحَـمْدِك، اللّهُـمَّ اغْفِـرْ لي.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.017.part.002.segment.002', 'dua.hisn.017.part.002', 2, 'transliteration', 'ar-Latn', 'Latn', 'Subhanakal-lahumma rabbana wabihamdik, allahummagh-fir lee');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.017.part.002.segment.003', 'dua.hisn.017.part.002', 3, 'translation', 'en', 'Latn', '‘How perfect You are O Allah, our Lord and I praise You.O Allah, forgive me.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.017.part.003', 'dua.hisn.017', 3);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.017.part.003.segment.001', 'dua.hisn.017.part.003', 1, 'arabic', 'ar', 'Arab', 'سُبـّوحٌ قُـدّْوس، رَبُّ الملائِكَـةِ وَالـرُّوح.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.017.part.003.segment.002', 'dua.hisn.017.part.003', 2, 'transliteration', 'ar-Latn', 'Latn', 'Subboohun quddoos, rabbul-mala-ikati warrooh.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.017.part.003.segment.003', 'dua.hisn.017.part.003', 3, 'translation', 'en', 'Latn', '‘Perfect and Holy (He is), Lord of the angles and the Rooh (i.e. Jibra-eel).’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.017.part.004', 'dua.hisn.017', 4);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.017.part.004.segment.001', 'dua.hisn.017.part.004', 1, 'arabic', 'ar', 'Arab', 'اللّهُـمَّ لَكَ رَكَـعْتُ وَبِكَ آمَـنْت، ولَكَ أَسْلَـمْت، خَشَـعَ لَكَ سَمْـعي، وَبَصَـري، وَمُخِّـي، وَعَظْمـي، وَعَصَـبي، وَما استَقَـلَّ بِهِ قَدَمي.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.017.part.004.segment.002', 'dua.hisn.017.part.004', 2, 'transliteration', 'ar-Latn', 'Latn', 'Allahumma laka rakaAAt, wabika amant, walaka aslamt, khashaAAa laka samAAee, wabasaree, wamukhkhee, waAAathmee, waAAasabee, wamas-taqalla bihi qadamee.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.017.part.004.segment.003', 'dua.hisn.017.part.004', 3, 'translation', 'en', 'Latn', '‘O Allah, unto You I have bowed, and in You I have believed, and to You I have submitted. My hearing, sight, mind, bones, tendons and what my feet carry are humbled before You.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.017.part.005', 'dua.hisn.017', 5);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.017.part.005.segment.001', 'dua.hisn.017.part.005', 1, 'arabic', 'ar', 'Arab', 'سُبْـحانَ ذي الْجَبَـروت،والمَلَـكوت، وَالكِبْـرِياء، وَالْعَظَـمَه.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.017.part.005.segment.002', 'dua.hisn.017.part.005', 2, 'transliteration', 'ar-Latn', 'Latn', 'Subhana thil-jabaroot, walmalakoot, walkibriya/, walAAathamah.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.017.part.005.segment.003', 'dua.hisn.017.part.005', 3, 'translation', 'en', 'Latn', '‘How perfect He is, The Possessor of total power, sovereignty, magnificence and grandeur.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.018', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-018', 18, 'Upon rising from the bowing posision', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.018.part.001', 'dua.hisn.018', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.018.part.001.segment.001', 'dua.hisn.018.part.001', 1, 'arabic', 'ar', 'Arab', 'سَمِـعَ اللهُ لِمَـنْ حَمِـدَه.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.018.part.001.segment.002', 'dua.hisn.018.part.001', 2, 'transliteration', 'ar-Latn', 'Latn', 'SamiAAal-lahu liman hamidah');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.018.part.001.segment.003', 'dua.hisn.018.part.001', 3, 'translation', 'en', 'Latn', '‘May Allah answer he who praises Him.’This supplication is to be made while rising.');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.018.part.002', 'dua.hisn.018', 2);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.018.part.002.segment.001', 'dua.hisn.018.part.002', 1, 'arabic', 'ar', 'Arab', 'رَبَّنـا وَلَكَ الحَمْـدُ حَمْـداً كَثـيراً طَيِّـباً مُـبارَكاً فيه.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.018.part.002.segment.002', 'dua.hisn.018.part.002', 2, 'transliteration', 'ar-Latn', 'Latn', 'Rabbana walakal-hamdu hamdan katheeran tayyiban mubarakan feeh.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.018.part.002.segment.003', 'dua.hisn.018.part.002', 3, 'translation', 'en', 'Latn', '‘Our Lord, for You is all praise, an abundant beautiful blessed praise.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.018.part.003', 'dua.hisn.018', 3);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.018.part.003.segment.001', 'dua.hisn.018.part.003', 1, 'arabic', 'ar', 'Arab', 'مِلْءَ السَّمـواتِ وَمِلْءَ الأَرْض، وَما بَيْـنَهُمـا، وَمِلْءَ ما شِئْـتَ مِنْ شَيءٍ بَعْـدْ. أَهـلَ الثَّـناءِ وَالمَجـدْ، أََحَـقُّ ما قالَ العَبْـد، وَكُلُّـنا لَكَ عَـبدْ. اللّهُـمَّ لا مانِعَ لِما أَعْطَـيْت، وَلا مُعْطِـيَ لِما مَنَـعْت، وَلا يَنْفَـعُ ذا الجَـدِّ مِنْـكَ الجَـد.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.018.part.003.segment.002', 'dua.hisn.018.part.003', 2, 'transliteration', 'ar-Latn', 'Latn', 'Mil-as-samawati wamil-al-ard, wama baynahuma, wamil/a ma shi/ta min shay-in baAAd, ahlath-thana-i walmajd, ahaqqu ma qalal-AAabd, wakulluna laka AAabd. Allahumma la maniAAa lima aAAtayt, wala muAAtiya lima manaAAt, wala yanfaAAu thal-jaddi minkal-jad.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.018.part.003.segment.003', 'dua.hisn.018.part.003', 3, 'translation', 'en', 'Latn', '‘The heavens and the Earth and all between them abound with Your praises, and all that You will abounds with Your praises. O Possessor of praise and majesty, the truest thing a slave has said (of You) and we are all Your slaves.O Allah, none can prevent what You have willed to bestow and none can bestow what You have willed to prevent, and no wealth or majesty can benefit anyone, as from You is all wealth and majesty.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.018.part.004', 'dua.hisn.018', 4);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.018.part.004.segment.001', 'dua.hisn.018.part.004', 1, 'comment', 'en', 'Latn', 'This supplication is made optionally only in conjunction with the previous one.');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.019', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-019', 19, 'Supplication whilst prostrating (sujood)', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.019.part.001', 'dua.hisn.019', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.019.part.001.segment.001', 'dua.hisn.019.part.001', 1, 'arabic', 'ar', 'Arab', 'سُبْـحانَ رَبِّـيَ الأَعْلـى. (ثلاثاً)');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.019.part.001.segment.002', 'dua.hisn.019.part.001', 2, 'transliteration', 'ar-Latn', 'Latn', 'Subhana rabbiyal-aAAla. (three times)');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.019.part.001.segment.003', 'dua.hisn.019.part.001', 3, 'translation', 'en', 'Latn', '‘How perfect my Lord is, The Most High.’(three times)');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.019.part.002', 'dua.hisn.019', 2);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.019.part.002.segment.001', 'dua.hisn.019.part.002', 1, 'arabic', 'ar', 'Arab', 'سُبْـحانَكَ اللّهُـمَّ رَبَّـنا وَبِحَـمْدِكَ، اللّهُـمَّ اغْفِرْ لي.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.019.part.002.segment.002', 'dua.hisn.019.part.002', 2, 'transliteration', 'ar-Latn', 'Latn', 'Subhanakal-lahumma rabbana wabihamdik, allahummagh- fir lee.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.019.part.002.segment.003', 'dua.hisn.019.part.002', 3, 'translation', 'en', 'Latn', '‘How perfect You are O Allah, our Lord, and I praise You. O Allah, forgive me.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.019.part.003', 'dua.hisn.019', 3);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.019.part.003.segment.001', 'dua.hisn.019.part.003', 1, 'arabic', 'ar', 'Arab', 'سُبـّوحٌ قُـدّوس، رَبُّ الملائِكَـةِ وَالـرُّوح.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.019.part.003.segment.002', 'dua.hisn.019.part.003', 2, 'transliteration', 'ar-Latn', 'Latn', 'Subbohoon quddos, rabbul-mala-ikati warrooh.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.019.part.003.segment.003', 'dua.hisn.019.part.003', 3, 'translation', 'en', 'Latn', '‘Perfect and Holy (He is), Lord of the angles and the Rooh (i.e. Jibra-eel).');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.019.part.004', 'dua.hisn.019', 4);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.019.part.004.segment.001', 'dua.hisn.019.part.004', 1, 'comment', 'en', 'Latn', '’');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.019.part.004.segment.002', 'dua.hisn.019.part.004', 2, 'arabic', 'ar', 'Arab', 'اللّهُـمَّ لَكَ سَـجَدْتُ وَبِـكَ آمَنْـت، وَلَكَ أَسْلَـمْت، سَجَـدَ وَجْهـي للَّـذي خَلَقَـهُ وَصَـوَّرَهُ وَشَقَّ سَمْـعَـهُ وَبَصَـرَه، تَبـارَكَ اللهُ أَحْسـنُ الخـالِقيـن.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.019.part.004.segment.003', 'dua.hisn.019.part.004', 3, 'transliteration', 'ar-Latn', 'Latn', 'Allahumma laka sajadt, wabika amant, walaka aslamt, sajada wajhee lillathee khalaqahu wasawwarahu washaqqa samAAahu wabasarahu, tabarakal-lahu ahsanul-khaliqeen.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.019.part.004.segment.004', 'dua.hisn.019.part.004', 4, 'translation', 'en', 'Latn', '‘O Allah, unto You I have prostrated and in You I have believed, and unto You I have submitted. My face has prostrated before He Who created it and fashioned it, and brought forth its faculties of hearing and seeing. Blessed is Allah, the Best of creators.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.019.part.005', 'dua.hisn.019', 5);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.019.part.005.segment.001', 'dua.hisn.019.part.005', 1, 'arabic', 'ar', 'Arab', 'سُبْـحانَ ذي الْجَبَـروت، والمَلَكـوت، والكِبْـرِياء، وَالعَظَمَـه.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.019.part.005.segment.002', 'dua.hisn.019.part.005', 2, 'transliteration', 'ar-Latn', 'Latn', 'Subhana thil-jabaroot, walmalakoot, walkibriya/, walAAathamah.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.019.part.005.segment.003', 'dua.hisn.019.part.005', 3, 'translation', 'en', 'Latn', '‘How perfect He is, The Possessor of total power, sovereignty, magnificence and grandeur.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.019.part.006', 'dua.hisn.019', 6);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.019.part.006.segment.001', 'dua.hisn.019.part.006', 1, 'arabic', 'ar', 'Arab', 'اللّهُـمَّ اغْفِـرْ لي ذَنْـبي كُلَّـه، دِقَّـهُ وَجِلَّـه، وَأَوَّلَـهُ وَآخِـرَه وَعَلانِيَّتَـهُ وَسِـرَّه.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.019.part.006.segment.002', 'dua.hisn.019.part.006', 2, 'transliteration', 'ar-Latn', 'Latn', 'Allahummagh-fir lee thanbee kullah, diqqahu wajillah, wa-awwalahu wa-akhirah, wa- AAalaniyyatahu wa-sirrah.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.019.part.006.segment.003', 'dua.hisn.019.part.006', 3, 'translation', 'en', 'Latn', '‘O Allah, forgive me all of my sins, the small and great of them, the first and last of them, and the seen and hidden of them.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.019.part.007', 'dua.hisn.019', 7);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.019.part.007.segment.001', 'dua.hisn.019.part.007', 1, 'arabic', 'ar', 'Arab', 'اللّهُـمَّ إِنِّـي أَعـوذُ بِرِضـاكَ مِنْ سَخَطِـك، وَبِمعـافاتِـكَ مِنْ عُقوبَـتِك، وَأَعـوذُ بِكَ مِنْـك، لا أُحْصـي ثَنـاءً عَلَـيْك، أَنْـتَ كَمـا أَثْنَـيْتَ عَلـى نَفْسـِك.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.019.part.007.segment.002', 'dua.hisn.019.part.007', 2, 'transliteration', 'ar-Latn', 'Latn', 'Allahumma innee aAAoothu biridaka min sakhatik, wa-bimuAAafatika min AAuqoobatik, wa-aAAoothu bika mink, la ohsee thana-an AAalayk, anta kama athnayta AAala nafsik.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.019.part.007.segment.003', 'dua.hisn.019.part.007', 3, 'translation', 'en', 'Latn', '‘O Allah, I take refuge within Your pleasure from Your displeasure and within Your pardon from Your punishment, and I take refuge in You from You. I cannot enumerate Your praise, You are as You have praised Yourself.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.020', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-020', 20, 'Supplication between the two prostrations', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.020.part.001', 'dua.hisn.020', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.020.part.001.segment.001', 'dua.hisn.020.part.001', 1, 'arabic', 'ar', 'Arab', 'رَبِّ اغْفِـرْ لي، رَبِّ اغْفِـرْ لي.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.020.part.001.segment.002', 'dua.hisn.020.part.001', 2, 'transliteration', 'ar-Latn', 'Latn', 'Rabbigh-fir lee, rabbigh-fir lee.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.020.part.001.segment.003', 'dua.hisn.020.part.001', 3, 'translation', 'en', 'Latn', '‘My Lord forgive me, My Lord forgive me.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.020.part.002', 'dua.hisn.020', 2);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.020.part.002.segment.001', 'dua.hisn.020.part.002', 1, 'arabic', 'ar', 'Arab', 'اللّهُـمَّ اغْفِـرْ لي، وَارْحَمْـني، وَاهْدِنـي، وَاجْبُرْنـي، وَعافِنـي وَارْزُقْنـي وَارْفَعْـني.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.020.part.002.segment.002', 'dua.hisn.020.part.002', 2, 'transliteration', 'ar-Latn', 'Latn', 'Allahummagh-fir lee, warhamnee, wahdinee, wajburnee, waAAafinee, warzuqnee warfaAAnee.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.020.part.002.segment.003', 'dua.hisn.020.part.002', 3, 'translation', 'en', 'Latn', '‘O Allah, forgive me, have mercy upon me, guide me, enrich me, give me health, grant me sustenance and raise my rank.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.021', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-021', 21, 'Supplication when prostrating due to recitation of the Quran', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.021.part.001', 'dua.hisn.021', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.021.part.001.segment.001', 'dua.hisn.021.part.001', 1, 'arabic', 'ar', 'Arab', 'سَجَـدَ وَجْهـي للَّـذي خَلَقَـهُ وَصَـوَّرَهُ وَشَقَّ سَمْـعَـهُ وَبَصَـرَهُ بِحَـوْلِـهِ وَقُـوَّتِهِ تَبـارَكَ اللهُ أَحْسَـنُ الخـالِقيـن.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.021.part.001.segment.002', 'dua.hisn.021.part.001', 2, 'transliteration', 'ar-Latn', 'Latn', 'Sajada wajhee lillathee khalaqahu washaqqa samAAahu wabasarahu bihawlihi waquwwatih{ tabaraka Allahu ahsanu alkhaliqeen}.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.021.part.001.segment.003', 'dua.hisn.021.part.001', 3, 'translation', 'en', 'Latn', '‘My face fell prostrate before He who created it and brought forth its faculties of hearing and seeing by His might and power.<< So Blessed is Allah, the best of creators. >>’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.021.part.002', 'dua.hisn.021', 2);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.021.part.002.segment.001', 'dua.hisn.021.part.002', 1, 'arabic', 'ar', 'Arab', 'اللّهُـمَّ اكْتُـبْ لي بِهـا عِنْـدَكَ أَجْـراً، وَضَـعْ عَنِّـي بِهـا وِزْراً، وَاجْعَـلها لي عِنْـدَكَ ذُخْـراً، وَتَقَبَّـلها مِنِّـي كَمـا تَقَبَّلْتَـها مِنْ عَبْـدِكَ داود.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.021.part.002.segment.002', 'dua.hisn.021.part.002', 2, 'transliteration', 'ar-Latn', 'Latn', 'Allahummak-tub lee bihaAAindaka ajra, wadaAAAAannee biha wizra, wajAAalha lee AAindaka thukhra, wataqabbalha minnee kama taqabbaltaha min AAabdika Dawood.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.021.part.002.segment.003', 'dua.hisn.021.part.002', 3, 'translation', 'en', 'Latn', '‘O Allah, record for me a reward for this (prostration), and remove from me a sin.Save it for me and accept it from me just as You had accepted it from Your servant Dawood.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.022', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-022', 22, 'The Tashahhud', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.022.part.001', 'dua.hisn.022', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.022.part.001.segment.001', 'dua.hisn.022.part.001', 1, 'comment', 'en', 'Latn', 'Tashahhud: what one says in the sitting position in prayer');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.022.part.001.segment.002', 'dua.hisn.022.part.001', 2, 'arabic', 'ar', 'Arab', 'التَّحِيّـاتُ للهِ وَالصَّلَـواتُ والطَّيِّـبات، السَّلامُ عَلَيـكَ أَيُّهـا النَّبِـيُّ وَرَحْمَـةُ اللهِ وَبَرَكـاتُه، السَّلامُ عَلَيْـنا وَعَلـى عِبـادِ للهِ الصَّـالِحـين. أَشْـهَدُ أَنْ لا إِلـهَ إِلاّ الله، وَأَشْـهَدُ أَنَّ مُحَمّـداً عَبْـدُهُ وَرَسـولُه');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.022.part.001.segment.003', 'dua.hisn.022.part.001', 3, 'transliteration', 'ar-Latn', 'Latn', 'Attahiyyatu lillahi wassalawatu wattayyibat, assalamu AAalayka ayyuhan-nabiyyu warahmatul-lahi wabarakatuh, assalamu AAalayna waAAala AAibadil-lahis-saliheen. Ash-hadu an la ilaha illal-lah, wa-ashhadu anna Muhammadan AAabduhu warasooluh.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.022.part.001.segment.004', 'dua.hisn.022.part.001', 4, 'translation', 'en', 'Latn', '‘At-tahiyyat is for Allah. All acts of worship and good deeds are for Him.Peace and the mercy and blessings of Allah be upon you O Prophet (saws).Peace be upon us and all of Allah’s righteous servants. I bear witness that none has the right to be worshipped except Allah and I bear witness that Muhammad is His slave and Messenger.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.022.part.002', 'dua.hisn.022', 2);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.022.part.002.segment.001', 'dua.hisn.022.part.002', 1, 'comment', 'en', 'Latn', 'At-tahiyyat: all words which indicate the glorification of Allah.His eternal existence, His perfection and His sovereignty.');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.023', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-023', 23, 'Prayers upon the Prophet (saws) after the tashahhud', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.023.part.001', 'dua.hisn.023', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.023.part.001.segment.001', 'dua.hisn.023.part.001', 1, 'arabic', 'ar', 'Arab', 'اللّهُـمَّ صَلِّ عَلـى مُحمَّـد، وَعَلـى آلِ مُحمَّد، كَمـا صَلَّيـتَ عَلـى إبْراهـيمَ وَعَلـى آلِ إبْراهـيم، إِنَّكَ حَمـيدٌ مَجـيد، اللّهُـمَّ بارِكْ عَلـى مُحمَّـد، وَعَلـى آلِ مُحمَّـد،كَمـا بارِكْتَ عَلـى إبْراهـيمَ وَعَلـى آلِ إبْراهيم، إِنَّكَ حَمـيدٌ مَجـيد.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.023.part.001.segment.002', 'dua.hisn.023.part.001', 2, 'transliteration', 'ar-Latn', 'Latn', 'Allahumma salli AAala Muhammad, wa-AAala ali Muhammad, kama sallayta AAala Ibraheema wa-AAala ali Ibraheem, innaka Hameedun Majeed, allahumma barik AAalaMuhammad, wa-AAala ali Muhammad, kama barakta AAala Ibraheema wa-AAala ali Ibraheem, innaka Hameedun Majeed.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.023.part.001.segment.003', 'dua.hisn.023.part.001', 3, 'translation', 'en', 'Latn', '‘O Allah, send prayers upon Muhammad and the followers of Muhammad, just as You sent prayers upon Ibraheem and upon the followers of Ibraheem.Verily, You are full of praise and majesty. O Allah, send blessings upon Mohammad and upon the family of Muhammad, just as You sent blessings upon Ibraheem and upon the family of Ibraheem.Verily, You are full of praise and majesty.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.023.part.002', 'dua.hisn.023', 2);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.023.part.002.segment.001', 'dua.hisn.023.part.002', 1, 'comment', 'en', 'Latn', 'send prayers: praise and exalt him in the highest and superior of gatherings: that of the closest angels to Allah.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.023.part.002.segment.002', 'dua.hisn.023.part.002', 2, 'comment', 'en', 'Latn', '(al) has been translated in it’s broadest sense: some scholars are of the view that the meaning here is more specific and that it means: his followers from among his family.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.023.part.002.segment.003', 'dua.hisn.023.part.002', 3, 'arabic', 'ar', 'Arab', 'اللّهُـمَّ صَلِّ عَلـى مُحمَّـدٍوَعَلـى أَزْواجِـهِ وَذُرِّيَّـتِه،كَمـا صَلَّيْـتَ عَلـى آلِ إبْراهـيم. وَبارِكْ عَلـى مُحمَّـدٍ وَعَلـى أَزْواجِـهِ وَذُرِّيَّـتِه،كَمـا بارِكْتَ عَلـى آلِ إبْراهـيم. إِنَّكَ حَمـيدٌ مَجـيد.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.023.part.002.segment.004', 'dua.hisn.023.part.002', 4, 'transliteration', 'ar-Latn', 'Latn', 'Allahumma salli AAala Muhammad wa-AAala azwajihi wathurriyyatihi kama sallayta AAala ali Ibraheem, wabarik AAala Muhammad, wa-AAala azwajihi wathurriyyatih, kama barakta AAala ali Ibraheem. innaka Hameedun Majeed.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.023.part.002.segment.005', 'dua.hisn.023.part.002', 5, 'translation', 'en', 'Latn', '‘O Allah, send prayers upon Muhammad and upon the wives and descendants of Muhammad, just as You sent prayers upon the family of Ibraheem, and send blessings upon Muhammad and upon the wives and descendants of Muhammad, just as You sent blessings upon the family of Ibraheem. Verily, You are full of praise and majesty.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.024', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-024', 24, 'Supplication said after the last tashahhud and before salam', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.024.part.001', 'dua.hisn.024', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.024.part.001.segment.001', 'dua.hisn.024.part.001', 1, 'arabic', 'ar', 'Arab', 'اللّهُـمَّ إِنِّـي أَعـوذُ بِكَ مِـنْ عَذابِ القَـبْر، وَمِـنْ عَذابِ جَهَـنَّم، وَمِـنْ فِتْـنَةِالمَحْـيا وَالمَمـات، وَمِـنْ شَـرِّ فِتْـنَةِالمَسيحِ الدَّجّال.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.024.part.001.segment.002', 'dua.hisn.024.part.001', 2, 'transliteration', 'ar-Latn', 'Latn', 'Allahumma innee aAAoothu bika min AAathabil-qabr, wamin AAathabi jahannam, wamin fitnatil-mahya walmamat, wamin shari fitnatil-maseehid-dajjal.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.024.part.001.segment.003', 'dua.hisn.024.part.001', 3, 'translation', 'en', 'Latn', '‘O Allah, I take refuge in You from the punishment of the grave, from the torment of the Fire, from the trials and tribulations of life and death and from the evil affliction of Al-Maseeh Ad-Dajjal.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.024.part.002', 'dua.hisn.024', 2);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.024.part.002.segment.001', 'dua.hisn.024.part.002', 1, 'comment', 'en', 'Latn', 'Al-Maseeh Ad-Dajjal: among the great signs of the last hour and the greatest trials to befall mankind, which every Prophet (saws) has warned about.Most of mankind will follow him. He will appear from Asbahan, Iran at the time when the Muslims will conquer Constantinople.He will be given special powers and will make the truth seem false and vice versa.He will claim to be righteous and then he will claim Prophet (saws)hood and finally, divinity.From his features is that he will be blind in his right eye which is a definite proof that contradicts his claim to be Allah as it is a sign of imperfection.The word Kafir will be written between his eyes which every believer, literate or illiterate will recognise.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.024.part.002.segment.002', 'dua.hisn.024.part.002', 2, 'arabic', 'ar', 'Arab', 'اللّهُـمَّ إِنِّـي أَعـوذُ بِكَ مِـنْ عَذابِ القَـبْر، وَأَعـوذُ بِكَ مِـنْ فِتْـنَةِالمَسيحِ الدَّجّـال، وَأَعـوذُ بِكَ مِـنْ فِتْـنَةِالمَحْـيا وَالمَمـات. اللّهُـمَّ إِنِّـي أَعـوذُ بِكَ مِنَ المَأْثَـمِ وَالمَغْـرَم.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.024.part.002.segment.003', 'dua.hisn.024.part.002', 3, 'transliteration', 'ar-Latn', 'Latn', 'Allahumma innee aAAoothu bika min AAathabil-qabr, wa-aAAoothu bika min fitnatil-maseehid-dajjal, wa-aAAoothu bika min fitnatil-mahya walmamat. Allahumma innee aAAoothu bika minal-ma/thami walmaghram.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.024.part.002.segment.004', 'dua.hisn.024.part.002', 4, 'translation', 'en', 'Latn', '‘O Allah, I take refuge in You from the punishment of the grave, and I take refuge in You from the temptation and trial of Al-Maseeh Ad-Dajjal, and I take refuge in You from the trials and tribulations of life and death.O Allah, I take refuge in You from sin and debt.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.024.part.003', 'dua.hisn.024', 3);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.024.part.003.segment.001', 'dua.hisn.024.part.003', 1, 'arabic', 'ar', 'Arab', 'اللّهُـمَّ إِنِّـي ظَلَـمْتُ نَفْسـي ظُلْمـاً كَثـيراً وَلا يَغْـفِرُ الذُّنـوبَ إِلاّ أَنْت، فَاغْـفِر لي مَغْـفِرَةً مِنْ عِنْـدِك وَارْحَمْـني، إِنَّكَ أَنْتَ الغَـفورُ الرَّحـيم.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.024.part.003.segment.002', 'dua.hisn.024.part.003', 2, 'transliteration', 'ar-Latn', 'Latn', 'Allahumma innee thalamtu nafsee thulman katheeran wala yaghfiruth-thunooba illa ant, faghfir lee maghfiratan min AAindik warhamnee, innaka antal-Ghafoorur-Raheem.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.024.part.003.segment.003', 'dua.hisn.024.part.003', 3, 'translation', 'en', 'Latn', '‘O Allah, I have indeed oppressed my soul excessively and none can forgive sin except You, so forgive me a forgiveness from Yourself and have mercy upon me.Surely, You are The Most-Forgiving, The Most-Merciful.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.024.part.004', 'dua.hisn.024', 4);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.024.part.004.segment.001', 'dua.hisn.024.part.004', 1, 'comment', 'en', 'Latn', 'From Yourself: i.e. from Your innermost grace without deserving it and a forgiveness which is befitting to your tremendous generosity.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.024.part.004.segment.002', 'dua.hisn.024.part.004', 2, 'arabic', 'ar', 'Arab', 'اللّهُـمَّ اغْـفِرْ لي ما قَدَّمْـتُ وَما أَخَّرْت، وَما أَسْـرَرْتُ وَما أَعْلَـنْت، وَما أَسْـرَفْت، وَما أَنْتَ أَعْـلَمُ بِهِ مِنِّي. أَنْتَ المُقَـدِّمُ، وَأَنْتَ المُـؤَخِّـرُ لا إِلهَ إِلاّ أَنْـت.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.024.part.004.segment.003', 'dua.hisn.024.part.004', 3, 'transliteration', 'ar-Latn', 'Latn', 'Allahummagh-fir lee ma qaddamtu,wama akhkhart, wama asrartu wama aAAlant, wama asraftt, wama anta aAAlamu bihi minnee, antal-muqaddimu wa-antal-mu-akhkhiru la ilaha illa ant.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.024.part.004.segment.004', 'dua.hisn.024.part.004', 4, 'translation', 'en', 'Latn', '‘O Allah, forgive me for those sins which have come to pass as well as those which shall come to pass, and those I have committed in secret as well as those I have made public, and where I have exceeded all bounds as well as those things about which You are more knowledgeable. You are Al-Muqaddim and Al-Mu-akhkhir.None has the right to be worshipped except You.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.024.part.005', 'dua.hisn.024', 5);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.024.part.005.segment.001', 'dua.hisn.024.part.005', 1, 'comment', 'en', 'Latn', 'Meaning of Al-Muqaddim and Al-Mu-akhkhir: Allah puts forward and favours whom He wills from amongst His creation just as He defers and holds back whom He wills in accordance to His wisdom.E.g.Favouring man over the rest of creation, favouring the Prophet (saws)s over the rest of mankind, favouring Muhammad over all the Prophet (saws)s and Messengersetc.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.024.part.005.segment.002', 'dua.hisn.024.part.005', 2, 'arabic', 'ar', 'Arab', 'اللّهُـمَّ أَعِـنِّي عَلـى ذِكْـرِكَ وَشُكْـرِك، وَحُسْـنِ عِبـادَتِـك.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.024.part.005.segment.003', 'dua.hisn.024.part.005', 3, 'transliteration', 'ar-Latn', 'Latn', 'Allahumma aAAinnee AAala thikrik, washukrik, wahusni AAibadatik.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.024.part.005.segment.004', 'dua.hisn.024.part.005', 4, 'translation', 'en', 'Latn', '‘O Allah, help me to remember You, to thank You, and to worship You in the best of manners.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.024.part.006', 'dua.hisn.024', 6);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.024.part.006.segment.001', 'dua.hisn.024.part.006', 1, 'arabic', 'ar', 'Arab', 'اللّهُـمَّ إِنِّـي أَعوذُ بِكَ مِنَ البُخْـل، وَأَعوذُ بِكَ مِنَ الجُـبْن، وَأَعوذُ بِكَ مِنْ أَنْ أُرَدَّ إِلى أَرْذَلِ الـعُمُر، وَأََعوذُ بِكَ مِنْ فِتْنَـةِ الدُّنْـيا وَعَـذابِ القَـبْر.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.024.part.006.segment.002', 'dua.hisn.024.part.006', 2, 'transliteration', 'ar-Latn', 'Latn', 'Allahumma innee aAAoothu bika minal-bukhl, wa-aAAoothu bika minal-jubn, wa-aAAoothu bika min an oradda ila arthalil- AAumur, wa-aAAoothu bika min fitnatid-dunya waAAathabil-qabr.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.024.part.006.segment.003', 'dua.hisn.024.part.006', 3, 'translation', 'en', 'Latn', '‘O Allah, I take refuge in You from miserliness and cowardice, I take refuge in You lest I be returned to the worst of lives “i.e. old age, being weak, incapable and in a state of fear”, and I take refuge in You from the trials and tribulations of this life and the punishment of the grave.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.024.part.007', 'dua.hisn.024', 7);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.024.part.007.segment.001', 'dua.hisn.024.part.007', 1, 'arabic', 'ar', 'Arab', 'اللّهُـمَّ إِنِّـي أَسْأَلُـكَ الجَـنَّةَ وأََعوذُ بِـكَ مِـنَ الـنّار.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.024.part.007.segment.002', 'dua.hisn.024.part.007', 2, 'transliteration', 'ar-Latn', 'Latn', 'Allahumma innee as-alukal-jannah, wa-aAAoothu bika minan-nar.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.024.part.007.segment.003', 'dua.hisn.024.part.007', 3, 'translation', 'en', 'Latn', '‘O Allah, I ask You to grant me Paradise and I take refuge in You from the Fire.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.024.part.008', 'dua.hisn.024', 8);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.024.part.008.segment.001', 'dua.hisn.024.part.008', 1, 'arabic', 'ar', 'Arab', 'اللّهُـمَّ بِعِلْـمِكَ الغَـيْبِ وَقُـدْرَتِـكَ عَلـى الْخَلقِ أَحْـيِني ما عَلِـمْتَ الحـياةَ خَـيْراً لـي، وَتَوَفَّـني إِذا عَلِـمْتَ الوَفـاةَخَـيْراً لـي، اللّهُـمَّ إِنِّـي أَسْـأَلُـكَ خَشْيَتَـكَ في الغَـيْبِ وَالشَّهـادَةِ، وَأَسْـأَلُـكَ كَلِمَـةَ الحَـقِّ في الرِّضـا وَالغَضَـب، وَأَسْـأَلُـكَ القَصْدَ في الغِنـى وَالفَقْـر، وَأَسْـأَلُـكَ نَعـيماً لا يَنْفَـد، وَأَسْـأَلُـكَ قُـرَّةَ عَيْـنٍ لا تَنْـقَطِعْ وَأَسْـأَلُـكَ الرِّضـا بَعْـدَ القَضـاء، وَأَسْـأَلُـكَ بًـرْدَ الْعَـيْشِ بَعْـدَ الْمَـوْت، وَأَسْـأَلُـكَ لَـذَّةَ النَّظَـرِ إِلـى وَجْـهِكَ وَالشَّـوْقَ إِلـى لِقـائِـك، في غَـيرِ ضَـرّاءَ مُضِـرَّة، وَلا فِتْـنَةٍ مُضـلَّة، اللّهُـمَّ زَيِّـنّا بِزينَـةِ الإيـمان، وَاجْـعَلنا هُـداةً مُهْـتَدين.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.024.part.008.segment.002', 'dua.hisn.024.part.008', 2, 'transliteration', 'ar-Latn', 'Latn', 'Allahumma biAAilmikal-ghayb, waqudratika AAalal-khalq, ahyinee ma AAalimtal-hayata khayran lee watawaffanee itha AAalimtal-wafata khayran lee, allahumma innee as-aluka khashyataka fil-ghaybi washshahadah, wa-as-aluka kalimatal-haqqi fir-rida walghadab, wa-as-alukal-qasda fil-ghina walfaqr, wa-as-aluka naAAeeman la yanfad, wa-as-aluka qurrata AAaynin la tanqatiAA, wa-as-alukar-rida baAAdal-qada/, wa-as-aluka bardal-AAayshi baAAdal-mawt, wa-as-aluka laththatan-nathari ila wajhik, washshawqa ila liqa-ik fee ghayri darraa mudirrah, wala fitnatin mudillah, allahumma zayyinna bizeenatil-eeman wajAAalna hudatan muhtadeen.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.024.part.008.segment.003', 'dua.hisn.024.part.008', 3, 'translation', 'en', 'Latn', '‘O Allah, by Your knowledge of the unseen and Your power over creation, keep me alive so long as You know such life to be good for me and take me if You know death to be better for me.O Allah, make me fearful of You whether in secret or in public and I ask You to make me true in speech, in times of pleasure and anger.I ask you to make me moderate in times of wealth and poverty and I ask You for everlasting bliss and joy which will never cease.I ask You to make me pleased with what You have decreed and for an easy life after death.I ask You for the sweetness of looking upon Your Face and a longing to encounter You in a manner which does not entail a calamity which will bring about harm nor a trial which will cause deviation. O Allah, beautify us with the adornment of faith and make us of those who guide and are rightly guided.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.024.part.009', 'dua.hisn.024', 9);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.024.part.009.segment.001', 'dua.hisn.024.part.009', 1, 'arabic', 'ar', 'Arab', 'اللّهُـمَّ إِنِّـي أَسْأَلُـكَ يا اللهُ بِأَنَّـكَ الواحِـدُ الأَحَـد،الصَّـمَدُ الَّـذي لَـمْ يَلِـدْ وَلَمْ يولَدْ، وَلَمْ يَكـنْ لَهُ كُـفُواً أَحَـد، أَنْ تَغْـفِرْ لي ذُنـوبي إِنَّـكَ أَنْـتَ الغَفـورُ الرَّحِّـيم.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.024.part.009.segment.002', 'dua.hisn.024.part.009', 2, 'transliteration', 'ar-Latn', 'Latn', 'Allahumma innee as-aluka ya Allah bi-annakal-wahidul-ahadus-samad, allathee lam yalid walam yoolad, walam yakun lahu kufuwan ahad, an taghfira lee thunoobee innaka antal-Ghafoorur-Raheem.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.024.part.009.segment.003', 'dua.hisn.024.part.009', 3, 'translation', 'en', 'Latn', '‘O Allah, I ask You O Allah, as You are The One, The Only, AS-Samad, The One who begets not, nor was He begotten and there is none like unto Him that You forgive me my sins for verily You are The Oft-Forgiving, Most-Merciful.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.024.part.010', 'dua.hisn.024', 10);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.024.part.010.segment.001', 'dua.hisn.024.part.010', 1, 'comment', 'en', 'Latn', 'AS-Samad: The Self-Sufficient Master, Possessor of perfect attributes whom all of creation turn to in all their needs.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.024.part.010.segment.002', 'dua.hisn.024.part.010', 2, 'arabic', 'ar', 'Arab', 'اللّهُـمَّ إِنِّـي أَسْأَلُـكَ بِأَنَّ لَكَ الْحَـمْدُ لا إِلـهَ إِلاّ أَنْـتَ وَحْـدَكَ لا شَـريكَ لَـكَ المَنّـانُ يا بَديـعَ السَّمواتِ وَالأَرْضِ يا ذا الجَلالِ وَالإِكْـرام، يا حَـيُّ يا قَـيّومُ إِنِّـي أَسْأَلُـكَ الجَـنَّةَ وَأَعـوذُ بِـكَ مِنَ الـنّار.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.024.part.010.segment.003', 'dua.hisn.024.part.010', 3, 'transliteration', 'ar-Latn', 'Latn', 'Allahumma innee as-aluka bianna lakal-hamd, la ilaha illa ant wahdaka la shareeka lak, almannan, ya badeeAAas-samawati wal-ard, ya thal-jalali wal-ikram, ya hayyu ya qayyoom, innee as-alukal-jannah, wa-aAAoothu bika minan-nar.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.024.part.010.segment.004', 'dua.hisn.024.part.010', 4, 'translation', 'en', 'Latn', '‘O Allah, I ask You as unto You is all praise, none has the right to be worshipped except You, alone, without partner. You are the Benefactor. O Originator of the heavens and the Earth, O Possessor of majesty and honour, O Ever Living, O Self-Subsisting and Supporter of all, verily I ask You for Paradise and I take refuge with You from the Fire.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.024.part.011', 'dua.hisn.024', 11);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.024.part.011.segment.001', 'dua.hisn.024.part.011', 1, 'arabic', 'ar', 'Arab', 'اللّهُـمَّ إِنِّـي أَسْأَلُـكَ بِأَنَّـي أَشْـهَدُ أَنَّـكَ أنْـتَ اللهُ لا إِلـهَ إِلاّ أَنْـت، الأَحَـدُ الصَّـمَدُ الَّـذي لَـمْ يَلِـدْ وَلَمْ يولَـدْ، وَلَمْ يَكـنْ لَهُ كُـفُواً أَحَـد');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.024.part.011.segment.002', 'dua.hisn.024.part.011', 2, 'transliteration', 'ar-Latn', 'Latn', '.Allahumma inne as-aluka biannee ashhadu annaka antal-lah, la ilaha illa ant, al-ahadus-samad, allathee lam yalid walam yoolad walam yakun lahu kufuwan ahad.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.024.part.011.segment.003', 'dua.hisn.024.part.011', 3, 'translation', 'en', 'Latn', '‘O Allah, I ask You, as I bear witness that You are Allah, none has the right to be worshipped except You, The One, AS-Samad Who begets not nor was He begotten and there is none like unto Him.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.024.part.012', 'dua.hisn.024', 12);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.024.part.012.segment.001', 'dua.hisn.024.part.012', 1, 'comment', 'en', 'Latn', 'AS-Samad: The Self-Sufficient Master, Possessor of perfect attributes whom all of creation turn to in all their needs.');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.025', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-025', 25, 'Remembrance after salam', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.025.part.001', 'dua.hisn.025', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.025.part.001.segment.001', 'dua.hisn.025.part.001', 1, 'arabic', 'ar', 'Arab', 'أَسْتَغْفِرُ اللهَ (ثلاث مرات) اللَّهمَّ أَنْتَ السَّلَام وَمنْكَ السَّلَام، تَبَارَكْتَ يَا ذَا الْجَلَال وَالْإكْرَام');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.025.part.001.segment.002', 'dua.hisn.025.part.001', 2, 'transliteration', 'ar-Latn', 'Latn', 'I seek the forgiveness of Allah (three times). O Allah, You are Peace and from You comes peace. Blessed are You , O Owner of majesty and honor.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.025.part.001.segment.003', 'dua.hisn.025.part.001', 3, 'translation', 'en', 'Latn', '''Astaghfirullaaha Allaahumma''Antas-Salaamu wa minkas-salaamu, tabaarakta yaa Thal-Jalaali wal-''Ikraam.');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.025.part.002', 'dua.hisn.025', 2);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.025.part.002.segment.001', 'dua.hisn.025.part.002', 1, 'arabic', 'ar', 'Arab', 'لَا إلهَ إلَّا الله وَحْدَه لَا شَريكَ لَه، لَه الْملْك وَلَه الْحَمْد وَهوَ عَلَى كلّ شَيْء قَديرٌ، اللَّهمَّ لَا مَانعَ لمَا أَعْطَيْتَ، وَلَا معْطيَ لمَا مَنَعْتَ، وَلَا يَنْفَعُ ذَا الْجَدّ منْكَ الْجَدّ');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.025.part.002.segment.002', 'dua.hisn.025.part.002', 2, 'transliteration', 'ar-Latn', 'Latn', 'Laa''ilaaha''illallaahu wahdahu laa shareeka lahu, lahul-mulku wa lahul-hamdu wa Huwa''alaa kulli shay''in Qadeer, Allaahumma laa maard''a limaa''a''tayta, wa laa mu''tiya limaa mana''ta, wa laa yanfa''u thal-jaddi minkal-jadd.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.025.part.002.segment.003', 'dua.hisn.025.part.002', 3, 'translation', 'en', 'Latn', 'None has the right to be worshipped but Allah alone, He has no partner, His is the dominion and His is the praise, and He is Able to do all things. O Allah, there is none who can withhold what You give, and none may give what You have withheld; and the might of the mighty person cannot benefit him against You.');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.025.part.003', 'dua.hisn.025', 3);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.025.part.003.segment.001', 'dua.hisn.025.part.003', 1, 'arabic', 'ar', 'Arab', 'لَا إلَهَ إلَّا الله وَحْدَه لَا شَريكَ لَه، لَه الْملْك وَلَه الْحَمْد وَهوَ عَلَى كلّ شَيْء قَديرٌ، لَا حَوْلَ وَلَا قوَّةَ إلَّا بالله، لَا إلَهَ إلَّا الله، وَلَا نَعْبد إلَّا إيَّاه، لَه النّعْمَة وَلَه الْفَضْلُ وَلَه الثَّنَاء الْحَسَن، لَا إلَهَ إلَّا الله مخْلصينَ لَه الدّينَ وَلَوْ كَرهَ الْكَافِرُونَ');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.025.part.003.segment.002', 'dua.hisn.025.part.003', 2, 'transliteration', 'ar-Latn', 'Latn', 'Laa''ilaaha''illallaahu wahdahu laa shareeka lahu, lahul-mulku, wa lahul-hamdu wa Huwa''alaa kulli shay''in Qadeer. Laa hawla wa laa quwwata''illaa billaahi, laa''ilaaha''illallaahu, wa laa na''budu''illaa''iyyaahu, lahun-ni''matu wa lahul-fadhlu wa lahuth-thanaa''ul-hasanu, laa''ilaaha''illallaahu mukhliseena lahud-deena wa law karihal-kaafiroon.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.025.part.003.segment.003', 'dua.hisn.025.part.003', 3, 'translation', 'en', 'Latn', 'None has the right to be worshipped but Allah alone, He has no partner, His is the dominion and His is the praise and He is Able to do all things. There is no power and no might except by Allah. None has the right to be worshipped but Allah, and we do not worship any other besides Him. His is grace , and His is bounty and to Him belongs the most excellent praise. None has the right to be worshipped but Allah. (We are) sincere in making our religious devotion to Him, even though the disbelievers may dislike it.');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.025.part.004', 'dua.hisn.025', 4);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.025.part.004.segment.001', 'dua.hisn.025.part.004', 1, 'arabic', 'ar', 'Arab', 'سبْحَانَ الله، وَالْحَمْد لله، وَالله أَكْبَر (ثَلَاثاً وَثَلَاثينَ) لَا إلَهَ إلَّا الله وَحْدَه لَا شَريكَ لَه، لَه الْملْك وَلَه الْحَمْد وَهوَ عَلَى كلّ شَيْء قَديرٌ');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.025.part.004.segment.002', 'dua.hisn.025.part.004', 2, 'transliteration', 'ar-Latn', 'Latn', 'Glory is to Allah , and praise is to Allah , and Allah is the Most Great (each said thirty-three times). None has the right to be worshipped but Allah alone, He has no partner, His is the dominion and His is the praise and He is Able to do all things.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.025.part.004.segment.003', 'dua.hisn.025.part.004', 3, 'translation', 'en', 'Latn', 'Subhaanallaahi, walhamdu lillaahi wallaahu''Akbar, - Laa''ilaaha''illallaahu wahdahu laa shareeka lahu, lahul-mulku wa lahul-hamduwaHuwa''alaakullishay''inQadeer.');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.025.part.005', 'dua.hisn.025', 5);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.025.part.005.segment.001', 'dua.hisn.025.part.005', 1, 'arabic', 'ar', 'Arab', 'سورَة الإخْلَاص - بسْم ٱلله ٱلرَّحْمَـٰن ٱلرَّحيم');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.025.part.006', 'dua.hisn.025', 6);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.025.part.006.segment.001', 'dua.hisn.025.part.006', 1, 'arabic', 'ar', 'Arab', 'قُلْ هُوَ اللهُ أَحَدٌ ۞ اللهُ الصَّمَدُ ۞ لَمْ يَلِدْ وَلَمْ يُولَدْ ۞ وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.025.part.006.segment.002', 'dua.hisn.025.part.006', 2, 'transliteration', 'ar-Latn', 'Latn', 'Surah Al-Ikhlas In the name of Allah, the Beneficent, the Merciful');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.025.part.006.segment.003', 'dua.hisn.025.part.006', 3, 'translation', 'en', 'Latn', 'Say (O Muhammad (SAW)):''He is Allah, (the) One.۞ Allah the Self-Sufficient Master, Whom all creatures need, (He neither eats nor drinks). ۞ He begets not, nor was He begotten. ۞ And there is none co-equal or comparable unto Him.۞''');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.025.part.007', 'dua.hisn.025', 7);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.025.part.007.segment.001', 'dua.hisn.025.part.007', 1, 'comment', 'en', 'Latn', 'bismillaahir-rahmaanir-raheem');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.025.part.007.segment.002', 'dua.hisn.025.part.007', 2, 'comment', 'en', 'Latn', '۞');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.025.part.007.segment.003', 'dua.hisn.025.part.007', 3, 'comment', 'en', 'Latn', 'qul huwa-llaahu ahad');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.025.part.007.segment.004', 'dua.hisn.025.part.007', 4, 'comment', 'en', 'Latn', '۞');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.025.part.007.segment.005', 'dua.hisn.025.part.007', 5, 'comment', 'en', 'Latn', 'allaahus-samad');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.025.part.007.segment.006', 'dua.hisn.025.part.007', 6, 'comment', 'en', 'Latn', '۞');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.025.part.007.segment.007', 'dua.hisn.025.part.007', 7, 'comment', 'en', 'Latn', 'lam yalid wa lam yoolad');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.025.part.007.segment.008', 'dua.hisn.025.part.007', 8, 'comment', 'en', 'Latn', '۞');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.025.part.007.segment.009', 'dua.hisn.025.part.007', 9, 'comment', 'en', 'Latn', 'wa lam yakul-lahu');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.025.part.007.segment.010', 'dua.hisn.025.part.007', 10, 'comment', 'en', 'Latn', 'ۥ');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.025.part.007.segment.011', 'dua.hisn.025.part.007', 11, 'comment', 'en', 'Latn', 'kufuwan ahad');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.025.part.007.segment.012', 'dua.hisn.025.part.007', 12, 'arabic', 'ar', 'Arab', 'سورَة الْفَلَقِ - بسْم ٱلله ٱلرَّحْمَـٰن ٱلرَّحيم');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.025.part.008', 'dua.hisn.025', 8);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.025.part.008.segment.001', 'dua.hisn.025.part.008', 1, 'arabic', 'ar', 'Arab', 'قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ ۞ مِنْ شَرِّ مَا خَلَقَ ۞ وَمِنْ شَرِّ غَاسِقٍ إِذَا وَقَبَ ۞ وَمِنْ شَرِّ النَّفَّاثَاتِ فِي الْعُقَدِ ۞ وَمِنْ شَرِّ حَاسِدٍ إِذَا حَسَدَ');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.025.part.008.segment.002', 'dua.hisn.025.part.008', 2, 'transliteration', 'ar-Latn', 'Latn', 'Surah Al-Falaq In the name of Allah, the Beneficent, the Merciful');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.025.part.008.segment.003', 'dua.hisn.025.part.008', 3, 'translation', 'en', 'Latn', 'Say:''I seek refuge with (Allah) the Lord of the daybreak, ۞ From the evil of what He has created; ۞ And from the evil of the darkening (night) as it comes with its darkness; (or the moon as it sets or goes away) ۞ And from the evil of those who practice witchcrafts when they blow in the knots, ۞ And from the evil of the envier when he envies. ۞''');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.025.part.009', 'dua.hisn.025', 9);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.025.part.009.segment.001', 'dua.hisn.025.part.009', 1, 'comment', 'en', 'Latn', 'bismillaahir-rahmaanir-raheem');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.025.part.009.segment.002', 'dua.hisn.025.part.009', 2, 'comment', 'en', 'Latn', '۞');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.025.part.009.segment.003', 'dua.hisn.025.part.009', 3, 'comment', 'en', 'Latn', 'qul a''oodhu birabbil-falaq');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.025.part.009.segment.004', 'dua.hisn.025.part.009', 4, 'comment', 'en', 'Latn', '۞');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.025.part.009.segment.005', 'dua.hisn.025.part.009', 5, 'comment', 'en', 'Latn', 'min sharri maa khalaq');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.025.part.009.segment.006', 'dua.hisn.025.part.009', 6, 'comment', 'en', 'Latn', '۞');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.025.part.009.segment.007', 'dua.hisn.025.part.009', 7, 'comment', 'en', 'Latn', 'wa min sharri ghaasiqin idhaa waqab');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.025.part.009.segment.008', 'dua.hisn.025.part.009', 8, 'comment', 'en', 'Latn', '۞');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.025.part.009.segment.009', 'dua.hisn.025.part.009', 9, 'comment', 'en', 'Latn', 'wa min sharrin-naffaathaati fil-''uqad');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.025.part.009.segment.010', 'dua.hisn.025.part.009', 10, 'comment', 'en', 'Latn', '۞');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.025.part.009.segment.011', 'dua.hisn.025.part.009', 11, 'comment', 'en', 'Latn', 'wa min sharri haasidin idhaa hasad');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.025.part.009.segment.012', 'dua.hisn.025.part.009', 12, 'arabic', 'ar', 'Arab', 'سورَة النَّاس - بسْم ٱلله ٱلرَّحْمَـٰن ٱلرَّحيم');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.025.part.010', 'dua.hisn.025', 10);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.025.part.010.segment.001', 'dua.hisn.025.part.010', 1, 'arabic', 'ar', 'Arab', 'قلْ أَعوذ برَبّ ٱلنَّاس ۞ مَلك ٱلنَّاس ۞ إلَـٰه ٱلنَّاس ۞ من شَرّ ٱلْوَسْوَاس ٱلْخَنَّاس ۞ ٱلَّذى يوَسْوس فِي صدور ٱلنَّاس ۞ منَ ٱلْجنَّة وَٱلنَّاس ۞');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.025.part.010.segment.002', 'dua.hisn.025.part.010', 2, 'transliteration', 'ar-Latn', 'Latn', 'Surah An-Nas In the name of Allah, the Beneficent, the Merciful');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.025.part.010.segment.003', 'dua.hisn.025.part.010', 3, 'translation', 'en', 'Latn', 'Say:''I seek refuge with (Allah) the Lord of mankind, ۞ The King of mankind ۞ The Ilah (God) of mankind, ۞ From the evil of the whisperer (devil who whispers evil in the hearts of men) who withdraws (from his whispering in one''s heart after one remembers Allah), ۞ Who whispers in the breasts of mankind, ۞ Of jinn and men.۞');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.025.part.011', 'dua.hisn.025', 11);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.025.part.011.segment.001', 'dua.hisn.025.part.011', 1, 'comment', 'en', 'Latn', '۞');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.025.part.011.segment.002', 'dua.hisn.025.part.011', 2, 'comment', 'en', 'Latn', 'qul a''oodh-u birabbin-naas');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.025.part.011.segment.003', 'dua.hisn.025.part.011', 3, 'comment', 'en', 'Latn', '۞');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.025.part.011.segment.004', 'dua.hisn.025.part.011', 4, 'comment', 'en', 'Latn', 'malikin-naas');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.025.part.011.segment.005', 'dua.hisn.025.part.011', 5, 'comment', 'en', 'Latn', '۞');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.025.part.011.segment.006', 'dua.hisn.025.part.011', 6, 'comment', 'en', 'Latn', 'ilaahin-naas');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.025.part.011.segment.007', 'dua.hisn.025.part.011', 7, 'comment', 'en', 'Latn', '۞');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.025.part.011.segment.008', 'dua.hisn.025.part.011', 8, 'comment', 'en', 'Latn', 'min sharril-waswaasil-khannaas');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.025.part.011.segment.009', 'dua.hisn.025.part.011', 9, 'comment', 'en', 'Latn', '۞');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.025.part.011.segment.010', 'dua.hisn.025.part.011', 10, 'comment', 'en', 'Latn', 'alladhee yuwaswisu fee sudoorin-naas');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.025.part.011.segment.011', 'dua.hisn.025.part.011', 11, 'comment', 'en', 'Latn', '۞');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.025.part.011.segment.012', 'dua.hisn.025.part.011', 12, 'comment', 'en', 'Latn', 'minal-jinnati wan-naas');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.025.part.011.segment.013', 'dua.hisn.025.part.011', 13, 'arabic', 'ar', 'Arab', 'أية الكرسي -بسْم ٱلله ٱلرَّحْمَـٰن ٱلرَّحيم');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.025.part.011.segment.014', 'dua.hisn.025.part.011', 14, 'transliteration', 'ar-Latn', 'Latn', '''');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.025.part.012', 'dua.hisn.025', 12);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.025.part.012.segment.001', 'dua.hisn.025.part.012', 1, 'arabic', 'ar', 'Arab', 'أَعُوذُ بِاللهِ مِنَ الشَّيْطَانِ الرَّجِيمِ اللهُ لَا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ لَا تَأْخُذُهُ سِنَةٌ وَلَا نَوْمٌ لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ مَنْ ذَا الَّذِي يَشْفَعُ عِنْدَهُ إِلَّا بِإِذْنِهِ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلَا يُحِيطُونَ بِشَيْءٍ مِنْ عِلْمِهِ إِلَّا بِمَا شَاءَ وَسِعَ كُرْسِيُّهُ السَّمَاوَاتِ وَالْأَرْضَ وَلَا يَئُودُهُ حِفْظُهُمَا وَهُوَ الْعَلِيُّ الْعَظِيمُ.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.025.part.012.segment.002', 'dua.hisn.025.part.012', 2, 'transliteration', 'ar-Latn', 'Latn', '''.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.025.part.012.segment.003', 'dua.hisn.025.part.012', 3, 'translation', 'en', 'Latn', 'Ayat al Kursi');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.025.part.013', 'dua.hisn.025', 13);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.025.part.013.segment.001', 'dua.hisn.025.part.013', 1, 'comment', 'en', 'Latn', 'Allah! There is none worthy of worship but He, the Ever Living, the One Who sustains and protects all that exists. Neither slumber nor sleep overtakes Him. To Him belongs whatever is in the heavens and whatever is on the earth. Who is he that can intercede with Him except with His Permission? He knows what happens to them in this world, and what will happen to them in the Hereafter. And they will never encompass anything of His Knowledge except that which He wills. His Throne extends over the heavens and the earth, and He feels no fatigue in guarding and preserving them. And He is the Most High, the Most Great.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.025.part.013.segment.002', 'dua.hisn.025.part.013', 2, 'comment', 'en', 'Latn', 'Allaahu laa''ilaaha''illaa Huwal-Hayyul-Qayyoom, laa ta''khuthuhu sinatun wa laa nawm, lahu maa fis-samaawaati wa maa fil-''ardh, man thal-lathee yashfa''u''indahu''illaa bi''ithnihi, ya''lamu maa bayna''aydeehim wa maa khalfahum, wa laa yuheetoona bishay''im-min''ilmihi''illaa bimaa shaa''a, wasi''a kursiyyuhus-samaawaati wal''ardha, wa laa ya''ooduhu hifdhuhumaa, wa Huwal-''Aliyyul-''Adheem.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.025.part.013.segment.003', 'dua.hisn.025.part.013', 3, 'arabic', 'ar', 'Arab', 'لَا إلَهَ إلَّا الله وَحَدْه لَا شَريكَ لَه، لَه الْملْك وَلَه الْحَمْد يحْيي وَيميت، وَهوَ عَلَى كلّ شَيْء قَديرٌ');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.025.part.013.segment.004', 'dua.hisn.025.part.013', 4, 'transliteration', 'ar-Latn', 'Latn', 'Laa''ilaaha''illallaahu wahdahu laa shareeka lahu, lahul-mulku wa lahul-hamdu yuhyee wa yumeetu wa Huwa''alaa kulli shay''in Qadeer.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.025.part.013.segment.005', 'dua.hisn.025.part.013', 5, 'translation', 'en', 'Latn', 'None has the right to be worshipped but Allah alone, Who has no partner. His is the dominion and His is the praise. He brings life and He causes death , and He is Able to do all things. (Recite ten times in after the Maghrib and Fajr prayers.)');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.025.part.014', 'dua.hisn.025', 14);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.025.part.014.segment.001', 'dua.hisn.025.part.014', 1, 'arabic', 'ar', 'Arab', 'اللَّهمَّ إنّي أَسْأَلكَ علْماً نَافِعاً، وَرزْقاً طَيّباً، وَعَمَلاً متَقَبَّلاً');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.025.part.014.segment.002', 'dua.hisn.025.part.014', 2, 'transliteration', 'ar-Latn', 'Latn', 'Allaahumma''innee''as''aluka''ilman naafi''an, wa rizqan tayyiban, wa''amalan mutaqabbalan.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.025.part.014.segment.003', 'dua.hisn.025.part.014', 3, 'translation', 'en', 'Latn', 'O Allah, I ask You for knowledge that is of benefit , a good provision , and deeds that will be accepted. (Recite after the Fajr prayer.)');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.026', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-026', 26, 'Supplication for seeking guidance in forming a decision or choosing the proper course…etc (Al-Istikharah)', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.026.part.001', 'dua.hisn.026', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.026.part.001.segment.001', 'dua.hisn.026.part.001', 1, 'comment', 'en', 'Latn', 'On the authority of Jabir Ibn AAabdullah, he said: ’The Prophet (saws)would instruct us to pray for guidance in all of our concerns, just as he would teach us a chapter from the Quran.Hewould say ’ If any of you intends to undertake a matter then let him pray two supererogatory units (two rakAAah nafilah) of prayer and after which he should supplicate:');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.026.part.001.segment.002', 'dua.hisn.026.part.001', 2, 'arabic', 'ar', 'Arab', 'اللّهُـمَّ إِنِّـي أَسْتَخيـرُكَ بِعِاْـمِك، وَأسْتَقْـدِرُكَ بِقُـدْرَتِـك، وَأَسْـألُـكَ مِنْ فَضْـلِكَ العَظـيم، فَإِنَّـكَ تَقْـدِرُ وَلا أَقْـدِر، وَتَـعْلَـمُ وَلا أَعْلَـم، وَأَنْـتَ عَلاّمُ الغُـيوب، اللّهُـمَّ إِنْ كُنْـتَ تَعْـلَمُ أَنَّ هـذا الأمْـرَ- وَيُسَـمِّي حاجَتَـه - خَـيْرٌ لي في دينـي وَمَعـاشي وَعاقِـبَةِ أَمْـري، فَاقْـدُرْهُ لي وَيَسِّـرْهُ لي ثـمَّ بارِكْ لي فيـه، وَإِنْ كُنْـتَ تَعْـلَمُ أَنَّ هـذا الأمْـرَ شَـرٌلي في دينـي وَمَعـاشي وَعاقِـبَةِ أَمْـري، فَاصْرِفْـهُ وَاصْرِفْني عَنْـهُ وَاقْـدُرْ لي الخَـيْرَحَيْـثُ كانَ ثُـمَّ أَرْضِـني بِـه.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.026.part.001.segment.003', 'dua.hisn.026.part.001', 3, 'transliteration', 'ar-Latn', 'Latn', 'Allahumma innee astakheeruka biAAilmik, wa-astaqdiruka biqudratik, wa-as-aluka min fadlikal-AAatheem, fa-innaka taqdiru wala aqdir, wataAAlamu wala aAAlam ,wa-anta AAallamul ghuyoob, allahumma in kunta taAAlamu anna hathal-amr (say your need) khayrun lee fee deenee wamaAAashee waAAaqibati amree faqdurhu lee, wayassirhu lee, thumma barik lee feeh, wa-in kunta taAAlamu anna hathal-amr sharrun lee fee deenee wamaAAashee waAAaqibati amree fasrifhu AAannee wasrifnee AAanh, waqdur liyal-khayra haythu kan, thumma ardinee bih.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.026.part.001.segment.004', 'dua.hisn.026.part.001', 4, 'translation', 'en', 'Latn', '‘O Allah, I seek Your counsel by Your knowledge and by Your power I seek strength and I ask You from Your immense favour, for verily You are able while I am not and verily You know while I do not and You are the Knower of the unseen.O Allah, if You know this affair -and here he mentions his need- to be good for me in relation to my religion, my life, and end, then decree and facilitate it for me, and bless me with it, and if You know this affair to be ill for me towards my religion, my life, and end, then remove it from me and remove me from it, and decree for me what is good wherever it be and make me satisfied with such.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.026.part.002', 'dua.hisn.026', 2);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.026.part.002.segment.001', 'dua.hisn.026.part.002', 1, 'comment', 'en', 'Latn', 'One who seeks guidance from his Creator and consults his fellow believers and then remains firm in his resolve does not regret, for Allah has said:');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.026.part.002.segment.002', 'dua.hisn.026.part.002', 2, 'arabic', 'ar', 'Arab', 'وَشـاوِرْهُـم في الأمْـرِ فَـإِذا عَـزَمْـتَ فَتَوَكّـلْ عَلـى الله');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.026.part.002.segment.003', 'dua.hisn.026.part.002', 3, 'transliteration', 'ar-Latn', 'Latn', 'washawirhum fee al-amri fa-itha AAazamta fatawakkal AAala Allah');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.026.part.002.segment.004', 'dua.hisn.026.part.002', 4, 'translation', 'en', 'Latn', '(chapter 3 verse 159)');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.026.part.003', 'dua.hisn.026', 3);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.026.part.003.segment.001', 'dua.hisn.026.part.003', 1, 'translation', 'en', 'Latn', '‘and consult them in the affair. Then when you have taken a decision, put your trust in Allah’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.027', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-027', 27, 'Remembrance said in the morning', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.027.part.001', 'dua.hisn.027', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.001.segment.001', 'dua.hisn.027.part.001', 1, 'arabic', 'ar', 'Arab', 'أية الكرسي -بسْم ٱلله ٱلرَّحْمَـٰن ٱلرَّحيم');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.001.segment.002', 'dua.hisn.027.part.001', 2, 'transliteration', 'ar-Latn', 'Latn', '''');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.027.part.002', 'dua.hisn.027', 2);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.002.segment.001', 'dua.hisn.027.part.002', 1, 'arabic', 'ar', 'Arab', 'اللهُ لَا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ لَا تَأْخُذُهُ سِنَةٌ وَلَا نَوْمٌ لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ مَنْ ذَا الَّذِي يَشْفَعُ عِنْدَهُ إِلَّا بِإِذْنِهِ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلَا يُحِيطُونَ بِشَيْءٍ مِنْ عِلْمِهِ إِلَّا بِمَا شَاءَ وَسِعَ كُرْسِيُّهُ السَّمَاوَاتِ وَالْأَرْضَ وَلَا يَئُودُهُ حِفْظُهُمَا وَهُوَ الْعَلِيُّ الْعَظِيمُ.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.002.segment.002', 'dua.hisn.027.part.002', 2, 'transliteration', 'ar-Latn', 'Latn', '''');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.002.segment.003', 'dua.hisn.027.part.002', 3, 'translation', 'en', 'Latn', 'Ayat al Kursi');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.027.part.003', 'dua.hisn.027', 3);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.003.segment.001', 'dua.hisn.027.part.003', 1, 'comment', 'en', 'Latn', 'Allah! There is none worthy of worship but He, the Ever Living, the One Who sustains and protects all that exists. Neither slumber nor sleep overtakes Him. To Him belongs whatever is in the heavens and whatever is on the earth. Who is he that can intercede with Him except with His Permission? He knows what happens to them in this world, and what will happen to them in the Hereafter. And they will never encompass anything of His Knowledge except that which He wills. His Throne extends over the heavens and the earth, and He feels no fatigue in guarding and preserving them. And He is the Most High, the Most Great.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.003.segment.002', 'dua.hisn.027.part.003', 2, 'comment', 'en', 'Latn', 'Allaahu laa''ilaaha''illaa Huwal-Hayyul-Qayyoom, laa ta''khuthuhu sinatun wa laa nawm, lahu maa fis-samaawaati wa maa fil-''ardh, man thal-lathee yashfa''u''indahu''illaa bi''ithnihi, ya''lamu maa bayna''aydeehim wa maa khalfahum, wa laa yuheetoona bishay''im-min''ilmihi''illaa bimaa shaa''a, wasi''a kursiyyuhus-samaawaati wal''ardha, wa laa ya''ooduhu hifdhuhumaa, wa Huwal-''Aliyyul-''Adheem.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.003.segment.003', 'dua.hisn.027.part.003', 3, 'arabic', 'ar', 'Arab', 'سورَة الإخْلَاص - بسْم ٱلله ٱلرَّحْمَـٰن ٱلرَّحيم');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.027.part.004', 'dua.hisn.027', 4);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.004.segment.001', 'dua.hisn.027.part.004', 1, 'arabic', 'ar', 'Arab', 'قُلْ هُوَ اللهُ أَحَدٌ ۞ اللهُ الصَّمَدُ ۞ لَمْ يَلِدْ وَلَمْ يُولَدْ ۞ وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.004.segment.002', 'dua.hisn.027.part.004', 2, 'transliteration', 'ar-Latn', 'Latn', 'Surah Al-Ikhlas In the name of Allah, the Beneficent, the Merciful');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.004.segment.003', 'dua.hisn.027.part.004', 3, 'translation', 'en', 'Latn', 'Say (O Muhammad (SAW)):''He is Allah, (the) One.۞ Allah the Self-Sufficient Master, Whom all creatures need, (He neither eats nor drinks). ۞ He begets not, nor was He begotten. ۞ And there is none co-equal or comparable unto Him.۞''');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.027.part.005', 'dua.hisn.027', 5);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.005.segment.001', 'dua.hisn.027.part.005', 1, 'comment', 'en', 'Latn', 'bismillaahir-rahmaanir-raheem');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.005.segment.002', 'dua.hisn.027.part.005', 2, 'comment', 'en', 'Latn', '۞');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.005.segment.003', 'dua.hisn.027.part.005', 3, 'comment', 'en', 'Latn', 'qul huwa-llaahu ahad');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.005.segment.004', 'dua.hisn.027.part.005', 4, 'comment', 'en', 'Latn', '۞');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.005.segment.005', 'dua.hisn.027.part.005', 5, 'comment', 'en', 'Latn', 'allaahus-samad');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.005.segment.006', 'dua.hisn.027.part.005', 6, 'comment', 'en', 'Latn', '۞');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.005.segment.007', 'dua.hisn.027.part.005', 7, 'comment', 'en', 'Latn', 'lam yalid wa lam yoolad');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.005.segment.008', 'dua.hisn.027.part.005', 8, 'comment', 'en', 'Latn', '۞');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.005.segment.009', 'dua.hisn.027.part.005', 9, 'comment', 'en', 'Latn', 'wa lam yakul-lahu');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.005.segment.010', 'dua.hisn.027.part.005', 10, 'comment', 'en', 'Latn', 'ۥ');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.005.segment.011', 'dua.hisn.027.part.005', 11, 'comment', 'en', 'Latn', 'kufuwan ahad');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.005.segment.012', 'dua.hisn.027.part.005', 12, 'arabic', 'ar', 'Arab', 'سورَة الْفَلَقِ- بسْم ٱلله ٱلرَّحْمَـٰن ٱلرَّحيم');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.027.part.006', 'dua.hisn.027', 6);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.006.segment.001', 'dua.hisn.027.part.006', 1, 'arabic', 'ar', 'Arab', 'قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ ۞ مِنْ شَرِّ مَا خَلَقَ ۞ وَمِنْ شَرِّ غَاسِقٍ إِذَا وَقَبَ ۞ وَمِنْ شَرِّ النَّفَّاثَاتِ فِي الْعُقَدِ ۞ وَمِنْ شَرِّ حَاسِدٍ إِذَا حَسَدَ');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.006.segment.002', 'dua.hisn.027.part.006', 2, 'transliteration', 'ar-Latn', 'Latn', 'Surah Al-Falaq In the name of Allah, the Beneficent, the Merciful');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.006.segment.003', 'dua.hisn.027.part.006', 3, 'translation', 'en', 'Latn', 'Say:''I seek refuge with (Allah) the Lord of the daybreak, ۞ From the evil of what He has created; ۞ And from the evil of the darkening (night) as it comes with its darkness; (or the moon as it sets or goes away) ۞ And from the evil of those who practice witchcrafts when they blow in the knots, ۞ And from the evil of the envier when he envies. ۞''');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.027.part.007', 'dua.hisn.027', 7);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.007.segment.001', 'dua.hisn.027.part.007', 1, 'comment', 'en', 'Latn', 'bismillaahir-rahmaanir-raheem');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.007.segment.002', 'dua.hisn.027.part.007', 2, 'comment', 'en', 'Latn', '۞');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.007.segment.003', 'dua.hisn.027.part.007', 3, 'comment', 'en', 'Latn', 'qul a''oodhu birabbil-falaq');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.007.segment.004', 'dua.hisn.027.part.007', 4, 'comment', 'en', 'Latn', '۞');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.007.segment.005', 'dua.hisn.027.part.007', 5, 'comment', 'en', 'Latn', 'min sharri maa khalaq');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.007.segment.006', 'dua.hisn.027.part.007', 6, 'comment', 'en', 'Latn', '۞');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.007.segment.007', 'dua.hisn.027.part.007', 7, 'comment', 'en', 'Latn', 'wa min sharri ghaasiqin idhaa waqab');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.007.segment.008', 'dua.hisn.027.part.007', 8, 'comment', 'en', 'Latn', '۞');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.007.segment.009', 'dua.hisn.027.part.007', 9, 'comment', 'en', 'Latn', 'wa min sharrin-naffaathaati fil-''uqad');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.007.segment.010', 'dua.hisn.027.part.007', 10, 'comment', 'en', 'Latn', '۞');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.007.segment.011', 'dua.hisn.027.part.007', 11, 'comment', 'en', 'Latn', 'wa min sharri haasidin idhaa hasad');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.007.segment.012', 'dua.hisn.027.part.007', 12, 'arabic', 'ar', 'Arab', 'سورَة النَّاس - بسْم ٱلله ٱلرَّحْمَـٰن ٱلرَّحيم');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.027.part.008', 'dua.hisn.027', 8);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.008.segment.001', 'dua.hisn.027.part.008', 1, 'arabic', 'ar', 'Arab', 'قُلْ أَعُوذُ بِرَبِّ النَّاسِ ۞ مَلِكِ النَّاسِ ۞ إِلَهِ النَّاسِ ۞ مِنْ شَرِّ الْوَسْوَاسِ الْخَنَّاسِ ۞ الَّذِي يُوَسْوِسُ فِي صُدُورِ النَّاسِ ۞ مِنَ الْجِنَّةِ وَالنَّاسِ');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.008.segment.002', 'dua.hisn.027.part.008', 2, 'transliteration', 'ar-Latn', 'Latn', 'Surah An-Nas In the name of Allah, the Beneficent, the Merciful');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.008.segment.003', 'dua.hisn.027.part.008', 3, 'translation', 'en', 'Latn', 'Say:''I seek refuge with (Allah) the Lord of mankind, ۞ The King of mankind ۞ The Ilah (God) of mankind, ۞ From the evil of the whisperer (devil who whispers evil in the hearts of men) who withdraws (from his whispering in one''s heart after one remembers Allah), ۞ Who whispers in the breasts of mankind, ۞ Of jinn and men.۞');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.027.part.009', 'dua.hisn.027', 9);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.009.segment.001', 'dua.hisn.027.part.009', 1, 'comment', 'en', 'Latn', '۞');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.009.segment.002', 'dua.hisn.027.part.009', 2, 'comment', 'en', 'Latn', 'qul a''oodh-u birabbin-naas');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.009.segment.003', 'dua.hisn.027.part.009', 3, 'comment', 'en', 'Latn', '۞');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.009.segment.004', 'dua.hisn.027.part.009', 4, 'comment', 'en', 'Latn', 'malikin-naas');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.009.segment.005', 'dua.hisn.027.part.009', 5, 'comment', 'en', 'Latn', '۞');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.009.segment.006', 'dua.hisn.027.part.009', 6, 'comment', 'en', 'Latn', 'ilaahin-naas');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.009.segment.007', 'dua.hisn.027.part.009', 7, 'comment', 'en', 'Latn', '۞');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.009.segment.008', 'dua.hisn.027.part.009', 8, 'comment', 'en', 'Latn', 'min sharril-waswaasil-khannaas');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.009.segment.009', 'dua.hisn.027.part.009', 9, 'comment', 'en', 'Latn', '۞');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.009.segment.010', 'dua.hisn.027.part.009', 10, 'comment', 'en', 'Latn', 'alladhee yuwaswisu fee sudoorin-naas');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.009.segment.011', 'dua.hisn.027.part.009', 11, 'comment', 'en', 'Latn', '۞');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.009.segment.012', 'dua.hisn.027.part.009', 12, 'comment', 'en', 'Latn', 'minal-jinnati wan-naas');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.009.segment.013', 'dua.hisn.027.part.009', 13, 'comment', 'en', 'Latn', 'three times for it will suffice you (as a protection) agains everything.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.009.segment.014', 'dua.hisn.027.part.009', 14, 'arabic', 'ar', 'Arab', 'أَصْبَحْنَا وَأَصْبَحَ الْمُلْكُ للهِ وَالْحَمْدُ للهِ، لَا إِلَهَ إِلَّا اللهُ وَحَدْهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، ربِّ أَسْأَلُكَ خَيْرَ مَا فِي هَذَا الْيَومِ وَخَيْرَ مَا بَعْدَهُ، وَأَعُوذُ بِكَ مِنْ شَرِّ مَا فِي هَذَا الْيَومِ وَشَرِّ مَا بَعْدَهُ، رَبِّ أَعُوذُ بِكَ مِنَ الْكَسَلِ، وَسُوءِ الكِبَرِ، رَبِّ أَعُوذُ بِكَ مِنْ عَذَابٍ فِي النَّارِ وَعَذَابٍ فِي الْقَبْرِ');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.009.segment.015', 'dua.hisn.027.part.009', 15, 'transliteration', 'ar-Latn', 'Latn', 'We have reached the morning and at this very time unto Allah belongs all sovereignty and all praise is for Allah. None has the right to be worshipped except Allah, alone, without partner, to Him belongs all sovereignty and praise and He is capable of all things.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.009.segment.016', 'dua.hisn.027.part.009', 16, 'translation', 'en', 'Latn', 'My Lord, I ask You for the good of this day and the good of what follows it and I seek refuge with You from the evil of this day and the evil of what follows it.');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.027.part.010', 'dua.hisn.027', 10);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.010.segment.001', 'dua.hisn.027.part.010', 1, 'comment', 'en', 'Latn', 'My Lord, I seek refuge with You from laziness and senility. My Lord, I seek refuge with You from the torment in the Fire and the torment in the grave.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.010.segment.002', 'dua.hisn.027.part.010', 2, 'comment', 'en', 'Latn', 'asbahnaa wa asbah-al-mulku lillaahi wal-hamdu lillaahi, laa ilaaha ill-allaahu wahdahu laa shareeka lah, lahul-mulku wa lahul-hamdu, wa huwa ''alaa kulli shay’in qadeer, rabbi as’aluka khayra maa fee haadhal-yawmi wa khayra maa ba''dahu, wa a''oodhu bika min sharri haadhal-yawmi wa sharri maa ba''dahu,rabbi a''oodhu bika minal-kasali wa soo’il-kibari, rabbi a''oodhu bika min ''adhaabin fin-naari wa ''adhaabin fil-qabr');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.010.segment.003', 'dua.hisn.027.part.010', 3, 'arabic', 'ar', 'Arab', 'اللَّهُمَّ بِكَ أَصْبَحْنَا، وَبِكَ أَمْسَيْنَا، وَبِكَ نَحْيَا، وَبِكَ نَمُوتُ وَإِلَيْكَ النُّشُورُ');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.010.segment.004', 'dua.hisn.027.part.010', 4, 'transliteration', 'ar-Latn', 'Latn', 'allaahumma bika asbahnaa wa bika amsaynaa, wa bika nahyaa wa bika namootu wa ilayk-an-nushoor');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.010.segment.005', 'dua.hisn.027.part.010', 5, 'translation', 'en', 'Latn', 'O Allah, by your leave we have reached the morning and by Your leave we have reached the evening, by Your leave we live and die and unto You is our resurrection.');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.027.part.011', 'dua.hisn.027', 11);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.011.segment.001', 'dua.hisn.027.part.011', 1, 'arabic', 'ar', 'Arab', 'اللَّهُمَّ أَنْتَ رَبِّي لّا إِلَهَ إِلَّا أَنْتَ، خَلَقْتَنِي وَأَنَا عَبْدُكَ، وَأَنَا عَلَى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ، أَعُوذُ بِكَ مِنْ شَرِّ مَا صَنَعْتُ، أَبُوءُ لَكَ بِنِعْمَتِكَ عَلَيَّ، وَأَبُوءُ بِذَنْبِي فَاغْفِر لِي فَإِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.011.segment.002', 'dua.hisn.027.part.011', 2, 'transliteration', 'ar-Latn', 'Latn', 'allaahumma anta rabbiy laa ilaaha illaa anta, khalaqtanee wa ana ''abduka, wa ana ''alaa ''ahdika wa wa''dika masta-ṭa''tu a''oodhu bika min sharri maa sana''tu, aboo’u laka bi ni''matika ''alayya wa aboo’u bi dhambee, faghfir lee fa innahu laa yaghfir-udh-dhunooba illaa ant');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.011.segment.003', 'dua.hisn.027.part.011', 3, 'translation', 'en', 'Latn', '‘O Allaah, You are my Lord, none has the right to be worshipped except You, You created me and I am You servant and I abide to Your covenant and promise as best I can, I take refuge in You from the evil of which I committed. I acknowledge Your favour upon me and I acknowledge my sin, so forgive me, for verily none can forgive sin except You.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.027.part.012', 'dua.hisn.027', 12);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.012.segment.001', 'dua.hisn.027.part.012', 1, 'arabic', 'ar', 'Arab', 'اللَّهُمَّ إِنِّي أَصْبَحْتُ أُشْهِدُكَ وَأُشْهِدُ حَمَلَةَ عَرْشِكَ، وَمَلَائِكَتَكَ وَجَمِيعَ خَلْقِكَ، أَنَّكَ أَنْتَ اللهُ لَا إِلَهَ إِلَّا أَنْتَ وَحْدَكَ لَا شَرِيكَ لَكَ، وَأَنَّ مُحَمَّداً عَبْدُكَ وَرَسُولُكَ(اربع مرات)');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.012.segment.002', 'dua.hisn.027.part.012', 2, 'transliteration', 'ar-Latn', 'Latn', 'Allaahumma''innee''asbahtu''ush-hiduka wa''ush-hidu hamalata''arshika, wa malaa''ikataka wajamee''a khalqika,''annaka''Antallaahu laa''ilaaha''illaa''Anta wahdaka laa shareeka laka, wa''anna Muhammadan''abduka wa Rasooluka.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.012.segment.003', 'dua.hisn.027.part.012', 3, 'translation', 'en', 'Latn', 'O Allah , I have entered a new morning 1 and call upon You and upon the bearers of Your Throne , upon Your angels and all creation to bear witness that surely You are Allah , there is none worthy of worship but You alone , You have no partners, and that Muhammad is Your slave and Your Messenger. (Recite four times)');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.027.part.013', 'dua.hisn.027', 13);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.013.segment.001', 'dua.hisn.027.part.013', 1, 'arabic', 'ar', 'Arab', 'االلَّهُمَّ مَا أَصْبَحَ بِي مِنْ نِعْمَةٍ أَوْ بِأَحَدٍ مِنْ خَلْقِكَ فَمِنْكَ وَحْدَكَ لَا شَرِيكَ لَكَ، فَلَكَ الْحَمْدُ وَلَكَ الشُّكْرُ');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.013.segment.002', 'dua.hisn.027.part.013', 2, 'transliteration', 'ar-Latn', 'Latn', 'Allaahumma maa''asbaha bee min ni''matin''aw bi''ahadin min khalqika faminka wahdaka laa shareeka laka, falakal-hamdu wa lakash-shukru.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.013.segment.003', 'dua.hisn.027.part.013', 3, 'translation', 'en', 'Latn', 'O Allah , whatever blessing has been received by me or anyone of Your creation 1 is from You alone , You have no partner. All praise is for you and thanks is to You.');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.027.part.014', 'dua.hisn.027', 14);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.014.segment.001', 'dua.hisn.027.part.014', 1, 'arabic', 'ar', 'Arab', 'اللّهُـمَّ عافِـني في بَدَنـي، اللّهُـمَّ عافِـني في سَمْـعي، اللّهُـمَّ عافِـني في بَصَـري، لا إلهَ إلاّ أَنْـتَ..(ثلاثاً)');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.027.part.015', 'dua.hisn.027', 15);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.015.segment.001', 'dua.hisn.027.part.015', 1, 'arabic', 'ar', 'Arab', 'اللّهُـمَّ إِنّـي أَعـوذُبِكَ مِنَ الْكُـفر، وَالفَـقْر، وَأَعـوذُبِكَ مِنْ عَذابِ القَـبْر، لا إلهَ إلاّ أَنْـتَ.(ثلاثاً)');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.015.segment.002', 'dua.hisn.027.part.015', 2, 'transliteration', 'ar-Latn', 'Latn', 'Allaahumma''aafinee fee badanee, Allaahumma''aafinee fee sam''ee, Allaahumma''aafinee fee basaree, laa''ilaaha''illaa''Anta (three times).');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.015.segment.003', 'dua.hisn.027.part.015', 3, 'translation', 'en', 'Latn', 'O Allah, make me healthy in my body. O Allah, preserve for me my hearing. O Allah, preserve for me my sight. There is none worthy of worship but You. (Recite three times)');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.015.segment.004', 'dua.hisn.027.part.015', 4, 'translation', 'en', 'Latn', 'O Allah , I seek refuge in You from disbelief and poverty and I seek refuge in You from the punishment of the grave. There is none worthy of worship but You. (Recite three times)');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.027.part.016', 'dua.hisn.027', 16);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.016.segment.001', 'dua.hisn.027.part.016', 1, 'comment', 'en', 'Latn', 'Allaahumma''innee''a''oothu bika minal-kufri, walfaqri, wa''a''oothu bika min''athaabil-qabri, laa''ilaaha''illaa''Anta. (three times)');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.016.segment.002', 'dua.hisn.027.part.016', 2, 'arabic', 'ar', 'Arab', 'حَسْبيَ الله لَآ إلَهَ إلَّا هوَ عَلَيْه تَوَكَّلْت وَهوَ رَبّ الْعَرْش الْعَظيم (سبع مرات)');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.016.segment.003', 'dua.hisn.027.part.016', 3, 'transliteration', 'ar-Latn', 'Latn', 'Allah is sufficient for me. There is none worthy of worship but Him. I have placed my trust in Him, He is Lord of the Majestic Throne. (Recite seven times)');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.016.segment.004', 'dua.hisn.027.part.016', 4, 'translation', 'en', 'Latn', 'Hasbiyallaahu laa''ilaaha''illaa Huwa''alayhi tawakkaltu wa Huwa Rabbul-''Arshil-''Adheem.');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.027.part.017', 'dua.hisn.027', 17);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.017.segment.001', 'dua.hisn.027.part.017', 1, 'arabic', 'ar', 'Arab', 'اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِي الدُّنْيَا وَالْآخِرَةِ، اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِي دِينِي وَدُنْيَايَ وَأَهْللِي، وَمَالِي، اللَّهُمَّ اسْتُرْ عَوْرَاتِي، وَآمِنْ رَوْعَاتِي، اللَّهُمَّ احْفَظْنِي مِنْ بَيْنِ يَدَيَّ، وَمِنْ خَلْفِي، وَعَنْ يَمِينِي، وَعَنْ شِمَالِي، وَمِنْ فَوْقِي، وَأَعُوذُ بِعَظَمَتِكَ أَنْ أُغْتَالَ مِنْ تَحْتِي');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.017.segment.002', 'dua.hisn.027.part.017', 2, 'transliteration', 'ar-Latn', 'Latn', 'Allaahumma''innee''as''alukal-''afwa wal''aafiyata fid-dunyaa wal''aakhirati, Allaahumma''innee''as''alukal-''afwa wal''aafiyata fee deenee wa dunyaaya wa''ahlee, wa maalee , Allaahum-mastur''awraatee, wa''aamin raw''aatee, Allaahum-mahfadhnee min bayni yadayya, wa min khalfee, wa''an yameenee, wa''an shimaalee, wa min fawqee, wa''a''oothu bi''adhamatika''an''ughtaala min tahtee.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.017.segment.003', 'dua.hisn.027.part.017', 3, 'translation', 'en', 'Latn', 'O Allah, I seek Your forgiveness and Your protection in this world and the next. O Allah, I seek Your forgiveness and Your protection in my religion, in my worldly affairs, in my family and in my wealth. O Allah, conceal my secrets and preserve me from anguish. O Allah , guard me from what is in front of me and behind me , from my left , and from my right , and from above me. I seek refuge in Your Greatness from being struck down from beneath me.');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.027.part.018', 'dua.hisn.027', 18);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.018.segment.001', 'dua.hisn.027.part.018', 1, 'arabic', 'ar', 'Arab', 'اللَّهُمَّ عَالِمَ الْغَيْبِ وَالشَّهَادَةِ فَاطِرَ السَّماوَاتِ وَالْأَرْضِ، رَبَّ كُلِّ شَيْءٍ وَمَلِيكَهُ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ، أَعُوذُ بِكَ مِنْ شَرِّ نَفْسِي، وَمِنْ شَرِّ الشَّيْطَانِ وَشِرْكِهِ، وَأَنْ أَقْتَرِفَ عَلَى نَفْسِي سُوءاً، أَوْ أَجُرَّهُ إِلَى مُسْلِمٍ');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.018.segment.002', 'dua.hisn.027.part.018', 2, 'transliteration', 'ar-Latn', 'Latn', 'Allaahumma''Aalimal-ghaybi wash-shahaadati faatiras-samaawaati wal''ardhi, Rabba kulli shay''in wa maleekahu,''ash-hadu''an laa''ilaaha''illaa''Anta,''a''oothu bika min sharri nafsee, wa min sharrish-shaytaani wa shirkihi, wa''an''aqtarifa''alaa nafsee soo''an,''aw''ajurrahu''ilaa Muslimin.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.018.segment.003', 'dua.hisn.027.part.018', 3, 'translation', 'en', 'Latn', 'O Allah, Knower of the unseen and the evident , Maker of the heavens and the earth , Lord of everything and its Possessor , I bear witness that there is none worthy of worship but You. I seek refuge in You from the evil of my soul and from the evil of Satan and his helpers. (I seek refuge in You) from bringing evil upon my soul and from harming any Muslim.');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.027.part.019', 'dua.hisn.027', 19);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.019.segment.001', 'dua.hisn.027.part.019', 1, 'arabic', 'ar', 'Arab', 'بِسْمِ اللهِ الَّذِي لَا يَضُرُّ مَعَ اسْمِهِ شَيْءٌ فِي الْأَرْضِ وَلَا فِي السَّمَاءِ وَهُوَ السَّمِيعُ الْعَلِيمُ (ثلاثا)');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.019.segment.002', 'dua.hisn.027.part.019', 2, 'transliteration', 'ar-Latn', 'Latn', 'Bismillaahil-lathee laa yadhurru ma''as-mihi shay''un fil-''ardhi wa laa fis-samaa''i wa Huwas-Samee''ul-''Aleem.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.019.segment.003', 'dua.hisn.027.part.019', 3, 'translation', 'en', 'Latn', 'In the Name of Allah, Who with His Name nothing can cause harm in the earth nor in the heavens, and He is the All-Hearing, the All-Knowing. (Recite three times)');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.027.part.020', 'dua.hisn.027', 20);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.020.segment.001', 'dua.hisn.027.part.020', 1, 'arabic', 'ar', 'Arab', 'رَضيت بالله رَبَّاً، وَبالْإسْلَام ديناً، وَبمحَمَّد صَلَى الله عَليه وَسَلَّمَ نَبيَّاً (ثلاثا)');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.020.segment.002', 'dua.hisn.027.part.020', 2, 'transliteration', 'ar-Latn', 'Latn', 'I am pleased with Allah as my Lord, with Islam as my religion and with Muhammad (peace and blessings of Allah be upon him) as my Prophet (saws). (Recite three times)');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.020.segment.003', 'dua.hisn.027.part.020', 3, 'translation', 'en', 'Latn', 'Radheetu billaahi Rabban, wa bil-''Islaami deenan, wa bi-Muhammadin (sallallaahu''alayhi wa sallama) Nabiyyan.');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.027.part.021', 'dua.hisn.027', 21);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.021.segment.001', 'dua.hisn.027.part.021', 1, 'arabic', 'ar', 'Arab', 'يَا حَيُّ يَا قَيُّومُ بِرَحْمَتِكَ أَسْتَغِيثُ أَصْلِحْ لِي شَأْنِي كُلَّهُ وَلَا تَكِلْنِي إِلَى نَفْسِي طَرْفَةَ عَيْنٍ');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.021.segment.002', 'dua.hisn.027.part.021', 2, 'transliteration', 'ar-Latn', 'Latn', 'O Ever Living One, O Eternal One, by Your mercy I call on You to set right all my affairs. Do not place me in charge of my soul even for the blinking of an eye');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.021.segment.003', 'dua.hisn.027.part.021', 3, 'translation', 'en', 'Latn', 'Yaa Hayyu yaa Qayyoomu birahmatika''astagheethu''aslih lee sha''nee kullahu wa laa takilnee''ilaa nafsee tarfata''aynin.');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.027.part.022', 'dua.hisn.027', 22);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.022.segment.001', 'dua.hisn.027.part.022', 1, 'arabic', 'ar', 'Arab', 'أَصْبَـحْـنا وَأَصْبَـحْ المـلك لله رَبّ العـالَمـين، اللّهـمَّ إنّـي أسْـأَلـكَ خَـيْرَ هـذا الـيَوْم،فـتْحَه، وَنَصْـرَه، وَنـورَه وَبَـرَكَتَـه، وَهـداه، وَأَعـوذ بـكَ مـنْ شَـرّ ما فـيه وَشَـرّ ما بَعْـدَه.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.022.segment.002', 'dua.hisn.027.part.022', 2, 'transliteration', 'ar-Latn', 'Latn', 'We have entered a new day and with it all the dominion which belongs to Allah, Lord of all that exists. O Allah, I ask You for the goodness of this day,2 its victory, its help, its light, its blessings, and its guidance. I seek refuge in You from the evil that is in it and from the evil that follows it.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.022.segment.003', 'dua.hisn.027.part.022', 3, 'translation', 'en', 'Latn', '''Asbahnaa wa''asbahal-mulku lillaahi Rabbil-''aalameen, Allaahumma''innee''as''aluka khayra haathal-yawmi: Fathahu wa nasrahu wa noorahu, wa barakatahu, wa hudaahu, wa''a''oothu bika min sharri maafeehi wa sharri maa ba''dahu.');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.027.part.023', 'dua.hisn.027', 23);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.023.segment.001', 'dua.hisn.027.part.023', 1, 'arabic', 'ar', 'Arab', 'أَصْبَحْنَا عَلَى فطْرَة الْإسْلَام وَعَلَى كَلمَة الْإخْلَاص، وَعَلَى دين نَبيّنَا محَمَّد صَلَى الله عَليه وَسَلَّمَ، وَعَلَى ملَّة أَبينَا إبْرَاهيمَ، حَنيَفاً مسْلماً وَمَا كَانَ منَ الْمشْركينَ');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.023.segment.002', 'dua.hisn.027.part.023', 2, 'transliteration', 'ar-Latn', 'Latn', 'We have entered a new day upon the natural religion of Islam, the word of sincere devotion, the religion of our Prophet (saws) Muhammad (peace and blessings of Allah be upon him), and the faith of our father Ibrahim. He was upright (in worshipping Allah), and a Muslim. He was not of those who worship others besides Allah.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.023.segment.003', 'dua.hisn.027.part.023', 3, 'translation', 'en', 'Latn', '''Asbahnaa''alaa fitratil-''Islaami wa''alaa kalimatil-''ikhlaasi, wa''alaa deeni Nabiyyinaa Muhammadin (sallallaahu''alayhi wa sallama), wa''alaa millati''abeenaa''Ibraaheema, haneefan Musliman wa maa kaana minal-mushrikeen.');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.027.part.024', 'dua.hisn.027', 24);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.024.segment.001', 'dua.hisn.027.part.024', 1, 'arabic', 'ar', 'Arab', 'سبْحَانَ اللَّه وَبحَمْده (مئة مرة)');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.024.segment.002', 'dua.hisn.027.part.024', 2, 'transliteration', 'ar-Latn', 'Latn', 'Glory is to Allah and praise is to Him. (Recite one hundred times)');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.024.segment.003', 'dua.hisn.027.part.024', 3, 'translation', 'en', 'Latn', 'Subhaanallaahi wa bihamdihi.');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.027.part.025', 'dua.hisn.027', 25);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.025.segment.001', 'dua.hisn.027.part.025', 1, 'arabic', 'ar', 'Arab', 'لا إلهَ إلاّ اللّه وحْـدَه لا شَـريكَ له، له المـلْك وله الحَمْـد، وهوَ على كلّ شَيء قَدير. (مائة مرة)');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.025.segment.002', 'dua.hisn.027.part.025', 2, 'transliteration', 'ar-Latn', 'Latn', 'Laa''ilaaha''illallaahu wahdahu laa shareeka lahu, lahul-mulku wa lahul-hamdu, wa Huwa''alaa kulli shay''in Qadeer.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.025.segment.003', 'dua.hisn.027.part.025', 3, 'translation', 'en', 'Latn', 'None has the right to be worshipped but Allah alone, Who has no partner. His is the dominion and His is the praise and He is Able to do all things.');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.027.part.026', 'dua.hisn.027', 26);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.026.segment.001', 'dua.hisn.027.part.026', 1, 'arabic', 'ar', 'Arab', 'سبْحَانَ الله وَبحَمْده عَدَدَ خَلْقه، وَرضَا نَفسه، وَزنَةَ عَرْشه، وَمدَادَ كَلمَاته (ثلاث مرات)');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.026.segment.002', 'dua.hisn.027.part.026', 2, 'transliteration', 'ar-Latn', 'Latn', 'Glory is to Allah and praise is to Him, by the multitude of His creation, by His Pleasure, by the weight of His Throne, and by the extent of His Words. (Recite three times)');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.026.segment.003', 'dua.hisn.027.part.026', 3, 'translation', 'en', 'Latn', 'Subhaanallaahi wa bihamdihi:''Adada khalqihi, wa ridhaa nafsihi, wa zinata''arshihi wa midaada kalimaatihi.');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.027.part.027', 'dua.hisn.027', 27);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.027.segment.001', 'dua.hisn.027.part.027', 1, 'arabic', 'ar', 'Arab', 'اللَّهمَّ إنّي أَسْأَلكَ علْماً نَافعاً، وَرزقاً طَيّباً، وَعَمَلاً متَقَبَّلاً');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.027.segment.002', 'dua.hisn.027.part.027', 2, 'transliteration', 'ar-Latn', 'Latn', 'Allaahumma''innee''as''aluka''ilman naafi''an, wa rizqan tayyiban, wa''amalan mutaqabbalan.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.027.segment.003', 'dua.hisn.027.part.027', 3, 'translation', 'en', 'Latn', 'O Allah, I ask You for knowledge that is of benefit , a good provision , and deeds that will be accepted.');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.027.part.028', 'dua.hisn.027', 28);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.028.segment.001', 'dua.hisn.027.part.028', 1, 'arabic', 'ar', 'Arab', 'أَسْتَغْفر اللهَ وَأَتوب إلَيْه (مائة مرة)');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.028.segment.002', 'dua.hisn.027.part.028', 2, 'transliteration', 'ar-Latn', 'Latn', 'I seek the forgiveness of Allah and repent to Him. (Recite one hundred times)');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.028.segment.003', 'dua.hisn.027.part.028', 3, 'translation', 'en', 'Latn', '''Astaghfirullaaha wa''atoobu''ilayhi.');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.027.part.029', 'dua.hisn.027', 29);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.029.segment.001', 'dua.hisn.027.part.029', 1, 'arabic', 'ar', 'Arab', 'اللَّهمَّ صَلّ وَسَلَّمْ عَلَى نَبيّنَا محَمَّد (عشر مرات)');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.029.segment.002', 'dua.hisn.027.part.029', 2, 'transliteration', 'ar-Latn', 'Latn', 'Oh Allah, we ask you for peace and blessings upon our Prophet (saws) Muhammad (Recite ten times)');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.027.part.029.segment.003', 'dua.hisn.027.part.029', 3, 'translation', 'en', 'Latn', 'Allahumma salli wa sallim''alaa nabiyyinaa Muhammadin');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.028', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-028', 28, 'Remembrance before sleeping', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.028.part.001', 'dua.hisn.028', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.028.part.001.segment.001', 'dua.hisn.028.part.001', 1, 'arabic', 'ar', 'Arab', 'سورَة الإخْلَاص - بسْم ٱلله ٱلرَّحْمَـٰن ٱلرَّحيم');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.028.part.002', 'dua.hisn.028', 2);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.028.part.002.segment.001', 'dua.hisn.028.part.002', 1, 'arabic', 'ar', 'Arab', 'قُلْ هُوَ اللهُ أَحَدٌ ۞ اللهُ الصَّمَدُ ۞ لَمْ يَلِدْ وَلَمْ يُولَدْ ۞ وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.028.part.002.segment.002', 'dua.hisn.028.part.002', 2, 'transliteration', 'ar-Latn', 'Latn', 'Surah Al-Ikhlas In the name of Allah, the Beneficent, the Merciful');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.028.part.002.segment.003', 'dua.hisn.028.part.002', 3, 'translation', 'en', 'Latn', 'Say (O Muhammad (SAW)):''He is Allah, (the) One.۞ Allah the Self-Sufficient Master, Whom all creatures need, (He neither eats nor drinks). ۞ He begets not, nor was He begotten. ۞ And there is none co-equal or comparable unto Him.۞''');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.028.part.003', 'dua.hisn.028', 3);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.028.part.003.segment.001', 'dua.hisn.028.part.003', 1, 'comment', 'en', 'Latn', 'bismillaahir-rahmaanir-raheem');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.028.part.003.segment.002', 'dua.hisn.028.part.003', 2, 'comment', 'en', 'Latn', '۞');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.028.part.003.segment.003', 'dua.hisn.028.part.003', 3, 'comment', 'en', 'Latn', 'qul huwa-llaahu ahad');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.028.part.003.segment.004', 'dua.hisn.028.part.003', 4, 'comment', 'en', 'Latn', '۞');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.028.part.003.segment.005', 'dua.hisn.028.part.003', 5, 'comment', 'en', 'Latn', 'allaahus-samad');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.028.part.003.segment.006', 'dua.hisn.028.part.003', 6, 'comment', 'en', 'Latn', '۞');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.028.part.003.segment.007', 'dua.hisn.028.part.003', 7, 'comment', 'en', 'Latn', 'lam yalid wa lam yoolad');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.028.part.003.segment.008', 'dua.hisn.028.part.003', 8, 'comment', 'en', 'Latn', '۞');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.028.part.003.segment.009', 'dua.hisn.028.part.003', 9, 'comment', 'en', 'Latn', 'wa lam yakul-lahu');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.028.part.003.segment.010', 'dua.hisn.028.part.003', 10, 'comment', 'en', 'Latn', 'ۥ');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.028.part.003.segment.011', 'dua.hisn.028.part.003', 11, 'comment', 'en', 'Latn', 'kufuwan ahad');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.028.part.003.segment.012', 'dua.hisn.028.part.003', 12, 'arabic', 'ar', 'Arab', 'سورَة الْفَلَقِ - بسْم ٱلله ٱلرَّحْمَـٰن ٱلرَّحيم');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.028.part.004', 'dua.hisn.028', 4);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.028.part.004.segment.001', 'dua.hisn.028.part.004', 1, 'arabic', 'ar', 'Arab', 'قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ ۞ مِنْ شَرِّ مَا خَلَقَ ۞ وَمِنْ شَرِّ غَاسِقٍ إِذَا وَقَبَ ۞ وَمِنْ شَرِّ النَّفَّاثَاتِ فِي الْعُقَدِ ۞ وَمِنْ شَرِّ حَاسِدٍ إِذَا حَسَدَ');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.028.part.004.segment.002', 'dua.hisn.028.part.004', 2, 'transliteration', 'ar-Latn', 'Latn', 'Surah Al-Falaq In the name of Allah, the Beneficent, the Merciful');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.028.part.004.segment.003', 'dua.hisn.028.part.004', 3, 'translation', 'en', 'Latn', 'Say:''I seek refuge with (Allah) the Lord of the daybreak, ۞ From the evil of what He has created; ۞ And from the evil of the darkening (night) as it comes with its darkness; (or the moon as it sets or goes away) ۞ And from the evil of those who practice witchcrafts when they blow in the knots, ۞ And from the evil of the envier when he envies. ۞''');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.028.part.005', 'dua.hisn.028', 5);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.028.part.005.segment.001', 'dua.hisn.028.part.005', 1, 'comment', 'en', 'Latn', 'bismillaahir-rahmaanir-raheem');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.028.part.005.segment.002', 'dua.hisn.028.part.005', 2, 'comment', 'en', 'Latn', '۞');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.028.part.005.segment.003', 'dua.hisn.028.part.005', 3, 'comment', 'en', 'Latn', 'qul a''oodhu birabbil-falaq');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.028.part.005.segment.004', 'dua.hisn.028.part.005', 4, 'comment', 'en', 'Latn', '۞');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.028.part.005.segment.005', 'dua.hisn.028.part.005', 5, 'comment', 'en', 'Latn', 'min sharri maa khalaq');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.028.part.005.segment.006', 'dua.hisn.028.part.005', 6, 'comment', 'en', 'Latn', '۞');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.028.part.005.segment.007', 'dua.hisn.028.part.005', 7, 'comment', 'en', 'Latn', 'wa min sharri ghaasiqin idhaa waqab');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.028.part.005.segment.008', 'dua.hisn.028.part.005', 8, 'comment', 'en', 'Latn', '۞');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.028.part.005.segment.009', 'dua.hisn.028.part.005', 9, 'comment', 'en', 'Latn', 'wa min sharrin-naffaathaati fil-''uqad');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.028.part.005.segment.010', 'dua.hisn.028.part.005', 10, 'comment', 'en', 'Latn', '۞');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.028.part.005.segment.011', 'dua.hisn.028.part.005', 11, 'comment', 'en', 'Latn', 'wa min sharri haasidin idhaa hasad');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.028.part.005.segment.012', 'dua.hisn.028.part.005', 12, 'arabic', 'ar', 'Arab', 'سورَة النَّاس - بسْم ٱلله ٱلرَّحْمَـٰن ٱلرَّحيم');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.028.part.006', 'dua.hisn.028', 6);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.028.part.006.segment.001', 'dua.hisn.028.part.006', 1, 'arabic', 'ar', 'Arab', 'قلْ أَعوذ برَبّ ٱلنَّاس ۞ مَلك ٱلنَّاس ۞ إلَـٰه ٱلنَّاس ۞ من شَرّ ٱلْوَسْوَاس ٱلْخَنَّاس ۞ ٱلَّذى يوَسْوس فِي صدور ٱلنَّاس ۞ منَ ٱلْجنَّة وَٱلنَّاس ۞');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.028.part.006.segment.002', 'dua.hisn.028.part.006', 2, 'transliteration', 'ar-Latn', 'Latn', 'Surah An-Nas In the name of Allah, the Beneficent, the Merciful');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.028.part.006.segment.003', 'dua.hisn.028.part.006', 3, 'translation', 'en', 'Latn', 'Say:''I seek refuge with (Allah) the Lord of mankind, ۞ The King of mankind ۞ The Ilah (God) of mankind, ۞ From the evil of the whisperer (devil who whispers evil in the hearts of men) who withdraws (from his whispering in one''s heart after one remembers Allah), ۞ Who whispers in the breasts of mankind, ۞ Of jinn and men.۞');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.028.part.007', 'dua.hisn.028', 7);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.028.part.007.segment.001', 'dua.hisn.028.part.007', 1, 'comment', 'en', 'Latn', '۞');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.028.part.007.segment.002', 'dua.hisn.028.part.007', 2, 'comment', 'en', 'Latn', 'qul a''oodh-u birabbin-naas');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.028.part.007.segment.003', 'dua.hisn.028.part.007', 3, 'comment', 'en', 'Latn', '۞');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.028.part.007.segment.004', 'dua.hisn.028.part.007', 4, 'comment', 'en', 'Latn', 'malikin-naas');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.028.part.007.segment.005', 'dua.hisn.028.part.007', 5, 'comment', 'en', 'Latn', '۞');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.028.part.007.segment.006', 'dua.hisn.028.part.007', 6, 'comment', 'en', 'Latn', 'ilaahin-naas');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.028.part.007.segment.007', 'dua.hisn.028.part.007', 7, 'comment', 'en', 'Latn', '۞');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.028.part.007.segment.008', 'dua.hisn.028.part.007', 8, 'comment', 'en', 'Latn', 'min sharril-waswaasil-khannaas');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.028.part.007.segment.009', 'dua.hisn.028.part.007', 9, 'comment', 'en', 'Latn', '۞');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.028.part.007.segment.010', 'dua.hisn.028.part.007', 10, 'comment', 'en', 'Latn', 'alladhee yuwaswisu fee sudoorin-naas');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.028.part.007.segment.011', 'dua.hisn.028.part.007', 11, 'comment', 'en', 'Latn', '۞');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.028.part.007.segment.012', 'dua.hisn.028.part.007', 12, 'comment', 'en', 'Latn', 'minal-jinnati wan-naas');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.028.part.007.segment.013', 'dua.hisn.028.part.007', 13, 'arabic', 'ar', 'Arab', 'أية الكرسي -بسْم ٱلله ٱلرَّحْمَـٰن ٱلرَّحيم');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.028.part.007.segment.014', 'dua.hisn.028.part.007', 14, 'transliteration', 'ar-Latn', 'Latn', '''');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.028.part.008', 'dua.hisn.028', 8);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.028.part.008.segment.001', 'dua.hisn.028.part.008', 1, 'arabic', 'ar', 'Arab', 'أَعُوذُ بِاللهِ مِنَ الشَّيْطَانِ الرَّجِيمِ اللهُ لَا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ لَا تَأْخُذُهُ سِنَةٌ وَلَا نَوْمٌ لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ مَنْ ذَا الَّذِي يَشْفَعُ عِنْدَهُ إِلَّا بِإِذْنِهِ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلَا يُحِيطُونَ بِشَيْءٍ مِنْ عِلْمِهِ إِلَّا بِمَا شَاءَ وَسِعَ كُرْسِيُّهُ السَّمَاوَاتِ وَالْأَرْضَ وَلَا يَئُودُهُ حِفْظُهُمَا وَهُوَ الْعَلِيُّ الْعَظِيمُ.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.028.part.008.segment.002', 'dua.hisn.028.part.008', 2, 'transliteration', 'ar-Latn', 'Latn', '''.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.028.part.008.segment.003', 'dua.hisn.028.part.008', 3, 'translation', 'en', 'Latn', 'Ayat al Kursi');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.028.part.009', 'dua.hisn.028', 9);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.028.part.009.segment.001', 'dua.hisn.028.part.009', 1, 'comment', 'en', 'Latn', 'Allah! There is none worthy of worship but He, the Ever Living, the One Who sustains and protects all that exists. Neither slumber nor sleep overtakes Him. To Him belongs whatever is in the heavens and whatever is on the earth. Who is he that can intercede with Him except with His Permission? He knows what happens to them in this world, and what will happen to them in the Hereafter. And they will never encompass anything of His Knowledge except that which He wills. His Throne extends over the heavens and the earth, and He feels no fatigue in guarding and preserving them. And He is the Most High, the Most Great.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.028.part.009.segment.002', 'dua.hisn.028.part.009', 2, 'comment', 'en', 'Latn', 'Allaahu laa''ilaaha''illaa Huwal-Hayyul-Qayyoom, laa ta''khuthuhu sinatun wa laa nawm, lahu maa fis-samaawaati wa maa fil-''ardh, man thal-lathee yashfa''u''indahu''illaa bi''ithnihi, ya''lamu maa bayna''aydeehim wa maa khalfahum, wa laa yuheetoona bishay''im-min''ilmihi''illaa bimaa shaa''a, wasi''a kursiyyuhus-samaawaati wal''ardha, wa laa ya''ooduhu hifdhuhumaa, wa Huwal-''Aliyyul-''Adheem.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.028.part.009.segment.003', 'dua.hisn.028.part.009', 3, 'comment', 'en', 'Latn', 'The Messenger believes in what has been send down to him from his Lord, and so do the believers. Each one believes in Allah, His Angels, His Books, and His Messengers. They say:''We make no distinction between any of His Messengers,''and they say:''We hear, and we obey. (We seek) Your Forgiveness, our Lord, and to You is the return.''Allah burdens not a person beyond what he can bear. He gets reward for that (good) which he has earned, and he is punished for that (evil) which he has earned. Our Lord! Punish us not if we forget or fall into error. Our Lord! Lay not on us a burden like that which You did lay on those before us. Our Lord! Put not on us a burden greater than we have strength to bear. Pardon us and grant us forgiveness. Have mercy on us. You are our Protector, and help us against the disbelieving people.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.028.part.009.segment.004', 'dua.hisn.028.part.009', 4, 'arabic', 'ar', 'Arab', 'آمَنَ الرَّسُولُ بِمَا أُنْزِلَ إِلَيْهِ مِنْ رَبِّهِ وَالْمُؤْمِنُونَ كُلٌّ آمَنَ بِاللهِ وَمَلَائِكَتِهِ وَكُتُبِهِ وَرُسُلِهِ لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِنْ رُسُلِهِ وَقَالُوا سَمِعْنَا وَأَطَعْنَا غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ الْمَصِيرُ ۞ لَا يُكَلِّفُ اللهُ نَفْسًا إِلَّا وُسْعَهَا لَهَا مَا كَسَبَتْ وَعَلَيْهَا مَا اكْتَسَبَتْ رَبَّنَا لَا تُؤَاخِذْنَا إِنْ نَسِينَا أَوْ أَخْطَأْنَا رَبَّنَا وَلَا تَحْمِلْ عَلَيْنَا إِصْرًا كَمَا حَمَلْتَهُ عَلَى الَّذِينَ مِنْ قَبْلِنَا رَبَّنَا وَلَا تُحَمِّلْنَا مَا لَا طَاقَةَ لَنَا بِهِ وَاعْفُ عَنَّا وَاغْفِرْ لَنَا وَارْحَمْنَا أَنْتَ مَوْلَانَا فَانْصُرْنَا عَلَى الْقَوْمِ الْكَافِرِينَ');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.028.part.009.segment.005', 'dua.hisn.028.part.009', 5, 'transliteration', 'ar-Latn', 'Latn', '''Aamanar-Rasoolu bimaa''unzila mir-Rabbihi walmu''minoon, kullun''aamana billaahi wa malaa''ikatihi wa Kutubihi wa Rusulihi, laa nufarriqu bayna''ahadim-mir-Rusulihi, wa qaaloo sami''naa wa''ata''naa ghufraanaka Rabbanaa wa''ilaykal-maseer. Laa yukallifullaahu nafsan''illaa wus''ahaa, lahaa maa kasabat wa''alayhaa mak-tasabat, Rabbanaa laa tu''aakhithnaa''in naseenaa''aw''akhta''naa, Rabbanaa wa laa tahmil''alaynaa''isran kamaa hamaltahu''alal-latheena min qablinaa, Rabbanaa wa laa tuhammilnaa maa laa taaqata lanaa bihi, wa''fu''annaa, waghfir lanaa warhamnaa,''Anta Mawlaanaa fansurnaa''alal-qawmil-kaafireen.');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.028.part.010', 'dua.hisn.028', 10);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.028.part.010.segment.001', 'dua.hisn.028.part.010', 1, 'arabic', 'ar', 'Arab', 'بِاسْمِكَ رَبِّي وَضَعْتُ جَنْبِي، وَبِكَ أَرْفَعُهُ، فَإِنْ أَمْسَكْتَ نَفْسِي فَارْحَمْهَا، وَإِنْ أَرْسَلْتَهَا فَاحْفَظْهَا، بِمَا تَحْفَظُ بِهِ عِبَادَكَ الصَّالِحِينَ');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.028.part.010.segment.002', 'dua.hisn.028.part.010', 2, 'transliteration', 'ar-Latn', 'Latn', 'With Your Name my Lord, I lay myself down ; and with Your Name I rise. And if my soul You take , have mercy on it , and if You send it back then protect it as You protect Your righteous slaves.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.028.part.010.segment.003', 'dua.hisn.028.part.010', 3, 'translation', 'en', 'Latn', 'Bismika Rabbee wadha''tu janbee , wa bika''arfa''uhu, fa''in''amsakta nafsee farhamhaa, wa''in''arsaltahaa fahfadhhaa, bimaa tahfadhu bihi''ibaadakas-saaliheen.');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.028.part.011', 'dua.hisn.028', 11);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.028.part.011.segment.001', 'dua.hisn.028.part.011', 1, 'arabic', 'ar', 'Arab', 'اللَّهُمَّ إِنَّكَ خَلَقْتَ نَفْسِي وَأَنْتَ تَوَفَّاهَا، لَكَ مَمَاتُهَا وَمَحْيَاهَا، إِنْ أَحْيَيْتَهَا فَاحْفَظْهَا، وَإِنْ أَمَتَّهَا فََاغْفِرْ لَهَا، اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَافِيَةَ');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.028.part.011.segment.002', 'dua.hisn.028.part.011', 2, 'transliteration', 'ar-Latn', 'Latn', 'Allaahwmma''innaka khalaqta nafsee wa''Anta tawaffaahaa, laka mamaatuhaa wa mahyaahaa,''in''ahyaytahaa fahfadhhaa, wa''in''amattahaa faghfir lahaa. Allaahumma''innee''as''alukal-''aafiyata.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.028.part.011.segment.003', 'dua.hisn.028.part.011', 3, 'translation', 'en', 'Latn', 'O Allah, You have created my soul and You take it back. Unto You is its death and its life. If You give it life then protect it , and if You cause it to die then forgive it. O Allah, I ask You for strength.');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.028.part.012', 'dua.hisn.028', 12);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.028.part.012.segment.001', 'dua.hisn.028.part.012', 1, 'arabic', 'ar', 'Arab', 'اللَّهمَّ قني عَذَابَكَ يَوْمَ تَبْعَث عبَادَكَ (ثلاث مرات)');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.028.part.012.segment.002', 'dua.hisn.028.part.012', 2, 'transliteration', 'ar-Latn', 'Latn', 'Allaahumma qinee''athaabaka yawma tab''athu''ibaadaka.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.028.part.012.segment.003', 'dua.hisn.028.part.012', 3, 'translation', 'en', 'Latn', 'O Allah, save me from Your punishment on the Day that You resurrect Your slaves. (Recite three times)');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.028.part.013', 'dua.hisn.028', 13);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.028.part.013.segment.001', 'dua.hisn.028.part.013', 1, 'arabic', 'ar', 'Arab', 'باسْمكَ اللَّهمَّ أَموت وَأَحْيَا');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.028.part.013.segment.002', 'dua.hisn.028.part.013', 2, 'transliteration', 'ar-Latn', 'Latn', 'In Your Name , O Allah , I die and I live.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.028.part.013.segment.003', 'dua.hisn.028.part.013', 3, 'translation', 'en', 'Latn', 'Bismika Allaahumma''amootu wa''ahyaa.');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.028.part.014', 'dua.hisn.028', 14);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.028.part.014.segment.001', 'dua.hisn.028.part.014', 1, 'arabic', 'ar', 'Arab', 'سبْحَانَ الله،(ثلاث وثلاثين مرة) والْحَمْد لله(ثلاث وثلاثين مرة)، وَالله أَكْبَر(اربع وثلاثين مرة)');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.028.part.014.segment.002', 'dua.hisn.028.part.014', 2, 'transliteration', 'ar-Latn', 'Latn', 'Glory is to Allah (thirty-three times) , praise is to Allah (thirty-three times) , Allah is the Most Great (thirty-four times)');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.028.part.014.segment.003', 'dua.hisn.028.part.014', 3, 'translation', 'en', 'Latn', 'Subhaanallaahi, - Walhamdu lillaahi, -Wallaahu''Akbar.');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.028.part.015', 'dua.hisn.028', 15);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.028.part.015.segment.001', 'dua.hisn.028.part.015', 1, 'arabic', 'ar', 'Arab', 'اللَّهُمَّ رَبَّ السَّمَاوَاتِ السَّبْعِ وَرَبَّ الْعَرْشِ الْعَظِيمِ، رَبَّنَا وَرَبَّ كُلِّ شَيْءٍ، فَالِقَ الْحَبِّ وَالنَّوَى، وَمُنْزِلَ التَّوْرَاةِ وَالْإِنجِيلِ، وَالْفُرْقَانِ، أَعُوذُ بِكَ مِنْ شَرِّ كُلِّ شَيْءٍ أّنْتَ آخِذٌ بِنَاصِيَتهِ. اللَّهُمَّ أَنْتَ الأَوَّلُ فَلَيْسَ قَبْلَكَ شَيْءٌ، وَأَنْتَ الْآخِرُ فَلَيْسَ بَعْدَكَ شَيْءٌ، وَأَنْتَ الظَّاهِرُ فَلَيْسَ فَوْقَكَ شَيْءٌ، وَأَنْتَ الْبَاطِنُ فَلَيْسَ دُونَكَ شَيْءٌ، فاقْضِ عَنَّا الدَّيْنَ وَأَغْنِنَا مِنَ الْفَقْرِ');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.028.part.015.segment.002', 'dua.hisn.028.part.015', 2, 'transliteration', 'ar-Latn', 'Latn', 'Allaahumma Rabbas-samaawaatis-sab''i wa Rabbal-''Arshil-''Adheem, Rabbanaa wa Rabba kulli shay''in, faaliqal-habbi wannawaa , wa munzilat-Tawraati wal-''Injeeli, wal-Furqaani,''a''oothu bika min sharri kulli shay''in''Anta''aakhithun binaasiyatihi. Allaahumma''Antal-''Awwalu falaysa qablaka shay''un, wa''Antal-''Aakhiru falaysa ba''daka shay''un, wa''Antadh-Dhaahiru falaysa fawqaka shay''un, wa''Antal-Baatinu falaysa doonaka shay''un, iqdhi''annad-dayna wa''aghninaa minal-faqri.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.028.part.015.segment.003', 'dua.hisn.028.part.015', 3, 'translation', 'en', 'Latn', 'O Allah! Lord of the seven heavens and Lord of the Magnificent Throne. Our Lord and the Lord of everything. Splitter of the grain and the date-stone , Revealer of the Torah and the Injeel and the Furqdn (the Qur''an), I seek refuge in You from the evil of everything that You shall seize by the forelock. O Allah You are the First and nothing has come before you, and You are the Last, and nothing may come after You. You are the Most High, nothing is above You and You are the Most Near and nothing is nearer than You. Remove our debts from us and enrich us against poverty.');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.028.part.016', 'dua.hisn.028', 16);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.028.part.016.segment.001', 'dua.hisn.028.part.016', 1, 'arabic', 'ar', 'Arab', 'الْحَمْد لله الَّذي أَطْعَمَنَا وَسَقَانَا، وَكَفَانَا، وَآوَانَا،فكَمْ ممَّنْ لَا كَافِيَ لَه وَلَا مؤْويَ');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.028.part.016.segment.002', 'dua.hisn.028.part.016', 2, 'transliteration', 'ar-Latn', 'Latn', 'Praise is to Allah Who has provided us with food and with drink , sufficed us and gave us an abode for how many are there with no provision and no home.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.028.part.016.segment.003', 'dua.hisn.028.part.016', 3, 'translation', 'en', 'Latn', 'Alhamdu lillaahil-lathee''at''amanaa wa saqaanaa, wa kafaanaa, wa''aawaanaa, fakam mimman laa kaafiya lahu wa laa mu''wiya.');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.028.part.017', 'dua.hisn.028', 17);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.028.part.017.segment.001', 'dua.hisn.028.part.017', 1, 'arabic', 'ar', 'Arab', 'اللَّهمَّ عَالمَ الْغَيْب وَالشَّهَادَة فَاطِرَ السَّمَاوات والْأَرْضَ، رَبَّ كلّ شَيْء وَمَلكه، أَشْهَد أَنْ لَا إلَهَ إلَّا أَنْتَ، أَعوذ بكَ منْ شَرّ نَفْسِي، وَمنْ شَرّ الشَّيْطَان وَشرْكه، وَأَنْ أَقْتَرِفَ عَلَى نَفْسِي سوءاً، أَوْ أَجرَّه إلَى مسْلم');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.028.part.017.segment.002', 'dua.hisn.028.part.017', 2, 'transliteration', 'ar-Latn', 'Latn', 'Allaahumma''Aalimal-ghaybi wash-shahaadati faatiras-samaawaati wal''ardhi, Rabba kulli shay''in wa maleekahu,''ash-hadu''an laa''ilaaha''illaa''Anta,''a''oothu bika min sharri nafsee, wa min sharrish-shaytaani wa shirkihi, wa''an''aqtarifa''alaa nafsee soo''an,''aw''ajurrahu''ilaa Muslimin.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.028.part.017.segment.003', 'dua.hisn.028.part.017', 3, 'translation', 'en', 'Latn', 'O Allah, Knower of the unseen and the evident , Maker of the heavens and the earth , Lord of everything and its Master, I bear witness that there is none worthy of worship but You. I seek refuge in You from the evil of my soul and from the evil of Satan and his helpers. (I seek refuge in You) from bringing evil upon my soul and from harming any Muslim.');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.028.part.018', 'dua.hisn.028', 18);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.028.part.018.segment.001', 'dua.hisn.028.part.018', 1, 'comment', 'en', 'Latn', 'Recite Surah 32 (As-Sajdah) and Surah 67 (Al-Mulk)');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.028.part.018.segment.002', 'dua.hisn.028.part.018', 2, 'comment', 'en', 'Latn', 'Recite Surah 32 (As-Sajdah) and Surah 67 (Al-Mulk)');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.028.part.018.segment.003', 'dua.hisn.028.part.018', 3, 'arabic', 'ar', 'Arab', 'اللَّهمَّ أَسْلَمْت نَفْسِي إلَيْكَ، وَفوَّضْت أَمْري إلَيْكَ، وَوَجَّهْت وَجْهي إلَيْكَ، وَأَلْجَأْت ظَهْري إلَيْكَ، رَغْبَةً وَرَهْبَةً إلَيْكَ، لَا مَلْجَأَ وَلّا مَنْجَا منْكَ إلَّا إلَيْكَ، آمَنْت بكتَابكَ الَّذيْ أَنْزَلْتَ وَبنَبيّكَ الَّذي أَرْسَلْتَ');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.028.part.018.segment.004', 'dua.hisn.028.part.018', 4, 'transliteration', 'ar-Latn', 'Latn', 'Allaahumma''aslamtu nafsee''ilayka, wa fawwadhtu''amree''ilayka, wa wajjahtu wajhee''ilayka, wa''alja''tu dhahree''ilayka, raghbatan wa rahbatan''ilayka, laa raalja''wa laa manja minka''illaa''ilayka,''aamantu bikitaabikal-lathee''anzalta wa bi-nabiyyikal-lathee''arsalta.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.028.part.018.segment.005', 'dua.hisn.028.part.018', 5, 'translation', 'en', 'Latn', 'O Allah, I submit myself to You, entrust my affairs to You, turn my face to You, and lay myself down depending upon You , hoping in You and fearing You. There is no refuge , and no escape, except to You. I believe in Your Book (the Qur''an) that You revealed, and the Prophet (saws) whom You sent.');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.029', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-029', 29, 'Supplication when turning over during the night', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.029.part.001', 'dua.hisn.029', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.029.part.001.segment.001', 'dua.hisn.029.part.001', 1, 'comment', 'en', 'Latn', '‘AAa-isha رضي الله عنها narrated that the Messenger of Allahused to say at night if he turned during sleep:');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.029.part.001.segment.002', 'dua.hisn.029.part.001', 2, 'arabic', 'ar', 'Arab', 'لا إِلـهَ إِلاّ اللهُ الـواحِدُ القَهّـار، رَبُّ السَّـمواتِ وَالأرْضِ وَما بَيْـنَهـما، العَزيـزُ الغَـفّار.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.029.part.001.segment.003', 'dua.hisn.029.part.001', 3, 'transliteration', 'ar-Latn', 'Latn', 'La ilaha illal-lahul-wahidul-qahhar, rabbus-samawati wama baynahuma, alAAazeezul-ghaffar.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.029.part.001.segment.004', 'dua.hisn.029.part.001', 4, 'translation', 'en', 'Latn', '‘None has the right to be worshipped except Allah, The One, AL-Qahhar.Lord of the heavens and the Earth and all between them, The Exalted in Might, The Oft-Forgiving.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.029.part.002', 'dua.hisn.029', 2);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.029.part.002.segment.001', 'dua.hisn.029.part.002', 1, 'comment', 'en', 'Latn', 'AL-Qahhar:The One Who has subdued all of creation and Whom all of creation are subservient to.All movements occur by His will.');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.030', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-030', 30, 'Upon experiencing unrest, fear, apprehensiveness and the like during sleep', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.030.part.001', 'dua.hisn.030', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.030.part.001.segment.001', 'dua.hisn.030.part.001', 1, 'arabic', 'ar', 'Arab', 'أَعـوذُ بِكَلِمـاتِ اللّهِ التّـامّـاتِ مِن غَضَـبِهِ وَعِـقابِهِ، وَشَـرِّ عِبـادِهِ وَمِنْ هَمَـزاتِ الشَّـياطينِ وَأَنْ يَحْضـرون.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.030.part.001.segment.002', 'dua.hisn.030.part.001', 2, 'transliteration', 'ar-Latn', 'Latn', 'aAAoothu bikalimatil-lahit-tammat min ghadabih,waAAiqabih, washarri AAibadih, wamin hamazatish-shayateen, wa-an yahduroon.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.030.part.001.segment.003', 'dua.hisn.030.part.001', 3, 'translation', 'en', 'Latn', '‘I take refuge in the perfect words of Allah from His anger and punishment, and from the evil of His servants, and from the madness and appearance of devils.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.031', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-031', 31, 'Upon seeing a good dream or a bad dream', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.031.part.001', 'dua.hisn.031', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.031.part.001.segment.001', 'dua.hisn.031.part.001', 1, 'comment', 'en', 'Latn', 'Summary of what to do upon having a bad dream:');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.031.part.001.segment.002', 'dua.hisn.031.part.001', 2, 'comment', 'en', 'Latn', 'Spit on your left three times');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.031.part.001.segment.003', 'dua.hisn.031.part.001', 3, 'comment', 'en', 'Latn', 'Spit: A form of spitting comprising mainly of air with little spittle');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.031.part.001.segment.004', 'dua.hisn.031.part.001', 4, 'comment', 'en', 'Latn', 'Seek refuge in Allah from shaytan and the evil of what you saw');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.031.part.001.segment.005', 'dua.hisn.031.part.001', 5, 'comment', 'en', 'Latn', 'Do not relate it to anyone');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.031.part.001.segment.006', 'dua.hisn.031.part.001', 6, 'comment', 'en', 'Latn', 'Turn and sleep on the opposite side to which you were sleeping on previously.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.031.part.001.segment.007', 'dua.hisn.031.part.001', 7, 'comment', 'en', 'Latn', 'Get up and pray if you so desire.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.031.part.001.segment.008', 'dua.hisn.031.part.001', 8, 'translation', 'en', 'Latn', '‘The righteous dream is from Allah and the bad dream is from the devil, so if anyone sees something which pleases him then he should only relate it to one whom he loves’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.032', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-032', 32, 'Qunoot Al-Witr', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.032.part.001', 'dua.hisn.032', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.032.part.001.segment.001', 'dua.hisn.032.part.001', 1, 'arabic', 'ar', 'Arab', 'اللّهُـمَّ اهْـدِنـي فـيمَنْ هَـدَيْـت، وَعـافِنـي فـيمَنْ عافَـيْت، وَتَوَلَّـني فـيمَنْ تَوَلَّـيْت، وَبارِكْ لـي فـيما أَعْطَـيْت، وَقِـني شَرَّ ما قَضَـيْت، فَإِنَّـكَ تَقْـضي وَلا يُقْـضى عَلَـيْك، إِنَّـهُ لا يَـذِلُّ مَنْ والَـيْت،  وَلا يَعِـزُّ مَن عـادَيْت ، تَبـارَكْـتَ رَبَّـنا وَتَعـالَـيْت.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.032.part.001.segment.002', 'dua.hisn.032.part.001', 2, 'transliteration', 'ar-Latn', 'Latn', 'Allahummah-dinee feeman hadayt, waAAafinee feeman AAafayt, watawallanee feeman tawallayt, wabarik lee feema aAAtayt, waqinee sharra ma qadayt, fa-innaka taqdee wala yuqda AAalayk, innahu la yathillu man walayt, wala yaAAizzu man AAadayt, tabarakta rabbana wataAAalayt.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.032.part.001.segment.003', 'dua.hisn.032.part.001', 3, 'translation', 'en', 'Latn', '‘O Allah, guide me along with those whom You have guided, pardon me along with those whom You have pardoned, be an ally to me along with those whom You are an ally to and bless for me that which You have bestowed.Protect me from the evil You have decreed for verily You decree and none can decree over You.For surety, he whom you show allegiance to is never abased and he whom You take as an enemy is never honoured and mighty. O our Lord, Blessed and Exalted are You.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.032.part.002', 'dua.hisn.032', 2);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.032.part.002.segment.001', 'dua.hisn.032.part.002', 1, 'comment', 'en', 'Latn', 'Evil you have decreed: Allah does not create pure evil which does not have any good or contain any benefit, wisdom or mercy at all, nor does He punish anyone without having commited a sin. Something can be good in terms of its creation when viewed in a particular perspective and at the same time be evil when viewed in another way.Allah created the devil and by him, He tests His servants, so there are those who hate the devil, fight him and his way and they stand at enmity towards him and his followers and there are others who are at allegiance with the devil and follow his steps. So evil exists in His creatures by His will and wisdom, not in His actions or act of creating.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.032.part.002.segment.002', 'dua.hisn.032.part.002', 2, 'arabic', 'ar', 'Arab', 'اللّهُـمَّ إِنِّـي أَعـوذُ بِرِضـاكَ مِنْ سَخَطِـك، وَبِمُعـافاتِـكَ مِنْ عُقوبَـتِك، وَأَعـوذُ بِكَ مِنْـك، لا أُحْصـي ثَنـاءً عَلَـيْك، أَنْـتَ كَمـا أَثْنَـيْتَ عَلـى نَفْسـِك.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.032.part.002.segment.003', 'dua.hisn.032.part.002', 3, 'transliteration', 'ar-Latn', 'Latn', 'Allahumma innee aAAoothu biridaka min sakhatik, wabimuAAafatika min AAuqoobatik, wa-aAAoothu bika mink, la ohsee thana-an AAalayk, anta kama athnayta AAala nafsik.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.032.part.002.segment.004', 'dua.hisn.032.part.002', 4, 'translation', 'en', 'Latn', '‘O Allah, I take refuge within Your pleasure from Your displeasure and within Your pardon from Your punishment, and I take refuge in You from You. I cannot enumerate Your praise. You are as You have praised Yourself.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.032.part.003', 'dua.hisn.032', 3);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.032.part.003.segment.001', 'dua.hisn.032.part.003', 1, 'arabic', 'ar', 'Arab', 'اللّهُـمَّ إِيّـاكَ نعْـبُدْ، وَلَـكَ نُصَلّـي وَنَسْـجُد، وَإِلَـيْكَ نَسْـعى وَنَحْـفِد، نَـرْجو رَحْمَـتَك، وَنَخْشـى عَـذابَك، إِنَّ عَـذابَكَ بالكـافرين ملْحَـق. اللّهُـمَّ إِنّا نَسْتَعـينُكَ وَنَسْتَـغْفِرُك، وَنُثْـنـي عَلَـيْك الخَـيْرَ، وَلا نَكْـفُرُك، وَنُـؤْمِنُ بِك، وَنَخْـضَعُ لَكَ وَنَخْـلَعُ مَنْ يَكْـفرُك.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.032.part.003.segment.002', 'dua.hisn.032.part.003', 2, 'transliteration', 'ar-Latn', 'Latn', 'Allahumma iyyaka naAAbud, walaka nusallee wanasjud, wa-ilayka nasAAa wanahfid, narjoo rahmatak, wanakhsha AAathabak, inna AAathabaka bilkafireena mulhaq. Allahumma inna nastaAAeenuk, wanastaghfiruk, wanuthnee AAalaykal- khayr, wala nakfuruk, wanu/minu bik, wanakhdaAAu lak wanakhlaAAu man yakfuruk.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.032.part.003.segment.003', 'dua.hisn.032.part.003', 3, 'translation', 'en', 'Latn', '‘O Allah, it is You we worship, and unto You we pray and prostrate, and towards You we hasten and You we serve. We hope for Your mercy and fear Your punishment, verily Your punishment will fall upon the disbelievers.O Allah, we seek Your aid and ask Your pardon, we praise You with all good and do not disbelieve in You.We believe in You and submit unto You, and we disown and reject those who disbelieve in You.');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.033', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-033', 33, 'Remembrance immediately after salam of the witr prayer', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.033.part.001', 'dua.hisn.033', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.033.part.001.segment.001', 'dua.hisn.033.part.001', 1, 'arabic', 'ar', 'Arab', 'سُـبْحانَ المَلِكِ القُدّوس,ربِّ الملائكةِ والرّوح');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.033.part.001.segment.002', 'dua.hisn.033.part.001', 2, 'transliteration', 'ar-Latn', 'Latn', 'Subhana-l-maliki-l-quddusi. Rabbi-l-malaikati wa r-ruhi.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.033.part.001.segment.003', 'dua.hisn.033.part.001', 3, 'translation', 'en', 'Latn', 'How perfect The King, The Holy One is three times. Lord of the angels and the Rooh.');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.034', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-034', 34, 'Supplication for anxiety and sorrow', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.034.part.001', 'dua.hisn.034', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.034.part.001.segment.001', 'dua.hisn.034.part.001', 1, 'arabic', 'ar', 'Arab', 'اللّهُـمَّ إِنِّي عَبْـدُكَ ابْنُ عَبْـدِكَ ابْنُ أَمَتِـكَ نَاصِيَتِي بِيَـدِكَ، مَاضٍ فِيَّ حُكْمُكَ، عَدْلٌ فِيَّ قَضَاؤكَ أَسْأَلُـكَ بِكُلِّ اسْمٍ هُوَ لَكَ سَمَّـيْتَ بِهِ نَفْسَكَ أِوْ أَنْزَلْتَـهُ فِي كِتَابِكَ، أَوْ عَلَّمْـتَهُ أَحَداً مِنْ خَلْقِـكَ أَوِ اسْتَـأْثَرْتَ بِهِ فِي عِلْمِ الغَيْـبِ عِنْـدَكَ أَنْ تَجْـعَلَ القُرْآنَ رَبِيـعَ قَلْبِـي، وَنورَ صَـدْرِي وجَلَاءَ حُـزْنِي وذَهَابَ هَمِّـي.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.034.part.001.segment.002', 'dua.hisn.034.part.001', 2, 'transliteration', 'ar-Latn', 'Latn', 'Allahumma innee AAabduk, ibnu AAabdik, ibnu amatik, nasiyatee biyadik, madin fiyya hukmuk, AAadlun fiyya qada-ok, as-aluka bikulli ismin huwa lak, sammayta bihi nafsak, aw anzaltahu fee kitabik, aw AAallamtahu ahadan min khalqik awis-ta/tharta bihi fee AAilmil-ghaybi AAindak, an tajAAalal-Qurana rabeeAAa qalbee, wanoora sadree, wajalaa huznee wathahaba hammee.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.034.part.001.segment.003', 'dua.hisn.034.part.001', 3, 'translation', 'en', 'Latn', '‘O Allah, I am Your servant, son of Your servant, son of Your maidservant, my forelock is in Your hand (i.e. You have total mastery over), Your command over me is forever executed and Your decree over me is just. I ask You by every name belonging to You which You named Yourself with, or revealed in Your Book, or You taught to any of Your creation, or You have preserved in the knowledge of the unseen with You, that You make the Quran the life of my heart and the light of my breast, and a departure for my sorrow and a release for my anxiety.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.034.part.002', 'dua.hisn.034', 2);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.034.part.002.segment.001', 'dua.hisn.034.part.002', 1, 'arabic', 'ar', 'Arab', 'اللّهُـمَّ إِنِّي أَعْوذُ بِكَ مِنَ الهَـمِّ وَ الْحُـزْنِ، والعًجْـزِ والكَسَلِ والبُخْـلِ والجُـبْنِ، وضَلْـعِ الـدَّيْنِ وغَلَبَـةِ الرِّجال.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.034.part.002.segment.002', 'dua.hisn.034.part.002', 2, 'transliteration', 'ar-Latn', 'Latn', 'Allahumma innee aAAoothu bika minal-hammi walhuzn, walAAajzi walkasali walbukhli waljubn, wadalAAid-dayni waghalabatir-rijal.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.034.part.002.segment.003', 'dua.hisn.034.part.002', 3, 'translation', 'en', 'Latn', '‘O Allah, I take refuge in You from anxiety and sorrow, weakness and laziness, miserliness and cowardice, the burden of debts and from being over powered by men.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.035', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-035', 35, 'Supplication for one in distress', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.035.part.001', 'dua.hisn.035', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.035.part.001.segment.001', 'dua.hisn.035.part.001', 1, 'arabic', 'ar', 'Arab', 'لَا إلَهَ إِلَّا اللَّهُ الْعَظـيمُ الْحَلِـيمْ، لَا إِلَهَ إِلَّا اللَّهُ رَبُّ العَـرْشِ العَظِيـمِ، لَا إِلَـهَ إِلَّا اللَّهْ رَبُّ السَّمَـوّاتِ ورّبُّ الأَرْضِ ورَبُّ العَرْشِ الكَـريم.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.035.part.001.segment.002', 'dua.hisn.035.part.001', 2, 'transliteration', 'ar-Latn', 'Latn', 'La ilaha illal-lahul-AAatheemul-haleem, la ilaha illal-lahu rabbul-AAarshil-AAatheem, la ilaha illal-lahurabbus-samawati warabbul-ardi warabbul-AAarshil-kareem.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.035.part.001.segment.003', 'dua.hisn.035.part.001', 3, 'translation', 'en', 'Latn', '‘None has the right to be worshipped except Allah Forbearing.None has the right to be worshipped except Allah, Lord of the magnificent throne.None has the right to be worshipped except Allah, Lord of the heavens, Lord of the Earth and Lord of the noble throne.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.035.part.002', 'dua.hisn.035', 2);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.035.part.002.segment.001', 'dua.hisn.035.part.002', 1, 'arabic', 'ar', 'Arab', 'اللّهُـمَّ رَحْمَتَـكَ أَرْجـو فَلا تَكِلـني إِلى نَفْـسي طَـرْفَةَ عَـيْن، وَأَصْلِـحْ لي شَأْنـي كُلَّـه لَا إِلَهَ إِلَّا أنْـت.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.035.part.002.segment.002', 'dua.hisn.035.part.002', 2, 'transliteration', 'ar-Latn', 'Latn', 'Allahumma rahmataka arjoo fala takilnee ila nafsee tarfata AAayn, wa-aslih lee sha/nee kullah, la ilaha illa ant.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.035.part.002.segment.003', 'dua.hisn.035.part.002', 3, 'translation', 'en', 'Latn', '‘O Allah, it is Your mercy that I hope for, so do not leave me in charge of my affairs even for a blink of an eye and rectify for me all of my affairs.None has the right to be worshipped except You.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.035.part.003', 'dua.hisn.035', 3);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.035.part.003.segment.001', 'dua.hisn.035.part.003', 1, 'arabic', 'ar', 'Arab', 'لَا إِلَهَ إِلَّا أنْـت سُـبْحانَكَ إِنِّي كُنْـتُ مِنَ الظّـالِميـن.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.035.part.003.segment.002', 'dua.hisn.035.part.003', 2, 'transliteration', 'ar-Latn', 'Latn', 'La ilaha illa anta subhanaka innee kuntu minath-thalimeen.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.035.part.003.segment.003', 'dua.hisn.035.part.003', 3, 'translation', 'en', 'Latn', '‘None has the right to be worshipped except You.How perfect You are, verily I was among the wrong-doers.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.035.part.004', 'dua.hisn.035', 4);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.035.part.004.segment.001', 'dua.hisn.035.part.004', 1, 'arabic', 'ar', 'Arab', 'اللهُ اللهُ رَبِّي لا أُشْـرِكُ بِهِ شَيْـئاً.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.035.part.004.segment.002', 'dua.hisn.035.part.004', 2, 'transliteration', 'ar-Latn', 'Latn', 'Allahu Allahu rabbi la oshriku bihi shaya.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.035.part.004.segment.003', 'dua.hisn.035.part.004', 3, 'translation', 'en', 'Latn', '‘Allah, Allah is my Lord, I do not associate anything with Him.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.036', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-036', 36, 'Upon encountering an enemy or those of authority', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.036.part.001', 'dua.hisn.036', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.036.part.001.segment.001', 'dua.hisn.036.part.001', 1, 'arabic', 'ar', 'Arab', 'اللّهُـمَّ إِنا نَجْـعَلُكَ في نُحـورِهِـم، وَنَعـوذُ بِكَ مِنْ شُرورِهـمْ.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.036.part.001.segment.002', 'dua.hisn.036.part.001', 2, 'transliteration', 'ar-Latn', 'Latn', 'Allahumma inna najAAaluka fee nuhoorihim wanaAAoothu bika min shuroorihim.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.036.part.001.segment.003', 'dua.hisn.036.part.001', 3, 'translation', 'en', 'Latn', '‘O Allah, we place You before them and we take refuge in You from their evil.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.036.part.002', 'dua.hisn.036', 2);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.036.part.002.segment.001', 'dua.hisn.036.part.002', 1, 'arabic', 'ar', 'Arab', 'اللّهُـمَّ أَنْتَ عَضُـدي، وَأَنْتَ نَصـيري، بِكَ أَجـولُ وَبِكَ أَصـولُ وَبِكَ أُقـاتِل.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.036.part.002.segment.002', 'dua.hisn.036.part.002', 2, 'transliteration', 'ar-Latn', 'Latn', 'Allahumma anta AAadudee, wa-anta naseeree, bika ajoolu wabika asoolu wabika oqatil.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.036.part.002.segment.003', 'dua.hisn.036.part.002', 3, 'translation', 'en', 'Latn', '‘O Allah, You are my supporter and You are my helper, by You I move and by You I attack and by You I battle.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.036.part.003', 'dua.hisn.036', 3);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.036.part.003.segment.001', 'dua.hisn.036.part.003', 1, 'arabic', 'ar', 'Arab', 'حَسْبُـنا اللهُ وَنِعْـمَ الوَكـيل.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.036.part.003.segment.002', 'dua.hisn.036.part.003', 2, 'transliteration', 'ar-Latn', 'Latn', 'Hasbunal-lahu waniAAmal-wakeel.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.036.part.003.segment.003', 'dua.hisn.036.part.003', 3, 'translation', 'en', 'Latn', '‘Allah is sufficient for us, and how fine a trustee (He is).’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.037', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-037', 37, 'For one afraid of governor''s injustice', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.037.part.001', 'dua.hisn.037', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.037.part.001.segment.001', 'dua.hisn.037.part.001', 1, 'arabic', 'ar', 'Arab', 'اللهُمَّ رَبَّ السَّماوَاتِ السَّبعِ, وَ رَبَّ العَرشِ العَظِيمِ, كُن لِي جَاراً مِن (اِسمُهُ(وَ أَحزَابِهِ مِن خَلائِقِكَ, أَن يَفرُطَ عَلَيَّ أَحَدٌ مِنهُم وَ يَطغَى عَزَّ جَارُكَ وَ جَلَّ ثَنَائُكَ, وَ لا إِلهَ إِلا أَنت');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.037.part.001.segment.002', 'dua.hisn.037.part.001', 2, 'transliteration', 'ar-Latn', 'Latn', 'Allahumma rabba s-samawati s-sabci, wa rabba-l-carshi-l-cazimi. Kun li jaran min (citer son nom) wa ahzabihi min khala''iqika, an yafruta calayya ahadun minhum wa yatgha.cAzza jaruka, wa jalla thana''uka, wa la ilaha illa ant.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.037.part.001.segment.003', 'dua.hisn.037.part.001', 3, 'translation', 'en', 'Latn', 'O Allah, Lord of the seven heavens and the earth and the great throne, protect me from so-and-so tell the name of the person and from his allies among your creatures, and from being subjected by their abus or tyranny. Honoured is your protected, exalted is your praise, none has the right to be worshipped except You.');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.037.part.002', 'dua.hisn.037', 2);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.037.part.002.segment.001', 'dua.hisn.037.part.002', 1, 'arabic', 'ar', 'Arab', 'اللهُ أَكْبَر, اللهُ أَعَزُّ مِنْ خَلْقِهِ جَمِيعًا, اللهُ أَعَزُّ مِمَّا أَخَافُ وَ أَحْذَر, أَعُوذُ باللِه الَّذِي لاَ إِلَهَ إِلاَّ هُو, , الْمُمْسِكُ السَّمَاوَاتِ السَّبْعِ أَنْ يَقَعْنَ عَلَى الأَرْضَ إِلاَّ بِإِذْنِه, مِنْ شَرِّ عَبْدِكَ فُلاَنٍ, وَ جُنُودَهُ وَ أَتْبَاعَهُ وَ أَشْيَاعَه, مِنَ الْجِنِّ وَ الإِنْس, اللَّهُمَّ كُن لِي جَارًا مِنْ شَرِّهِم, جَلَّ ثَنَاؤُك وَ عَزَّ جَارُك, وَ جَلَّ ثَنَاؤُك, وَ لاَ إِلَهَ إِلاَّ أَنْت');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.037.part.002.segment.002', 'dua.hisn.037.part.002', 2, 'transliteration', 'ar-Latn', 'Latn', 'Allahu akbaru. Allahu acazzu min khalqihi jamican. Allahu acazzu mimma akhafu wa ahdharu. Acudhu bi-l-lahi l-ladhi la ilaha illa huwa-l-mumsiki s-samawati s-sabci an yaqacna cala-l-ardi illa bi-idhnihi, min sharri cabdika (citer son nom) wa junudihi wa atbacihi wa ashyacihi mina-l-jinni wa-l-insi. Allahumma kun li jaran min sharrihim. Jalla thana''uka wa cazza aruka, wa tabaraka smuka, wa la ilaha ghayruka.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.037.part.002.segment.003', 'dua.hisn.037.part.002', 3, 'translation', 'en', 'Latn', 'Allah is the greatest, Allah is mightier than all things. Allah is mightier than the one I''m afraid of and I mistrust. I take refuge in Allah, none has the right to be worshipped except Allah, who hold back the seven heavens from falling on earth except when he''ll allowed this, from the misdeeds of You slave so-and-so tell the name of the person, from his soldiers, from his partisans among the djinns and the human beings. Ô Lord ! Be my protector from their misdeeds. Exalted is Your praise, honoured is Your protected, blessed is Your name and none has the right to be worshipped except You.');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.038', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-038', 38, 'For one afraid of governor''s injustice', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.038.part.001', 'dua.hisn.038', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.038.part.001.segment.001', 'dua.hisn.038.part.001', 1, 'arabic', 'ar', 'Arab', 'اللهُمَّ رَبَّ السَّماوَاتِ السَّبعِ, وَ رَبَّ العَرشِ العَظِيمِ, كُن لِي جَاراً مِن (اِسمُهُ(وَ أَحزَابِهِ مِن خَلائِقِكَ, أَن يَفرُطَ عَلَيَّ أَحَدٌ مِنهُم وَ يَطغَى عَزَّ جَارُكَ وَ جَلَّ ثَنَائُكَ, وَ لا إِلهَ إِلا أَنت');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.038.part.001.segment.002', 'dua.hisn.038.part.001', 2, 'transliteration', 'ar-Latn', 'Latn', 'Allahumma rabba s-samawati s-sabci, wa rabba-l-carshi-l-cazimi. Kun li jaran min (citer son nom) wa ahzabihi min khala''iqika, an yafruta calayya ahadun minhum wa yatgha.cAzza jaruka, wa jalla thana''uka, wa la ilaha illa ant.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.038.part.001.segment.003', 'dua.hisn.038.part.001', 3, 'translation', 'en', 'Latn', 'O Allah, Lord of the seven heavens and the earth and the great throne, protect me from so-and-so tell the name of the person and from his allies among your creatures, and from being subjected by their abus or tyranny. Honoured is your protected, exalted is your praise, none has the right to be worshipped except You.');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.038.part.002', 'dua.hisn.038', 2);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.038.part.002.segment.001', 'dua.hisn.038.part.002', 1, 'arabic', 'ar', 'Arab', 'اللهُ أَكْبَر, اللهُ أَعَزُّ مِنْ خَلْقِهِ جَمِيعًا, اللهُ أَعَزُّ مِمَّا أَخَافُ وَ أَحْذَر, أَعُوذُ باللِه الَّذِي لاَ إِلَهَ إِلاَّ هُو, , الْمُمْسِكُ السَّمَاوَاتِ السَّبْعِ أَنْ يَقَعْنَ عَلَى الأَرْضَ إِلاَّ بِإِذْنِه, مِنْ شَرِّ عَبْدِكَ فُلاَنٍ, وَ جُنُودَهُ وَ أَتْبَاعَهُ وَ أَشْيَاعَه, مِنَ الْجِنِّ وَ الإِنْس, اللَّهُمَّ كُن لِي جَارًا مِنْ شَرِّهِم, جَلَّ ثَنَاؤُك وَ عَزَّ جَارُك, وَ جَلَّ ثَنَاؤُك, وَ لاَ إِلَهَ إِلاَّ أَنْت');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.038.part.002.segment.002', 'dua.hisn.038.part.002', 2, 'transliteration', 'ar-Latn', 'Latn', 'Allahu akbaru. Allahu acazzu min khalqihi jamican. Allahu acazzu mimma akhafu wa ahdharu. Acudhu bi-l-lahi l-ladhi la ilaha illa huwa-l-mumsiki s-samawati s-sabci an yaqacna cala-l-ardi illa bi-idhnihi, min sharri cabdika (citer son nom) wa junudihi wa atbacihi wa ashyacihi mina-l-jinni wa-l-insi. Allahumma kun li jaran min sharrihim. Jalla thana''uka wa cazza aruka, wa tabaraka smuka, wa la ilaha ghayruka.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.038.part.002.segment.003', 'dua.hisn.038.part.002', 3, 'translation', 'en', 'Latn', 'Allah is the greatest, Allah is mightier than all things. Allah is mightier than the one I''m afraid of and I mistrust. I take refuge in Allah, none has the right to be worshipped except Allah, who hold back the seven heavens from falling on earth except when he''ll allowed this, from the misdeeds of You slave so-and-so tell the name of the person, from his soldiers, from his partisans among the djinns and the human beings. Ô Lord ! Be my protector from their misdeeds. Exalted is Your praise, honoured is Your protected, blessed is Your name and none has the right to be worshipped except You.');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.039', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-039', 39, 'Against enemies', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.039.part.001', 'dua.hisn.039', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.039.part.001.segment.001', 'dua.hisn.039.part.001', 1, 'arabic', 'ar', 'Arab', 'اللَّهُمَّ مُنْزِلَ الكِتَابِ سَريعَ الحِسابِ اهْزِمَ الأَحْزَابَ اللَّهُمَّ اهْزِمْهُمْ وَزَلْزِلْهُمْ.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.039.part.001.segment.002', 'dua.hisn.039.part.001', 2, 'transliteration', 'ar-Latn', 'Latn', 'Allahumma munzilal-kitab, sareeAAal-hisab, ihzimil-ahzab, allahummah-zimhum wazalzilhum.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.039.part.001.segment.003', 'dua.hisn.039.part.001', 3, 'translation', 'en', 'Latn', '‘O Allah, Revealer of the Book, Swift at reckoning, defeat the confederates. O Allah, defeat them and convulse them.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.040', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-040', 40, 'When being afraid of a group of people', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.040.part.001', 'dua.hisn.040', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.040.part.001.segment.001', 'dua.hisn.040.part.001', 1, 'arabic', 'ar', 'Arab', 'اللَّهُمَّ اكْفِنِيهِمْ بِما شِئْتَ.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.040.part.001.segment.002', 'dua.hisn.040.part.001', 2, 'transliteration', 'ar-Latn', 'Latn', 'Allahummak-fineehim bima shi/t.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.040.part.001.segment.003', 'dua.hisn.040.part.001', 3, 'translation', 'en', 'Latn', '‘O Allah, protect me from them with what You choose.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.041', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-041', 41, 'For one afflicted with doubt in his faith', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.041.part.001', 'dua.hisn.041', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.041.part.001.segment.001', 'dua.hisn.041.part.001', 1, 'comment', 'en', 'Latn', 'He should seek refuge in Allah');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.041.part.001.segment.002', 'dua.hisn.041.part.001', 2, 'comment', 'en', 'Latn', 'He should renounce that which is causing such doubt.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.041.part.001.segment.003', 'dua.hisn.041.part.001', 3, 'comment', 'en', 'Latn', 'He should say:');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.041.part.001.segment.004', 'dua.hisn.041.part.001', 4, 'arabic', 'ar', 'Arab', 'آمَنْـتُ بِاللهِ وَرُسُـلِه.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.041.part.001.segment.005', 'dua.hisn.041.part.001', 5, 'transliteration', 'ar-Latn', 'Latn', 'Amantu billahi warusulih.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.041.part.001.segment.006', 'dua.hisn.041.part.001', 6, 'translation', 'en', 'Latn', '‘I have believed in Allah and His Messenger.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.041.part.002', 'dua.hisn.041', 2);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.041.part.002.segment.001', 'dua.hisn.041.part.002', 1, 'comment', 'en', 'Latn', 'He should also recite the following verse:');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.041.part.002.segment.002', 'dua.hisn.041.part.002', 2, 'arabic', 'ar', 'Arab', 'هُوَ الأوَّلُ، وَالآخِـرُ، وَالظّـاهِـرُ، وَالْبـاطِـنُ، وَهُوَ بِكُلِّ شَيءٍ عَلـيم.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.041.part.002.segment.003', 'dua.hisn.041.part.002', 3, 'transliteration', 'ar-Latn', 'Latn', 'Huwa al-awwalu, waal-akhiru, waalththahiru waalbatinu wahuwa bikulli shayin AAaleem.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.041.part.002.segment.004', 'dua.hisn.041.part.002', 4, 'translation', 'en', 'Latn', '‘He is The First and The Last, Aththahir and Al-Batin and He knows well all things.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.041.part.003', 'dua.hisn.041', 3);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.041.part.003.segment.001', 'dua.hisn.041.part.003', 1, 'comment', 'en', 'Latn', 'Aththahir: Indicates the greatness of His attributes and the insignificance of every single creation in respect to His greatness and Highness, for He is above all of His creation as regards His essence and attributes.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.041.part.003.segment.002', 'dua.hisn.041.part.003', 2, 'comment', 'en', 'Latn', 'Al-Batin: Indicates His awareness and knowledge of all secrets, of that which is in the hearts and the most intimate of things just as it indicates His closeness and nearness to all in a manner which befits His majesty.');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.042', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-042', 42, 'Settling a debt', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.042.part.001', 'dua.hisn.042', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.042.part.001.segment.001', 'dua.hisn.042.part.001', 1, 'arabic', 'ar', 'Arab', 'اللّهُـمَّ اكْفِـني بِحَلالِـكَ عَنْ حَـرامِـك، وَأَغْنِـني بِفَضْـلِكِ عَمَّـنْ سِـواك.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.042.part.001.segment.002', 'dua.hisn.042.part.001', 2, 'transliteration', 'ar-Latn', 'Latn', 'Allahummak-finee bihalalika AAan haramik, wa-aghninee bifadlika AAamman siwak.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.042.part.001.segment.003', 'dua.hisn.042.part.001', 3, 'translation', 'en', 'Latn', '‘O Allah, make what is lawful enough for me, as opposed to what is unlawful, and spare me by Your grace, of need of others.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.042.part.002', 'dua.hisn.042', 2);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.042.part.002.segment.001', 'dua.hisn.042.part.002', 1, 'arabic', 'ar', 'Arab', 'اللّهُـمَّ إِنِّي أَعْوذُ بِكَ مِنَ الهَـمِّ وَ الْحُـزْنِ، والعًجْـزِ والكَسَلِ والبُخْـلِ والجُـبْنِ، وضَلْـعِ الـدَّيْنِ وغَلَبَـةِ الرِّجال.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.042.part.002.segment.002', 'dua.hisn.042.part.002', 2, 'transliteration', 'ar-Latn', 'Latn', 'Allahumma innee aAAoothu bika minal-hammi walhuzn, walAAajzi walkasal, walbukhl, waljubn, wadalAAid-dayni waghalabatir-rijal.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.042.part.002.segment.003', 'dua.hisn.042.part.002', 3, 'translation', 'en', 'Latn', '‘O Allah, I take refuge in You from anxiety and sorrow, weakness and laziness, miserliness and cowardice, the burden of debts and from being over powered by men.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.043', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-043', 43, 'Supplication for expelling the devil and his whisperings', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.043.part.001', 'dua.hisn.043', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.043.part.001.segment.001', 'dua.hisn.043.part.001', 1, 'arabic', 'ar', 'Arab', 'أَعـوذُ بِاللهِ مِنَ الشَّيْـطانِ الرَّجيـم');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.043.part.001.segment.002', 'dua.hisn.043.part.001', 2, 'transliteration', 'ar-Latn', 'Latn', 'Acudhu bi-l-lahi mina sh-shaytani r-rajim.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.043.part.001.segment.003', 'dua.hisn.043.part.001', 3, 'translation', 'en', 'Latn', 'Seek refuge in Allah from him and spit on your left side three times.');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.044', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-044', 44, 'For one whose affairs have become difficult', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.044.part.001', 'dua.hisn.044', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.044.part.001.segment.001', 'dua.hisn.044.part.001', 1, 'arabic', 'ar', 'Arab', 'اللّهُـمَّ لا سَـهْلَ إِلاّ ما جَعَلـتَهُ سَهـلاً، وَأَنْتَ تَجْـعَلُ الْحَـزَنَ إِذا شِـئْتَ سَهـْلاً.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.044.part.001.segment.002', 'dua.hisn.044.part.001', 2, 'transliteration', 'ar-Latn', 'Latn', 'Allahumma la sahla illa ma jaAAaltahu sahla, wa-anta tajAAalul- hazana in shi/ta sahla.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.044.part.001.segment.003', 'dua.hisn.044.part.001', 3, 'translation', 'en', 'Latn', '‘O Allah, there is no ease except in that which You have made easy, and You make the difficulty, if You wish, easy.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.045', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-045', 45, 'Upon committing a sin', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.045.part.001', 'dua.hisn.045', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.045.part.001.segment.001', 'dua.hisn.045.part.001', 1, 'translation', 'en', 'Latn', '‘Any servant who commits a sin and as a result, performs ablution, prays two units of prayer (i.e. two rakAAas) and then seeks Allah’s forgiveness, Allah would forgive him.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.046', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-046', 46, 'For expelling the devil and his whisperings', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.046.part.001', 'dua.hisn.046', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.046.part.001.segment.001', 'dua.hisn.046.part.001', 1, 'comment', 'en', 'Latn', 'Seeking refuge from him.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.046.part.001.segment.002', 'dua.hisn.046.part.001', 2, 'comment', 'en', 'Latn', 'The athan (call to prayer).');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.046.part.001.segment.003', 'dua.hisn.046.part.001', 3, 'comment', 'en', 'Latn', 'Recitation of the Quran and the authentic texts of remembrance and supplications.');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.047', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-047', 47, 'When stricken with a mishap or overtaken by an affair', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.047.part.001', 'dua.hisn.047', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.047.part.001.segment.001', 'dua.hisn.047.part.001', 1, 'comment', 'en', 'Latn', '‘The strong believer is better and more beloved to Allah, than the weak believer and there is goodness in both. Strive for that which will benefit you ,seek help from Allah and do not despair.If a mishap should happen to befall you then do not say ‘If only I had actedsuch and such would have happened’.Rather, say:');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.047.part.001.segment.002', 'dua.hisn.047.part.001', 2, 'arabic', 'ar', 'Arab', 'قَدَّرَ اللهُ وَما شـاءَ فَعَـل.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.047.part.001.segment.003', 'dua.hisn.047.part.001', 3, 'transliteration', 'ar-Latn', 'Latn', 'Qaddaral-lah, wama shaa faAAal.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.047.part.001.segment.004', 'dua.hisn.047.part.001', 4, 'translation', 'en', 'Latn', '‘Allah has decreed and what He wills, He does.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.047.part.002', 'dua.hisn.047', 2);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.047.part.002.segment.001', 'dua.hisn.047.part.002', 1, 'comment', 'en', 'Latn', 'for verily ‘If’ lets in the work of the devil.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.048', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-048', 48, 'Congratulation on the occasion of a birth', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.048.part.001', 'dua.hisn.048', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.048.part.001.segment.001', 'dua.hisn.048.part.001', 1, 'arabic', 'ar', 'Arab', 'بَارَكَ اللهُ لَكَ فِالْمَوْهُوبِ, وَ شَكَرْتَ الْوَاهِب, وَ بَلَغَ أَشُدَّهُ, وَ رُزِقْتَ برَّه...بَارَكَ اللهُ لَكَ وَ بَارَكَ عَلَيْكَ، َوجَزَاكَ اللهُ خَيْراً، وَرَزَقَكَ اللهُ مِثْلَهُ، وأَجْزَلَ ثَوَابَكَ');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.048.part.001.segment.002', 'dua.hisn.048.part.001', 2, 'transliteration', 'ar-Latn', 'Latn', 'Baraka l-lahu laka fi-l-mawhubi laka, wa shakarta-l-wahiba, wa balagha ashuddahu, wa ruziqta birrahu.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.048.part.001.segment.003', 'dua.hisn.048.part.001', 3, 'translation', 'en', 'Latn', 'May Allah bless what He allots to you (this child) and may you be grateful to the One who allots him to you. May he (this child) come to maturity and may Allah allot him the good behaviour towards you.');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.048.part.002', 'dua.hisn.048', 2);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.048.part.002.segment.001', 'dua.hisn.048.part.002', 1, 'comment', 'en', 'Latn', 'Answer : May Allah bless every thing that He allots to you ! May Allah reward you by His forgiveness, allot a new-born like mine to you and give you an abundant retribution.');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.049', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-049', 49, 'Placing childen under Allah’s protection', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.049.part.001', 'dua.hisn.049', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.049.part.001.segment.001', 'dua.hisn.049.part.001', 1, 'comment', 'en', 'Latn', 'Ibn AAabbas related that the Messenger of Allahused to commend Al-Hasan and Al-Husayn to Allah’s protection, saying:');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.049.part.001.segment.002', 'dua.hisn.049.part.001', 2, 'arabic', 'ar', 'Arab', 'أُعيـذُكُمـا بِكَلِـماتِ اللهِ التّـامَّة، مِنْ كُلِّ شَيْـطانٍ وَهـامَّة، وَمِنْ كُـلِّ عَـيْنٍ لامَّـة.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.049.part.001.segment.003', 'dua.hisn.049.part.001', 3, 'transliteration', 'ar-Latn', 'Latn', 'OAAeethukuma bikalimatil-lahit-tammah, min kulli shaytanin wahammah, wamin kulli AAaynin lammah.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.049.part.001.segment.004', 'dua.hisn.049.part.001', 4, 'translation', 'en', 'Latn', '‘I commend you two to the protection of Allah’s perfect words from every devil, vermin, and every evil eye.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.050', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-050', 50, 'When visiting the sick', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.050.part.001', 'dua.hisn.050', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.050.part.001.segment.001', 'dua.hisn.050.part.001', 1, 'comment', 'en', 'Latn', 'When the Prophet (saws)would enter upon a sick person');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.050.part.001.segment.002', 'dua.hisn.050.part.001', 2, 'comment', 'en', 'Latn', 'he would say:');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.050.part.001.segment.003', 'dua.hisn.050.part.001', 3, 'arabic', 'ar', 'Arab', 'لا بأْسَ طَهـورٌ إِنْ شـاءَ الله.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.050.part.001.segment.004', 'dua.hisn.050.part.001', 4, 'transliteration', 'ar-Latn', 'Latn', 'La ba/sa tahoorun in shaal-lah.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.050.part.001.segment.005', 'dua.hisn.050.part.001', 5, 'translation', 'en', 'Latn', '‘Never mind, may it (the sickness) be a purification, if Allah wills.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.050.part.002', 'dua.hisn.050', 2);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.050.part.002.segment.001', 'dua.hisn.050.part.002', 1, 'comment', 'en', 'Latn', '‘Any Muslim servant who visits a sick person whose prescribed moment of death has not arrived and supplicates seven times:');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.050.part.002.segment.002', 'dua.hisn.050.part.002', 2, 'arabic', 'ar', 'Arab', 'أَسْـأَلُ اللهَ العَـظيـم، رَبَّ العَـرْشِ العَـظيـم أَنْ يَشْفـيك.(سبع مرات)');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.050.part.002.segment.003', 'dua.hisn.050.part.002', 3, 'transliteration', 'ar-Latn', 'Latn', 'Asalul-lahal-AAatheem rabbal-AAarshil-AAatheem an yashfeek (7times).');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.050.part.002.segment.004', 'dua.hisn.050.part.002', 4, 'translation', 'en', 'Latn', '‘I ask Allah The Supreme, Lord of the magnificent throne to cure you’.');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.050.part.003', 'dua.hisn.050', 3);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.050.part.003.segment.001', 'dua.hisn.050.part.003', 1, 'comment', 'en', 'Latn', 'he (the sick person) will be cured.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.051', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-051', 51, 'Excellence of visiting the sick', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.051.part.001', 'dua.hisn.051', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.051.part.001.segment.001', 'dua.hisn.051.part.001', 1, 'translation', 'en', 'Latn', '‘Ali Ibn Abee Talib related that he heard the Messenger of Allahsay: ‘If a man calls on his sick Muslim brother, it is as if he walks reaping the fruits of Paradise until he sits, and when he sits he is showered in mercy, and if this was in the morning, seventy thousand angles send prayers upon him until the evening, and if this was in the evening, seventy thousand angles send prayers upon him until the morning.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.052', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-052', 52, 'When the sick have renounced all hope of life', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.052.part.001', 'dua.hisn.052', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.052.part.001.segment.001', 'dua.hisn.052.part.001', 1, 'arabic', 'ar', 'Arab', 'أللّهُـمَّ اغْفِـرْ لي وَارْحَمْـني وَأَلْحِقْـني بِالرَّفـيقِ الأّعْلـى.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.052.part.001.segment.002', 'dua.hisn.052.part.001', 2, 'transliteration', 'ar-Latn', 'Latn', 'Allahummagh-fir lee, warhamnee wa-alhiqnee birrafeeqil-aAAla.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.052.part.001.segment.003', 'dua.hisn.052.part.001', 3, 'translation', 'en', 'Latn', '‘O Allah, forgive me, have mercy upon me and unite me with the higher companions.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.052.part.002', 'dua.hisn.052', 2);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.052.part.002.segment.001', 'dua.hisn.052.part.002', 1, 'comment', 'en', 'Latn', 'Refer to the Quran, chapter 4, verse: 69.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.052.part.002.segment.002', 'dua.hisn.052.part.002', 2, 'comment', 'en', 'Latn', 'AAaishah رضي الله عنهاrelated that the Prophet (saws)(during his illness in which he passed away) would dip his hands in water and then he would wipe his face');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.052.part.002.segment.003', 'dua.hisn.052.part.002', 3, 'comment', 'en', 'Latn', 'and say:');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.052.part.002.segment.004', 'dua.hisn.052.part.002', 4, 'arabic', 'ar', 'Arab', 'لَا إِلَهَ إِلَّا الله، إِنَّ للمَـوْتِ لَسَكَـرات.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.052.part.002.segment.005', 'dua.hisn.052.part.002', 5, 'transliteration', 'ar-Latn', 'Latn', 'La ilaha illal-lah, inna lilmawti lasakarat.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.052.part.002.segment.006', 'dua.hisn.052.part.002', 6, 'translation', 'en', 'Latn', '‘None has the right to be worshipped except Allah, death does indeed contain agony.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.052.part.003', 'dua.hisn.052', 3);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.052.part.003.segment.001', 'dua.hisn.052.part.003', 1, 'arabic', 'ar', 'Arab', 'لا إلهَ إلاّ اللّهُ وَاللّهُ أَكْبَـر، لا إلهَ إلاّ اللّهُ وحْـدَهُ لا شَريكَ لهُ، لا إلهَ إلاّ اللّهُ لهُ المُلكُ ولهُ الحَمْد، لا إلهَ إلاّ اللّهُ وَلا حَـوْلَ وَلا قُـوَّةَ إِلاّ بِالله.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.052.part.003.segment.002', 'dua.hisn.052.part.003', 2, 'transliteration', 'ar-Latn', 'Latn', 'La ilaha illal-lah, wallahu akbar, la ilaha illal-lahu wahdah, la shareeka lah, la ilaha illal-lahu lahul-mulku walahul-hamd, la ilaha illal-lah, wala hawla wala quwwata illa billah.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.052.part.003.segment.003', 'dua.hisn.052.part.003', 3, 'translation', 'en', 'Latn', '‘None has the right to be worshipped except Allah and Allah is the greatest.None has the right to be worshipped except Allah, alone.None has the right to be worshipped except Allah, alone, without partner.None has the right to be worshipped except Allah, to Him belongs all sovereignty and praise.None has the right to be worshipped except Allah and there is no might and no power except with Allah.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.053', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-053', 53, 'Instruction for the one nearing death', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.053.part.001', 'dua.hisn.053', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.053.part.001.segment.001', 'dua.hisn.053.part.001', 1, 'comment', 'en', 'Latn', 'i.e. those around the sick should instruct and encourage him to say the shahadah.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.053.part.001.segment.002', 'dua.hisn.053.part.001', 2, 'comment', 'en', 'Latn', '‘He whose last words are:');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.053.part.001.segment.003', 'dua.hisn.053.part.001', 3, 'arabic', 'ar', 'Arab', 'لا إلهَ إلاّ اللّه.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.053.part.001.segment.004', 'dua.hisn.053.part.001', 4, 'transliteration', 'ar-Latn', 'Latn', 'La ilaha illal-lah.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.053.part.001.segment.005', 'dua.hisn.053.part.001', 5, 'translation', 'en', 'Latn', '‘None has the right to be worshipped except Allah.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.053.part.002', 'dua.hisn.053', 2);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.053.part.002.segment.001', 'dua.hisn.053.part.002', 1, 'comment', 'en', 'Latn', 'will enter Paradise.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.054', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-054', 54, 'For one afflicted by a calamity', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.054.part.001', 'dua.hisn.054', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.054.part.001.segment.001', 'dua.hisn.054.part.001', 1, 'arabic', 'ar', 'Arab', 'إِنّا للهِ وَإِنَا إِلَـيْهِ راجِعـون، اللهُـمِّ اْجُـرْني في مُصـيبَتي، وَاخْلُـفْ لي خَيْـراً مِنْـها.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.054.part.001.segment.002', 'dua.hisn.054.part.001', 2, 'transliteration', 'ar-Latn', 'Latn', 'Inna lillahi wa-inna ilayhi rajiAAoon, allahumma/- jurnee fee museebatee wakhluf lee khayran minha.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.054.part.001.segment.003', 'dua.hisn.054.part.001', 3, 'translation', 'en', 'Latn', '‘To Allah we belong and unto Him is our return.O Allah, recompense me for my affliction and replace it for me with something better.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.055', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-055', 55, 'When closing the eyes of the deceased', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.055.part.001', 'dua.hisn.055', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.055.part.001.segment.001', 'dua.hisn.055.part.001', 1, 'arabic', 'ar', 'Arab', 'اللهُـمِّ اغْفِـرْ لِـ-فلان باسـمه- وَارْفَعْ دَرَجَتَـهُ في المَهْـدِييـن، وَاخْـلُفْـهُ في عَقِـبِهِ في الغابِـرين، وَاغْفِـرْ لَنـا وَلَـهُ يا رَبَّ العـالَمـين، وَافْسَـحْ لَهُ في قَبْـرِهِ وَنَـوِّرْ لَهُ فيه.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.055.part.001.segment.002', 'dua.hisn.055.part.001', 2, 'transliteration', 'ar-Latn', 'Latn', 'Allahummagh-fir li-name the dead- warfaAA darajatahu fil-mahdiyyeen, wakhlufhu fee AAaqibihi fil-ghabireen, waghfir lana walahu ya rabbal-AAalameen wafsah lahu fee qabrih, wanawwir lahu feeh.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.055.part.001.segment.003', 'dua.hisn.055.part.001', 3, 'translation', 'en', 'Latn', '‘O Allah, forgive -here the name of the deceased is mentioned- and raise his rank among the rightly guided, and be a successor to whom he has left behind, and forgive us and him O Lord of the worlds.Make spacious his grave and illuminate it for him.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.055.part.002', 'dua.hisn.055', 2);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.055.part.002.segment.001', 'dua.hisn.055.part.002', 1, 'comment', 'en', 'Latn', 'A successor: one who succeeds another due to the latter’s absence or death. This is the correct meaning of the word khaleefah; thus, it is incorrect to believe that Adam is the khaleefah (vicegerent, as is commonly translated) of Allah on earth because Allah is never absent, and will never die.This supplication proves the correct understanding of this term and shows that Allah succeeds us and guards whom we leave behind when we die or are absent (also refer to supplication #198).');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.056', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-056', 56, 'For the deceased at the funeral prayer', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.056.part.001', 'dua.hisn.056', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.056.part.001.segment.001', 'dua.hisn.056.part.001', 1, 'arabic', 'ar', 'Arab', 'اللهُـمِّ اغْفِـرْ لَهُ وَارْحَمْـه، وَعافِهِ وَاعْفُ عَنْـه، وَأَكْـرِمْ نُزُلَـه، وَوَسِّـعْ مُدْخَـلَه، وَاغْسِلْـهُ بِالْمـاءِ وَالثَّـلْجِ وَالْبَـرَدْ، وَنَقِّـهِ مِنَ الْخطـايا كَما نَـقّيْتَ الـثَّوْبُ الأَبْيَـضُ مِنَ الدَّنَـسْ، وَأَبْـدِلْهُ داراً خَـيْراً مِنْ دارِه، وَأَهْلاً خَـيْراً مِنْ أَهْلِـه، وَزَوْجَـاً خَـيْراً مِنْ زَوْجِه، وَأَدْخِـلْهُ الْجَـنَّة، وَأَعِـذْهُ مِنْ عَذابِ القَـبْر وَعَذابِ النّـار.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.056.part.001.segment.002', 'dua.hisn.056.part.001', 2, 'transliteration', 'ar-Latn', 'Latn', 'Allahummagh-fir lahu warhamh, waAAafihi, waAAfu AAanh, wa-akrim nuzulah, wawassiAA mudkhalah, waghsilhu bilma-i waththalji walbarad, wanaqqihi minal-khataya kama naqqaytath-thawbal-abyada minad-danas, wa-abdilhu daran khayran min darih, wa-ahlan khayran min ahlih wazawjan khayran min zawjih, wa-adkhilhul-jannah, wa-aAAithhu min AAathabil-qabr, waAAathabin-nar.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.056.part.001.segment.003', 'dua.hisn.056.part.001', 3, 'translation', 'en', 'Latn', '‘O Allah, forgive and have mercy upon him, excuse him and pardon him, and make honourable his reception. Expand his entry, and cleanse him with water, snow, and ice, and purify him of sin as a white robe is purified of filth.Exchange his home for a better home, and his family for a better family, and his spouse for a better spouse. Admit him into the Garden, protect him from the punishment of the grave and the torment of the Fire.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.056.part.002', 'dua.hisn.056', 2);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.056.part.002.segment.001', 'dua.hisn.056.part.002', 1, 'arabic', 'ar', 'Arab', 'اللهُـمِّ اغْفِـرْ لِحَيِّـنا وَمَيِّتِـنا وَشـاهِدِنا، وَغائِبِـنا، وَصَغيـرِنا وَكَبيـرِنا، وَذَكَـرِنا وَأُنْثـانا. اللهُـمِّ مَنْ أَحْيَيْـتَهُ مِنّا فَأَحْيِـهِ عَلى الإِسْلام،وَمَنْ تَوَفَّـيْتَهُ مِنّا فَتَوَفَّـهُ عَلى الإِيـمان، اللهُـمِّ لا تَحْـرِمْنـا أَجْـرَه، وَلا تُضِـلَّنا بَعْـدَه.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.056.part.002.segment.002', 'dua.hisn.056.part.002', 2, 'transliteration', 'ar-Latn', 'Latn', 'Allahummagh-fir lihayyina wamayyitina washahidina, wagha-ibina, wasagheerina wakabeerina, wathakarina wa-onthana. Allahumma man ahyaytahu minna fa-ahyihi AAalal-islam, waman tawaffaytahu minna fatawaffahu AAalal-eeman, allahumma la tahrimna ajrah, wala tudillana baAAdah.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.056.part.002.segment.003', 'dua.hisn.056.part.002', 3, 'translation', 'en', 'Latn', '‘O Allah, forgive our living and our dead, those present and those absent, our young and our old, our males and our females.O Allah, whom amongst us You keep alive, then let such a life be upon Islam, and whom amongst us You take unto Yourself, then let such a death be upon faith.O Allah, do not deprive us of his reward and do not let us stray after him.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.056.part.003', 'dua.hisn.056', 3);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.056.part.003.segment.001', 'dua.hisn.056.part.003', 1, 'arabic', 'ar', 'Arab', 'اللهُـمِّ إِنَّ فُلانَ بْنَ فُلانٍ في ذِمَّـتِك، وَحَبْـلِ جِـوارِك، فَقِـهِ مِنْ فِتْـنَةِ الْقَـبْرِ وَعَذابِ النّـار، وَأَنْتَ أَهْلُ الْوَفـاءِ وَالْـحَقِّ، فَاغْفِـرْ لَهُ وَارْحَمْـهُ، إِنَّكَ أَنْتَ الغَـفورُ الـرَّحيم.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.056.part.003.segment.002', 'dua.hisn.056.part.003', 2, 'transliteration', 'ar-Latn', 'Latn', 'Allahumma inna -name the dead- fee thimmatik, wahabli jiwarik, faqihi min fitnatil-qabr waAAathabin-nar, wa-anta ahlul-wafa/, walhaq, faghfir lahu warhamh, innaka antal-ghafoorur-raheem.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.056.part.003.segment.003', 'dua.hisn.056.part.003', 3, 'translation', 'en', 'Latn', '‘O Allah, so-and-so is under Your care and protection so protect him from the trial of the grave and torment of the Fire.Indeed You are faithful and truthful. Forgive and have mercy upon him, surely You are The Oft-Forgiving, The Most-Merciful.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.056.part.004', 'dua.hisn.056', 4);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.056.part.004.segment.001', 'dua.hisn.056.part.004', 1, 'arabic', 'ar', 'Arab', 'اللهُـمِّ عَبْـدُكَ وَابْنُ أَمَـتِك، احْتـاجَ إِلى رَحْمَـتِك، وَأَنْتَ غَنِـيٌّ عَنْ عَذابِـه، إِنْ كانَ مُحْـسِناً فَزِدْ في حَسَـناتِه، وَإِنْ كانَ مُسـيئاً فَتَـجاوَزْ عَنْـه.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.056.part.004.segment.002', 'dua.hisn.056.part.004', 2, 'transliteration', 'ar-Latn', 'Latn', 'Allahumma AAabduka wabnu amatik, ihtaja ila rahmatik, wa-anta ghaniyyun AAan AAathabih, in kana muhsinan fazid fee hasanatih, wa-in kana museean fatajawaz AAanh.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.056.part.004.segment.003', 'dua.hisn.056.part.004', 3, 'translation', 'en', 'Latn', '‘O Allah, Your servant and the son of Your maidservant is in need of Your mercy and You are without need of his punishment. If he was righteous then increase his reward and if he was wicked then look over his sins.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.057', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-057', 57, 'For the deceased at the funeral prayer', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
