INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.057.part.004', 'dua.hisn.057', 4);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.057.part.004.segment.001', 'dua.hisn.057.part.004', 1, 'arabic', 'ar', 'Arab', 'اللهُـمِّ عَبْـدُكَ وَابْنُ أَمَـتِك، احْتـاجَ إِلى رَحْمَـتِك، وَأَنْتَ غَنِـيٌّ عَنْ عَذابِـه، إِنْ كانَ مُحْـسِناً فَزِدْ في حَسَـناتِه، وَإِنْ كانَ مُسـيئاً فَتَـجاوَزْ عَنْـه.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.057.part.004.segment.002', 'dua.hisn.057.part.004', 2, 'transliteration', 'ar-Latn', 'Latn', 'Allahumma AAabduka wabnu amatik, ihtaja ila rahmatik, wa-anta ghaniyyun AAan AAathabih, in kana muhsinan fazid fee hasanatih, wa-in kana museean fatajawaz AAanh.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.057.part.004.segment.003', 'dua.hisn.057.part.004', 3, 'translation', 'en', 'Latn', '‘O Allah, Your servant and the son of Your maidservant is in need of Your mercy and You are without need of his punishment. If he was righteous then increase his reward and if he was wicked then look over his sins.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.058', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-058', 58, 'When the deceased is a child, during the funeral prayer', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.058.part.001', 'dua.hisn.058', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.058.part.001.segment.001', 'dua.hisn.058.part.001', 1, 'comment', 'en', 'Latn', 'This supplication is made when the deceased is a baby/child (i.e. one not having reached the age of puberty).');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.058.part.001.segment.002', 'dua.hisn.058.part.001', 2, 'comment', 'en', 'Latn', 'After seeking forgiveness for the deceased, one can say:');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.058.part.001.segment.003', 'dua.hisn.058.part.001', 3, 'arabic', 'ar', 'Arab', 'اللهُـمِّ اجْعَلْـهُ فَرَطـاً وَذُخْـراً لِوالِـدَيه، وَشَفـيعاً مُجـاباً، اللهُـمِّ ثَـقِّلْ بِهِ مَوازيـنَهُما، وَأَعْـظِمْ بِهِ أُجـورَهُـما، وَأَلْـحِقْـهُ بِصالِـحِ الـمؤْمِنـين، وَاجْعَلْـهُ في كَفـالَةِ إِبْـراهـيم، وَقِهِ بِرَحْمَـتِكَ عَذابَ الْجَـحيم.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.058.part.001.segment.004', 'dua.hisn.058.part.001', 4, 'transliteration', 'ar-Latn', 'Latn', 'Allahummaj-AAalhu faratan, wathukhran liwalidayh, washafeeAAan mujaban. Allahumma thaqqil bihi mawazeenahuma wa-aAAthim bihi ojoorahuma, wa-alhiqhu bisalihil-mu/mineen, wajAAalhu fee kafalati Ibraheem, waqihi birahmatika AAathabal-jaheem.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.058.part.001.segment.005', 'dua.hisn.058.part.001', 5, 'translation', 'en', 'Latn', '''O Allah, make him a preceding reward and a stored treasure for his parents, and an answered intercessor. O Allah, through him, make heavy their scales and magnify their reward.Unite him with the righteous believers, place him under the care of Ibraheem, and protect him by Your mercy from the torment of Hell.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.058.part.002', 'dua.hisn.058', 2);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.058.part.002.segment.001', 'dua.hisn.058.part.002', 1, 'comment', 'en', 'Latn', 'Al-Hasan used to recite the opening chapter of the Quran (i.e. AL-Fatihah) over the child');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.058.part.002.segment.002', 'dua.hisn.058.part.002', 2, 'comment', 'en', 'Latn', 'and then supplicates:');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.058.part.002.segment.003', 'dua.hisn.058.part.002', 3, 'arabic', 'ar', 'Arab', 'اللهُـمِّ اجْعَلْـهُ لَنا فَرَطـاً، وَسَلَـفاً وَأَجْـراً.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.058.part.002.segment.004', 'dua.hisn.058.part.002', 4, 'transliteration', 'ar-Latn', 'Latn', 'Allahummaj-AAalhu lana farata, wasalafan wa-ajra.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.058.part.002.segment.005', 'dua.hisn.058.part.002', 5, 'translation', 'en', 'Latn', '‘O Allah, make him a preceding reward, a prepayment and a recompense for us.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.059', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-059', 59, 'Condolence', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.059.part.001', 'dua.hisn.059', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.059.part.001.segment.001', 'dua.hisn.059.part.001', 1, 'arabic', 'ar', 'Arab', 'إِنَّ للهِ ما أَخَذ، وَلَهُ ما أَعْـطـى، وَكُـلُّ شَيءٍ عِنْـدَهُ بِأَجَلٍ مُسَـمَّى.فَلْتَصْـبِر وَلْتَحْـتَسِب.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.059.part.001.segment.002', 'dua.hisn.059.part.001', 2, 'transliteration', 'ar-Latn', 'Latn', 'Inna lillahi ma akhath, walahu ma aAAta, wakullu shayin AAindahu bi-ajalin musammafaltasbir waltahtasib.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.059.part.001.segment.003', 'dua.hisn.059.part.001', 3, 'translation', 'en', 'Latn', '‘Verily to Allah, belongs what He took and to Him belongs what He gave, and everything with Him has an appointed timeand then heordered for her to be patient and hope for Allah’s reward.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.059.part.002', 'dua.hisn.059', 2);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.059.part.002.segment.001', 'dua.hisn.059.part.002', 1, 'comment', 'en', 'Latn', 'The words (faltasbir waltahtasib) are commands in the feminine 3rd person form, so they will need to be changed in respect to whom is being addressed.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.059.part.002.segment.002', 'dua.hisn.059.part.002', 2, 'comment', 'en', 'Latn', '...and one can also say:');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.059.part.002.segment.003', 'dua.hisn.059.part.002', 3, 'arabic', 'ar', 'Arab', 'أَعْظَـمَ اللهُ أَجْـرَك، وَأَحْسَـنَ عَـزاءَ ك، وَغَفَـرَ لِمَـيِّتِك.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.059.part.002.segment.004', 'dua.hisn.059.part.002', 4, 'transliteration', 'ar-Latn', 'Latn', 'aAAthamal-lahu ajrak, wa-ahsana AAazaak, waghafara limayyitik.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.059.part.002.segment.005', 'dua.hisn.059.part.002', 5, 'translation', 'en', 'Latn', '‘May Allah magnify your reward, make better your solace and forgive your deceased.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.059.part.003', 'dua.hisn.059', 3);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.059.part.003.segment.001', 'dua.hisn.059.part.003', 1, 'comment', 'en', 'Latn', 'This is the saying of some of the scholars, not a hadeeth.');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.060', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-060', 60, 'Placing the deceased in the grave', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.060.part.001', 'dua.hisn.060', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.060.part.001.segment.001', 'dua.hisn.060.part.001', 1, 'arabic', 'ar', 'Arab', 'بِسْـمِ اللهِ وَعَلـى سُـنَّةِ رَسـولِ الله.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.060.part.001.segment.002', 'dua.hisn.060.part.001', 2, 'transliteration', 'ar-Latn', 'Latn', 'Bismil-lahi waAAala sunnati rasoolil-lah.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.060.part.001.segment.003', 'dua.hisn.060.part.001', 3, 'translation', 'en', 'Latn', '‘In the name of Allah and upon the sunnah of the Messenger of Allah.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.061', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-061', 61, 'After burying the deceased', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.061.part.001', 'dua.hisn.061', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.061.part.001.segment.001', 'dua.hisn.061.part.001', 1, 'comment', 'en', 'Latn', 'and say: ‘Seek forgiveness for your brother and pray that he remains firm, for he is now being questioned’.’');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.061.part.001.segment.002', 'dua.hisn.061.part.001', 2, 'translation', 'en', 'Latn', '‘After the Prophet (saws) would bury the deceased he would stand by the grave');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.062', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-062', 62, 'Visiting the graves', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.062.part.001', 'dua.hisn.062', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.062.part.001.segment.001', 'dua.hisn.062.part.001', 1, 'arabic', 'ar', 'Arab', 'السَّلامُ عَلَـيْكُمْ أَهْلَ الدِّيارِ مِنَ المؤْمِنيـنَ وَالْمُسْلِمين، وَإِنّا إِنْ شاءَ اللهُ بِكُـمْ لاحِقـون، نَسْـاَلُ اللهَ لنـا وَلَكُـمْ العـافِيَة.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.062.part.001.segment.002', 'dua.hisn.062.part.001', 2, 'transliteration', 'ar-Latn', 'Latn', 'Assalamu AAalaykum ahlad-diyari minal-mu/mineena walmuslimeen, wa-inna in shaal-lahu bikum lahiqoon, nas-alul-laha lana walakumul-AAafiyah.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.062.part.001.segment.003', 'dua.hisn.062.part.001', 3, 'translation', 'en', 'Latn', '‘Peace be upon you all, O inhabitants of the graves, amongst the believers and the Muslims. Verily we will, Allah willing, be united with you, we ask Allah for well-being for us and you.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.063', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-063', 63, 'During a wind storm', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.063.part.001', 'dua.hisn.063', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.063.part.001.segment.001', 'dua.hisn.063.part.001', 1, 'arabic', 'ar', 'Arab', 'اللّهُـمَّ إِنَّـي أَسْـأَلُـكَ خَيْـرَها، وَأَعـوذُ بِكَ مِنْ شَـرِّها.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.063.part.001.segment.002', 'dua.hisn.063.part.001', 2, 'transliteration', 'ar-Latn', 'Latn', 'Allahumma innee as-aluka khayraha wa-aAAoothu bika min sharriha.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.063.part.001.segment.003', 'dua.hisn.063.part.001', 3, 'translation', 'en', 'Latn', '‘O Allah, I ask You for it’s goodness and I take refuge with You from it’s evil.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.063.part.002', 'dua.hisn.063', 2);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.063.part.002.segment.001', 'dua.hisn.063.part.002', 1, 'arabic', 'ar', 'Arab', 'اللّهُـمَّ إِنَّـي أَسْـأَلُـكَ خَيْـرَها، وَخَيْـرَ ما فيهـا، وَخَيْـرَ ما اُرْسِلَـتْ بِه، وَأَعـوذُ بِكَ مِنْ شَـرِّها، وَشَـرِّ ما فيهـا، وَشَـرِّ ما اُرْسِلَـتْ بِه.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.063.part.002.segment.002', 'dua.hisn.063.part.002', 2, 'transliteration', 'ar-Latn', 'Latn', 'Allahumma innee as-aluka khayraha wakhayra ma feeha, wakhayra ma orsilat bih, wa-aAAoothu bika min sharriha, washarri ma feeha washarri ma orsilat bih.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.063.part.002.segment.003', 'dua.hisn.063.part.002', 3, 'translation', 'en', 'Latn', '‘O Allah, I ask You for it’s goodness, the good within it, and the good it was sent with, and I take refuge with You from it’s evil, the evil within it, and from the evil it was sent with.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.064', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-064', 64, 'Upon hearing thunder', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.064.part.001', 'dua.hisn.064', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.064.part.001.segment.001', 'dua.hisn.064.part.001', 1, 'comment', 'en', 'Latn', 'When AAabdullah Ibn Az-Zubayr used to hear thunder he would stop talking');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.064.part.001.segment.002', 'dua.hisn.064.part.001', 2, 'comment', 'en', 'Latn', 'and say:');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.064.part.001.segment.003', 'dua.hisn.064.part.001', 3, 'arabic', 'ar', 'Arab', 'سُبْـحانَ الّذي يُسَبِّـحُ الـرَّعْدُ بِحَمْـدِهِ، وَالملائِكـةُ مِنْ خيـفَته.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.064.part.001.segment.004', 'dua.hisn.064.part.001', 4, 'transliteration', 'ar-Latn', 'Latn', 'Subhanal-lathee yusabbihur-raAAdu bihamdih, walmala-ikatu min kheefatih.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.064.part.001.segment.005', 'dua.hisn.064.part.001', 5, 'translation', 'en', 'Latn', '‘How perfect He is, (The One) Whom the thunder declares His perfection with His praise, as do the angles out of fear of Him.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.065', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-065', 65, 'For rain', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.065.part.001', 'dua.hisn.065', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.065.part.001.segment.001', 'dua.hisn.065.part.001', 1, 'arabic', 'ar', 'Arab', 'اللّهُمَّ اسْقِـنا غَيْـثاً مُغيـثاً مَريئاً مُريـعاً، نافِعـاً غَيْـرَ ضار، عاجِـلاً غَـيْرَ آجِل.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.065.part.001.segment.002', 'dua.hisn.065.part.001', 2, 'transliteration', 'ar-Latn', 'Latn', 'Allahummas-qina ghaythan mugheethan maree-an mureeAAan, nafiAAan, ghayra dar, AAajilan ghayra ajil.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.065.part.001.segment.003', 'dua.hisn.065.part.001', 3, 'translation', 'en', 'Latn', '‘O Allah, send upon us helpful, wholesome and healthy rain, beneficial not harmful rain, now, not later.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.065.part.002', 'dua.hisn.065', 2);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.065.part.002.segment.001', 'dua.hisn.065.part.002', 1, 'arabic', 'ar', 'Arab', 'اللّهُمَّ أغِثْنـا، اللّهُمَّ أغِثْنـا، اللّهُمَّ أغِثْنـا.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.065.part.002.segment.002', 'dua.hisn.065.part.002', 2, 'transliteration', 'ar-Latn', 'Latn', 'Allahumma aghithna, allahumma aghithna, allahumma aghithna.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.065.part.002.segment.003', 'dua.hisn.065.part.002', 3, 'translation', 'en', 'Latn', '‘O Allah, relieve us, O Allah, relieve us, O Allah, relieve us.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.065.part.003', 'dua.hisn.065', 3);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.065.part.003.segment.001', 'dua.hisn.065.part.003', 1, 'arabic', 'ar', 'Arab', 'اللّهُمَّ اسْقِ عِبادَكَ وَبَهـائِمَك، وَانْشُـرْ رَحْمَـتَكَ وَأَحْيِي بَلَـدَكَ المَيِّـت.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.065.part.003.segment.002', 'dua.hisn.065.part.003', 2, 'transliteration', 'ar-Latn', 'Latn', 'Allahummas-qi AAibadak, wabaha-imak, wanshur rahmatak, wa-ahyi baladakal-mayyit.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.065.part.003.segment.003', 'dua.hisn.065.part.003', 3, 'translation', 'en', 'Latn', '‘O Allah, provide water for Your servants and Your cattle, spread out Your mercy and resurrect Your dead land.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.066', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-066', 66, 'When it rains', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.066.part.001', 'dua.hisn.066', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.066.part.001.segment.001', 'dua.hisn.066.part.001', 1, 'arabic', 'ar', 'Arab', 'اللّهُمَّ صَيِّـباً نافِـعاً.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.066.part.001.segment.002', 'dua.hisn.066.part.001', 2, 'transliteration', 'ar-Latn', 'Latn', 'Allahumma sayyiban nafiAAa.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.066.part.001.segment.003', 'dua.hisn.066.part.001', 3, 'translation', 'en', 'Latn', '‘O Allah, may it be a beneficial rain cloud.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.067', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-067', 67, 'After rainfall', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.067.part.001', 'dua.hisn.067', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.067.part.001.segment.001', 'dua.hisn.067.part.001', 1, 'arabic', 'ar', 'Arab', 'مُطِـرْنا بِفَضْـلِ اللهِ وَرَحْمَـتِه.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.067.part.001.segment.002', 'dua.hisn.067.part.001', 2, 'transliteration', 'ar-Latn', 'Latn', 'Mutirna bifadlil-lahi warahmatih.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.067.part.001.segment.003', 'dua.hisn.067.part.001', 3, 'translation', 'en', 'Latn', '‘We have been given rain by the grace and mercy of Allah.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.068', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-068', 68, 'Asking for clear skies', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.068.part.001', 'dua.hisn.068', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.068.part.001.segment.001', 'dua.hisn.068.part.001', 1, 'arabic', 'ar', 'Arab', 'اللّهُمَّ حَوالَيْنا وَلا عَلَيْـنا، اللّهُمَّ عَلى الآكـامِ وَالظِّـراب، وَبُطـونِ الأوْدِية، وَمَنـابِتِ الشَّجـر.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.068.part.001.segment.002', 'dua.hisn.068.part.001', 2, 'transliteration', 'ar-Latn', 'Latn', 'Allahumma hawalayna wala AAalayna, allahumma AAalal-akami waththirab, wabutoonil-awdiyah, wamanabitish-shajar.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.068.part.001.segment.003', 'dua.hisn.068.part.001', 3, 'translation', 'en', 'Latn', '‘O Allah, let the rain fall around us and not upon us, O Allah, (let it fall) on the pastures, hills, valleys and the roots of trees.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.069', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-069', 69, 'Upon sighting the crescent moon', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.069.part.001', 'dua.hisn.069', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.069.part.001.segment.001', 'dua.hisn.069.part.001', 1, 'arabic', 'ar', 'Arab', 'اللهُ أَكْـبَر، اللّهُمَّ أَهِلَّـهُ عَلَيْـنا بِالأمْـنِ وَالإيمـان، والسَّلامَـةِ والإسْلام، وَالتَّـوْفيـقِ لِما تُحِـبُّ وَتَـرْضـى، رَبُّنـا وَرَبُّكَ الله.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.069.part.001.segment.002', 'dua.hisn.069.part.001', 2, 'transliteration', 'ar-Latn', 'Latn', 'Allahu akbar, allahumma ahillahu AAalayna bil-amni wal-eeman, wassalamati wal-islam, wattawfeeiqi lima tuhibbu watarda, rabbuna warabbukal-lah.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.069.part.001.segment.003', 'dua.hisn.069.part.001', 3, 'translation', 'en', 'Latn', '‘Allah is the greatest. O Allah, let the crescent loom above us in safety, faith, peace, and Islam, and in agreement with all that You love and pleases You. Our Lord and your Lord is Allah.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.070', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-070', 70, 'Upon breaking fast', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.070.part.001', 'dua.hisn.070', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.070.part.001.segment.001', 'dua.hisn.070.part.001', 1, 'arabic', 'ar', 'Arab', 'ذَهَـبَ الظَّمَـأُ، وَابْتَلَّـتِ العُـروق، وَثَبَـتَ الأجْـرُ إِنْ شـاءَ الله.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.070.part.001.segment.002', 'dua.hisn.070.part.001', 2, 'transliteration', 'ar-Latn', 'Latn', 'Thahabath-thama-o wabtallatil-AAurooq, wathabatal-ajru in shaal-lah.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.070.part.001.segment.003', 'dua.hisn.070.part.001', 3, 'translation', 'en', 'Latn', '‘The thirst has gone and the veins are quenched, and reward is confirmed, if Allah wills.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.070.part.002', 'dua.hisn.070', 2);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.070.part.002.segment.001', 'dua.hisn.070.part.002', 1, 'comment', 'en', 'Latn', '‘AAabdullah Ibn AAamr Ibn Al-AAas related that the Messenger of Allah said: ‘Indeed the fasting person has at the time of breaking fast, a supplication which is not rejected’.Ibn Abee Mulaykah رحمه اللهsaid: ‘I Heard AAabdullah Ibn AAomar say when he broke his fast:');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.070.part.002.segment.002', 'dua.hisn.070.part.002', 2, 'arabic', 'ar', 'Arab', 'اللّهُـمَّإِنَّـي أَسْـأَلُـكَ بِرَحْمَـتِكَ الّتي وَسِـعَت كُلَّ شيء، أَنْ تَغْـفِرَ لي.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.070.part.002.segment.003', 'dua.hisn.070.part.002', 3, 'transliteration', 'ar-Latn', 'Latn', 'Allahumma inne as-aluka birahmatikal-latee wasiAAat kulla shay, an taghfira lee.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.070.part.002.segment.004', 'dua.hisn.070.part.002', 4, 'translation', 'en', 'Latn', '‘O Allah, I ask You by Your mercy which envelopes all things, that You forgive me.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.071', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-071', 71, 'Before eating', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.071.part.001', 'dua.hisn.071', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.071.part.001.segment.001', 'dua.hisn.071.part.001', 1, 'comment', 'en', 'Latn', '‘When you are about to eat, you should say:');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.071.part.001.segment.002', 'dua.hisn.071.part.001', 2, 'comment', 'en', 'Latn', 'and if you forget to say it before starting, then you should say (when you remember):');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.071.part.001.segment.003', 'dua.hisn.071.part.001', 3, 'arabic', 'ar', 'Arab', 'بِسْمِ الله.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.071.part.001.segment.004', 'dua.hisn.071.part.001', 4, 'transliteration', 'ar-Latn', 'Latn', 'Bismil-lah.');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.071.part.002', 'dua.hisn.071', 2);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.071.part.002.segment.001', 'dua.hisn.071.part.002', 1, 'arabic', 'ar', 'Arab', 'بِسْمِ اللهِ في أَوَّلِهِ وَآخِـرِه.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.071.part.002.segment.002', 'dua.hisn.071.part.002', 2, 'transliteration', 'ar-Latn', 'Latn', 'Bismil-lahi fee awwalihi wa-akhirih.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.071.part.002.segment.003', 'dua.hisn.071.part.002', 3, 'translation', 'en', 'Latn', '‘In the name of Allah in it’s beginning and end.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.071.part.003', 'dua.hisn.071', 3);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.071.part.003.segment.001', 'dua.hisn.071.part.003', 1, 'comment', 'en', 'Latn', '‘Whomever Allah feeds, should say:');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.071.part.003.segment.002', 'dua.hisn.071.part.003', 2, 'arabic', 'ar', 'Arab', 'اللّهُـمَّ بارِكْ لَنا فيهِ وَأَطْـعِمْنا خَـيْراً مِنْـه.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.071.part.003.segment.003', 'dua.hisn.071.part.003', 3, 'transliteration', 'ar-Latn', 'Latn', 'Allahumma barik lana feehi wa-atAAimna khayran minh.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.071.part.003.segment.004', 'dua.hisn.071.part.003', 4, 'translation', 'en', 'Latn', '‘O Allah, bless it for us and feed us better than it.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.071.part.004', 'dua.hisn.071', 4);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.071.part.004.segment.001', 'dua.hisn.071.part.004', 1, 'comment', 'en', 'Latn', '.and whomever Allah gives milk to drink should say:');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.071.part.004.segment.002', 'dua.hisn.071.part.004', 2, 'arabic', 'ar', 'Arab', 'اللّهُـمَّ بارِكْ لَنا فيهِ وَزِدْنا مِنْه.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.071.part.004.segment.003', 'dua.hisn.071.part.004', 3, 'transliteration', 'ar-Latn', 'Latn', 'Allahumma barik lana feehi wazidna minh.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.071.part.004.segment.004', 'dua.hisn.071.part.004', 4, 'translation', 'en', 'Latn', '‘O Allah, bless it for usand give us more of it.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.072', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-072', 72, 'Upon completing the meal', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.072.part.001', 'dua.hisn.072', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.072.part.001.segment.001', 'dua.hisn.072.part.001', 1, 'arabic', 'ar', 'Arab', 'الْحَمْـدُ للهِ الَّذي أَطْعَمَنـي هـذا وَرَزَقَنـيهِ مِنْ غَـيْرِ حَوْلٍ مِنِّي وَلا قُوَّة.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.072.part.001.segment.002', 'dua.hisn.072.part.001', 2, 'transliteration', 'ar-Latn', 'Latn', 'Alhamdu lillahil-lathee atAAamanee hatha warazaqaneehi min ghayri hawlin minnee wala quwwah.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.072.part.001.segment.003', 'dua.hisn.072.part.001', 3, 'translation', 'en', 'Latn', '‘All praise is for Allah who fed me this and provided it for me without any might nor power from myself.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.072.part.002', 'dua.hisn.072', 2);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.072.part.002.segment.001', 'dua.hisn.072.part.002', 1, 'arabic', 'ar', 'Arab', 'الْحَمْـدُ للهِ حَمْـداً كَثـيراً طَيِّـباً مُبـارَكاً فيه، غَيْرَ مَكْفِيٍّ وَلا مُوَدَّعٍ وَلا مُسْتَغْـنىً عَنْـهُ رَبُّـنا.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.072.part.002.segment.002', 'dua.hisn.072.part.002', 2, 'transliteration', 'ar-Latn', 'Latn', 'Alhamdu lillahi hamdan katheeran tayyiban mubarakan feeh, ghayra makfiyyin wala muwaddaAAin, wala mustaghnan AAanhu rabbuna.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.072.part.002.segment.003', 'dua.hisn.072.part.002', 3, 'translation', 'en', 'Latn', '‘Allah be praised with an abundant beautiful blessed praise, a never-ending praise, a praise which we will never bid farewell to and an indispensable praise, He is our Lord.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.072.part.003', 'dua.hisn.072', 3);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.072.part.003.segment.001', 'dua.hisn.072.part.003', 1, 'comment', 'en', 'Latn', 'There are other views as regards to the understanding of this supplication, from them: Allah be praised with an abundant beautiful blessed praise. He is The One Who is sufficient, feeds and is not fed. The One Who is longed for, along with that which is with Him and The One Who is needed, He is our Lord.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.073', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-073', 73, 'Of the guest for the host', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.073.part.001', 'dua.hisn.073', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.073.part.001.segment.001', 'dua.hisn.073.part.001', 1, 'arabic', 'ar', 'Arab', 'اللّهُـمَّ بارِكْ لَهُمْ فيما رَزَقْـتَهُم، وَاغْفِـرْ لَهُـمْ وَارْحَمْهُمْ.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.073.part.001.segment.002', 'dua.hisn.073.part.001', 2, 'transliteration', 'ar-Latn', 'Latn', 'Allahumma barik lahum feema razaqtahum, waghfir lahum warhamhum.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.073.part.001.segment.003', 'dua.hisn.073.part.001', 3, 'translation', 'en', 'Latn', '‘O Allah, bless for them, that which You have provided them, forgive them and have mercy upon them.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.074', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-074', 74, 'To one offering a drink or to one who intended to do that', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.074.part.001', 'dua.hisn.074', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.074.part.001.segment.001', 'dua.hisn.074.part.001', 1, 'arabic', 'ar', 'Arab', 'اللّهُـمَّ أَطْعِمْ مَن أَطْعَمَني، وَاسْقِ مَن سقاني.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.074.part.001.segment.002', 'dua.hisn.074.part.001', 2, 'transliteration', 'ar-Latn', 'Latn', 'Allahumma atAAim man atAAamanee wasqi man saqanee.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.074.part.001.segment.003', 'dua.hisn.074.part.001', 3, 'translation', 'en', 'Latn', '‘O Allah, feed him who fed me, and provide with drink him who provided me with drink.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.075', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-075', 75, 'When breaking fast in someone’s home', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.075.part.001', 'dua.hisn.075', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.075.part.001.segment.001', 'dua.hisn.075.part.001', 1, 'arabic', 'ar', 'Arab', 'أَفْطَـرَ عِنْدَكُم الصّـائِمونَ وَأَكَلَ طَعامَـكُمُ الأبْـرار، وَصَلَّـتْ عَلَـيْكُمُ الملائِكَـة.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.075.part.001.segment.002', 'dua.hisn.075.part.001', 2, 'transliteration', 'ar-Latn', 'Latn', 'Aftara AAindakumus-sa-imoon, wa-akala taAAamakumul-abrar, wasallat AAalaykumul-mala-ikah.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.075.part.001.segment.003', 'dua.hisn.075.part.001', 3, 'translation', 'en', 'Latn', '‘May the fasting break their fast in your home, and may the dutiful and pious eat your food, and may the angles send prayers upon you.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.076', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-076', 76, 'By one fasting when presented with food and does not break his fast', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.076.part.001', 'dua.hisn.076', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.076.part.001.segment.001', 'dua.hisn.076.part.001', 1, 'translation', 'en', 'Latn', '‘If you are not invited (to a meal) then answer.  If  you happen to be fasting, then supplicate (for those present) and if you are not fasting, then eat.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.077', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-077', 77, 'When insulted while fasting', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.077.part.001', 'dua.hisn.077', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.077.part.001.segment.001', 'dua.hisn.077.part.001', 1, 'arabic', 'ar', 'Arab', 'إِنِّي صَائِمٌ، إِنِّي صَائِمٌ.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.077.part.001.segment.002', 'dua.hisn.077.part.001', 2, 'transliteration', 'ar-Latn', 'Latn', 'Innee sa-im, innee sa-im.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.077.part.001.segment.003', 'dua.hisn.077.part.001', 3, 'translation', 'en', 'Latn', '‘I am fasting, I am fasting.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.078', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-078', 78, 'Upon seeing the early or premature fruit', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.078.part.001', 'dua.hisn.078', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.078.part.001.segment.001', 'dua.hisn.078.part.001', 1, 'arabic', 'ar', 'Arab', 'اللّهُـمَّ بارِكْ لَنا في ثَمَـرِنا، وَبارِكْ لَنا في مَدينَتِنـا، وَبارِكْ لَنا في صاعِنـا، وَبارِكْ لَنا في مُدِّنا.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.078.part.001.segment.002', 'dua.hisn.078.part.001', 2, 'transliteration', 'ar-Latn', 'Latn', 'Allahumma barik lana fee thamarina, wabarik lana fee madeenatina, wabarik lana fee saAAina wabarik lana fee muddina.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.078.part.001.segment.003', 'dua.hisn.078.part.001', 3, 'translation', 'en', 'Latn', '‘O Allah, bless our fruit for us, bless our town for us, bless our saAA for us and bless our mudd for us.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.079', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-079', 79, 'Upon sneezing', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.079.part.001', 'dua.hisn.079', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.079.part.001.segment.001', 'dua.hisn.079.part.001', 1, 'comment', 'en', 'Latn', '‘When one of you sneezes he should say:');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.079.part.001.segment.002', 'dua.hisn.079.part.001', 2, 'arabic', 'ar', 'Arab', 'الْحَمْـدُ للهِ.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.079.part.001.segment.003', 'dua.hisn.079.part.001', 3, 'transliteration', 'ar-Latn', 'Latn', 'Alhamdu lillah.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.079.part.001.segment.004', 'dua.hisn.079.part.001', 4, 'translation', 'en', 'Latn', '‘All praise if for Allah.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.079.part.002', 'dua.hisn.079', 2);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.079.part.002.segment.001', 'dua.hisn.079.part.002', 1, 'comment', 'en', 'Latn', 'and his brother or companion should say to him:');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.079.part.002.segment.002', 'dua.hisn.079.part.002', 2, 'arabic', 'ar', 'Arab', 'يَرْحَمُـكَ الله.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.079.part.002.segment.003', 'dua.hisn.079.part.002', 3, 'transliteration', 'ar-Latn', 'Latn', 'Yarhamukal-lah.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.079.part.002.segment.004', 'dua.hisn.079.part.002', 4, 'translation', 'en', 'Latn', '‘May Allah have mercy upon you.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.079.part.003', 'dua.hisn.079', 3);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.079.part.003.segment.001', 'dua.hisn.079.part.003', 1, 'comment', 'en', 'Latn', 'and he (i.e. the one who sneezed) replies back to him:');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.079.part.003.segment.002', 'dua.hisn.079.part.003', 2, 'arabic', 'ar', 'Arab', 'يَهْـديكُـمُ اللهُ وَيُصْـلِحُ بالَـكُم.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.079.part.003.segment.003', 'dua.hisn.079.part.003', 3, 'transliteration', 'ar-Latn', 'Latn', 'Yahdeekumul-lahu wayuslihu balakum.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.079.part.003.segment.004', 'dua.hisn.079.part.003', 4, 'translation', 'en', 'Latn', '‘May Allah guide you and rectify your condition.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.080', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-080', 80, 'When a misbeliever praise Allah after sneezing', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.080.part.001', 'dua.hisn.080', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.080.part.001.segment.001', 'dua.hisn.080.part.001', 1, 'arabic', 'ar', 'Arab', 'يَهْـديكُـمُ اللهُ وَيُصْـلِحُ بالَـكُم.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.080.part.001.segment.002', 'dua.hisn.080.part.001', 2, 'transliteration', 'ar-Latn', 'Latn', 'Yahdeekumul-lahu wayuslihu balakum.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.080.part.001.segment.003', 'dua.hisn.080.part.001', 3, 'translation', 'en', 'Latn', '‘May Allah guide you and rectify your condition.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.081', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-081', 81, 'To the newlywed', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.081.part.001', 'dua.hisn.081', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.081.part.001.segment.001', 'dua.hisn.081.part.001', 1, 'arabic', 'ar', 'Arab', 'بارَكَ اللّهُ لَك، وَبارَكَ عَلَـيْك، وَجَمَعَ بَيْـنَكُما في خَـيْر.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.081.part.001.segment.002', 'dua.hisn.081.part.001', 2, 'transliteration', 'ar-Latn', 'Latn', 'Barakal-lahu lak, wabaraka AAalayk, wajamaAAa baynakuma fee khayr.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.081.part.001.segment.003', 'dua.hisn.081.part.001', 3, 'translation', 'en', 'Latn', '‘May Allah bless for you (your spouse) and bless you, and may He unite both of you in goodness.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.082', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-082', 82, 'On the wedding night or when buying an animal', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.082.part.001', 'dua.hisn.082', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.082.part.001.segment.001', 'dua.hisn.082.part.001', 1, 'comment', 'en', 'Latn', 'when you marry a woman or buy a maidservant, you should say:');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.082.part.001.segment.002', 'dua.hisn.082.part.001', 2, 'arabic', 'ar', 'Arab', 'اللّهُـمَّ  إِنَّـي أَسْـأَلُـكَ خَيْـرَها، وَخَيْـرَ ما جَبَلْـتَهـا عَلَـيْه، وَأَعـوذُ بِكَ مِنْ شَـرِّها، وَشَـرِّ ما جَبَلْـتَهـا عَلَـيْه.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.082.part.001.segment.003', 'dua.hisn.082.part.001', 3, 'transliteration', 'ar-Latn', 'Latn', 'Allahumma innee as-aluka khayraha wakhayra ma jabaltaha AAalayh, wa-aAAoothu bika min sharriha washarri ma jabaltaha AAalayh.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.082.part.001.segment.004', 'dua.hisn.082.part.001', 4, 'translation', 'en', 'Latn', '‘O Allah, I ask You for the goodness within her and the goodness that you have made her inclined towards, and I take refuge with You from the evil within her and the evil that you have made her inclined towards.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.082.part.002', 'dua.hisn.082', 2);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.082.part.002.segment.001', 'dua.hisn.082.part.002', 1, 'comment', 'en', 'Latn', 'and if you buy a camel, then you should take hold of it’s hump and say likewise.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.083', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-083', 83, 'Before sexual intercourse', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.083.part.001', 'dua.hisn.083', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.083.part.001.segment.001', 'dua.hisn.083.part.001', 1, 'arabic', 'ar', 'Arab', 'بِسْمِ الله اللّهُـمَّ جَنِّبْنا الشَّيْـطانَ، وَجَنِّبِ الشَّـيْطانَ ما رَزَقْـتَنا.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.083.part.001.segment.002', 'dua.hisn.083.part.001', 2, 'transliteration', 'ar-Latn', 'Latn', 'Bismil-lah, allahumma jannibnash-shaytan, wajannibish-shaytana ma razaqtana.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.083.part.001.segment.003', 'dua.hisn.083.part.001', 3, 'translation', 'en', 'Latn', '‘In the name of Allah. O Allah, keep the devil away from us and keep the devil away from what you have blessed us with.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.084', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-084', 84, 'When angry', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.084.part.001', 'dua.hisn.084', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.084.part.001.segment.001', 'dua.hisn.084.part.001', 1, 'arabic', 'ar', 'Arab', 'أَعـوذُ بِاللهِ مِنَ الشَّيْـطانِ الرَّجيـم.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.084.part.001.segment.002', 'dua.hisn.084.part.001', 2, 'transliteration', 'ar-Latn', 'Latn', 'aAAoothu billahi minash-shaytanir-rajeem.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.084.part.001.segment.003', 'dua.hisn.084.part.001', 3, 'translation', 'en', 'Latn', '‘I take refuge with Allah from the accursed devil.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.085', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-085', 85, 'Upon seeing someone in trial or tribulation', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.085.part.001', 'dua.hisn.085', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.085.part.001.segment.001', 'dua.hisn.085.part.001', 1, 'arabic', 'ar', 'Arab', 'الْحَمْـدُ للهِ الّذي عافاني مِمّا ابْتَـلاكَ بِهِ، وَفَضَّلَـني عَلى كَثيـرٍ مِمَّنْ خَلَـقَ تَفْضـيلا.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.085.part.001.segment.002', 'dua.hisn.085.part.001', 2, 'transliteration', 'ar-Latn', 'Latn', 'Alhamdu lillahil-lathee AAafanee mimmab-talaka bih, wafaddalanee AAala katheerin mimman khalaqa tafdeela.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.085.part.001.segment.003', 'dua.hisn.085.part.001', 3, 'translation', 'en', 'Latn', '‘All praise is for Allah Who saved me from that which He tested you with and Who most certainly favoured me over much of His creation.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.086', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-086', 86, 'At a sitting or gathering', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.086.part.001', 'dua.hisn.086', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.086.part.001.segment.001', 'dua.hisn.086.part.001', 1, 'comment', 'en', 'Latn', 'Ibn AAumar said: It would be counted that the Messenger of Allah would say one hundred times at any one sitting before getting up:');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.086.part.001.segment.002', 'dua.hisn.086.part.001', 2, 'arabic', 'ar', 'Arab', 'رَبِّ اغْفِـرْ لي، وَتُبْ عَلَـيَّ، إِنَّكَ أَنْـتَ التَّـوّابُ الغَـفور.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.086.part.001.segment.003', 'dua.hisn.086.part.001', 3, 'transliteration', 'ar-Latn', 'Latn', 'Rabbigh-fir lee watub AAalay, innaka antat-tawwabul-ghafoor.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.086.part.001.segment.004', 'dua.hisn.086.part.001', 4, 'translation', 'en', 'Latn', '‘O my Lord, forgive me and turn towards me (to accept my repentance). Verily You are The Oft-Returning. The Oft-Forgiving.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.087', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-087', 87, 'At a sitting or gathering', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.087.part.001', 'dua.hisn.087', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.087.part.001.segment.001', 'dua.hisn.087.part.001', 1, 'comment', 'en', 'Latn', 'Ibn AAumar said: It would be counted that the Messenger of Allah would say one hundred times at any one sitting before getting up:');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.087.part.001.segment.002', 'dua.hisn.087.part.001', 2, 'arabic', 'ar', 'Arab', 'رَبِّ اغْفِـرْ لي، وَتُبْ عَلَـيَّ، إِنَّكَ أَنْـتَ التَّـوّابُ الغَـفور.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.087.part.001.segment.003', 'dua.hisn.087.part.001', 3, 'transliteration', 'ar-Latn', 'Latn', 'Rabbigh-fir lee watub AAalay, innaka antat-tawwabul-ghafoor.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.087.part.001.segment.004', 'dua.hisn.087.part.001', 4, 'translation', 'en', 'Latn', '‘O my Lord, forgive me and turn towards me (to accept my repentance). Verily You are The Oft-Returning. The Oft-Forgiving.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.088', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-088', 88, 'For the expiation of sins, said at the conclusion of a sitting or gathering', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.088.part.001', 'dua.hisn.088', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.088.part.001.segment.001', 'dua.hisn.088.part.001', 1, 'arabic', 'ar', 'Arab', 'سُبْحـانَكَ اللّهُـمَّ وَبِحَمدِك، أَشْهَـدُ أَنْ لا إِلهَ إِلاّ أَنْتَ أَسْتَغْفِرُكَ وَأَتوبُ إِلَـيْك.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.088.part.001.segment.002', 'dua.hisn.088.part.001', 2, 'transliteration', 'ar-Latn', 'Latn', 'Subhanakal-lahumma wabihamdik, ashhadu an la ilaha illa ant, astaghfiruka wa-atoobu ilayk.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.088.part.001.segment.003', 'dua.hisn.088.part.001', 3, 'translation', 'en', 'Latn', '‘How perfect You are O Allah, and I praise You.  I bear witness that None has the right to be worshipped except You.  I seek Your forgiveness and turn to You in repentance.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.088.part.002', 'dua.hisn.088', 2);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.088.part.002.segment.001', 'dua.hisn.088.part.002', 1, 'comment', 'en', 'Latn', 'Cont.79. Supplication for concluding all sittings');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.088.part.002.segment.002', 'dua.hisn.088.part.002', 2, 'comment', 'en', 'Latn', 'AAaishah رضي الله عنها  said: Whenever The Messenger of Allah would betake a seat, read Quran or pray, he would always conclude it with certain words, I (i.e. AAaishah) said: O Messenger of Allah, I have noticed that whenever you betake a seat, read Quran or pray, you always conclude it with these words. He said: Yes, whoever speaks good, it (i.e. the supplication) will be a seal for that goodness and whoever speaks ill, it will be an atonement for him.’');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.088.part.002.segment.003', 'dua.hisn.088.part.002', 3, 'arabic', 'ar', 'Arab', 'سُبْحـانَكَ وَبِحَمدِك، لا إِلهَ إِلاّ أَنْتَ أَسْتَغْفِرُكَ وَأَتوبُ إِلَـيْك.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.088.part.002.segment.004', 'dua.hisn.088.part.002', 4, 'transliteration', 'ar-Latn', 'Latn', 'Subhanaka wabihamdik, la ilaha illa anta astaghfiruka wa-atoobu ilayk.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.088.part.002.segment.005', 'dua.hisn.088.part.002', 5, 'translation', 'en', 'Latn', '‘How perfect You are and I praise You.  None has the right to be worshipped except You, I seek Your forgiveness and turn in repentance to You.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.089', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-089', 89, 'Returning a supplication of forgiveness', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.089.part.001', 'dua.hisn.089', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.089.part.001.segment.001', 'dua.hisn.089.part.001', 1, 'comment', 'en', 'Latn', '‘AAabdullah Ibn Sarjis  said: ‘I went to see the Prophet (saws) and ate from his food and then said to him:');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.089.part.001.segment.002', 'dua.hisn.089.part.001', 2, 'arabic', 'ar', 'Arab', 'غَفَـرَ اللهُ لَكَ يا رَسـولَ الله.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.089.part.001.segment.003', 'dua.hisn.089.part.001', 3, 'transliteration', 'ar-Latn', 'Latn', 'Ghafaral-lahu laka ya rasoolal-lah.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.089.part.001.segment.004', 'dua.hisn.089.part.001', 4, 'translation', 'en', 'Latn', '‘May Allah forgive you, O Messenger of Allah.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.089.part.002', 'dua.hisn.089', 2);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.089.part.002.segment.001', 'dua.hisn.089.part.002', 1, 'comment', 'en', 'Latn', 'he replied:');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.089.part.002.segment.002', 'dua.hisn.089.part.002', 2, 'arabic', 'ar', 'Arab', 'وَلَكَ.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.089.part.002.segment.003', 'dua.hisn.089.part.002', 3, 'transliteration', 'ar-Latn', 'Latn', 'wa-lak');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.089.part.002.segment.004', 'dua.hisn.089.part.002', 4, 'translation', 'en', 'Latn', '‘and you.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.090', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-090', 90, 'To one who does you a favour', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.090.part.001', 'dua.hisn.090', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.090.part.001.segment.001', 'dua.hisn.090.part.001', 1, 'comment', 'en', 'Latn', '‘If someone does you a favour and you say:');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.090.part.001.segment.002', 'dua.hisn.090.part.001', 2, 'arabic', 'ar', 'Arab', 'جَزاكَ اللهُ خَـيْراً.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.090.part.001.segment.003', 'dua.hisn.090.part.001', 3, 'transliteration', 'ar-Latn', 'Latn', 'Jazakal-lahu khayran.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.090.part.001.segment.004', 'dua.hisn.090.part.001', 4, 'translation', 'en', 'Latn', '‘May Allah reward you with goodness.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.090.part.002', 'dua.hisn.090', 2);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.090.part.002.segment.001', 'dua.hisn.090.part.002', 1, 'comment', 'en', 'Latn', 'then you have indeed excelled in praising him.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.091', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-091', 91, 'Protection from the Dajjal', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.091.part.001', 'dua.hisn.091', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.091.part.001.segment.001', 'dua.hisn.091.part.001', 1, 'comment', 'en', 'Latn', 'Dajjal: among the great signs of the last hour and the greatest trials to befall mankind, which every Prophet (saws) has warned about.  Most of mankind will folow him. He will appear from Asbahan, Iran at the time when Muslims will conquer Constantinople.  He will be given special powers and will make the truth seem false and vice versa. He will claim to be righteous and then he will claim Prophet (saws)-hood and finally, divinity. From his features is that he will be blind in his right eye which is a definite proof that contradicts his claim to be Allah as it is a sign of imperfection.  The word Kafir will be written between his eyes which every believer, literate or illiterate will recognise.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.091.part.001.segment.002', 'dua.hisn.091.part.001', 2, 'comment', 'en', 'Latn', 'One should also seek refuge with Allah from the tribulations of the Dajjal after the last tashahhud in prayer.(Refer to supplications #55 & #56)');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.091.part.001.segment.003', 'dua.hisn.091.part.001', 3, 'translation', 'en', 'Latn', '‘Whoever memorises the first ten verses of soorat Al-Kahf will be protected from Dajjal.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.092', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-092', 92, 'To one who pronounces his love for you, for Allah’s sake', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.092.part.001', 'dua.hisn.092', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.092.part.001.segment.001', 'dua.hisn.092.part.001', 1, 'arabic', 'ar', 'Arab', 'أَحَبَّـكَ الّذي أَحْبَبْـتَني لَه.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.092.part.001.segment.002', 'dua.hisn.092.part.001', 2, 'transliteration', 'ar-Latn', 'Latn', 'Ahabbakal-lathee ahbabtanee lah.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.092.part.001.segment.003', 'dua.hisn.092.part.001', 3, 'translation', 'en', 'Latn', '‘May He, for whom you have loved me, love you.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.093', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-093', 93, 'To one who has offered you some of his wealth', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.093.part.001', 'dua.hisn.093', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.093.part.001.segment.001', 'dua.hisn.093.part.001', 1, 'arabic', 'ar', 'Arab', 'بارَكَ اللهُ لَكَ في أَهْلِكَ وَمالِك.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.093.part.001.segment.002', 'dua.hisn.093.part.001', 2, 'transliteration', 'ar-Latn', 'Latn', 'Barakal-lahu laka fee ahlika wamalik.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.093.part.001.segment.003', 'dua.hisn.093.part.001', 3, 'translation', 'en', 'Latn', '‘May Allah bless for you, your family and wealth.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.094', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-094', 94, 'To the debtor when his debt is settled', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.094.part.001', 'dua.hisn.094', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.094.part.001.segment.001', 'dua.hisn.094.part.001', 1, 'arabic', 'ar', 'Arab', 'بارَكَ اللهُ لَكَ في أَهْلِكَ وَمالِك، إِنَّما جَـزاءُ السَّلَفِ الْحَمْدُ والأَداء.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.094.part.001.segment.002', 'dua.hisn.094.part.001', 2, 'transliteration', 'ar-Latn', 'Latn', 'Barakal-lahu laka fee ahlika wamalik, innama jaza-os-salafil-hamdu wal-ada/.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.094.part.001.segment.003', 'dua.hisn.094.part.001', 3, 'translation', 'en', 'Latn', '‘May Allah bless for you, your family and wealth. Surely commendation and payment are the reward for a loan.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.095', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-095', 95, 'For fear of shirk', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.095.part.001', 'dua.hisn.095', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.095.part.001.segment.001', 'dua.hisn.095.part.001', 1, 'arabic', 'ar', 'Arab', 'اللّهُـمَّ  إِنّـي أَعـوذُبِكَ أَنْ أُشْـرِكَ بِكَ وَأَنا أَعْـلَمْ، وَأَسْتَـغْفِرُكَ لِما لا أَعْـلَم.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.095.part.001.segment.002', 'dua.hisn.095.part.001', 2, 'transliteration', 'ar-Latn', 'Latn', 'Allahumma innee aAAoothu bika an oshrika bika wa-ana aAAlam, wa-astaghfiruka lima la aAAlam.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.095.part.001.segment.003', 'dua.hisn.095.part.001', 3, 'translation', 'en', 'Latn', '‘O Allah, I take refuge in You lest I should commit shirk with You knowingly and I seek Your forgiveness for what I do unknowingly.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.096', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-096', 96, 'Returning a supplication after having bestowed a gift or charity upon someone', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.096.part.001', 'dua.hisn.096', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.096.part.001.segment.001', 'dua.hisn.096.part.001', 1, 'arabic', 'ar', 'Arab', 'وَفيكَ بارَكَ الله');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.096.part.001.segment.002', 'dua.hisn.096.part.001', 2, 'transliteration', 'ar-Latn', 'Latn', 'Wa fika barakallah');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.096.part.001.segment.003', 'dua.hisn.096.part.001', 3, 'translation', 'en', 'Latn', 'May Allah bless you all.');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.097', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-097', 97, 'Forbiddance of ascribing things to omens', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.097.part.001', 'dua.hisn.097', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.097.part.001.segment.001', 'dua.hisn.097.part.001', 1, 'comment', 'en', 'Latn', 'This supplication is used whenever one initially thinks a casual event or occurrence to foretell good or evil, using it as a basis to determine which action he should undertake, but he then denounces such a link, relies on Allah and then says this supplication as an expiation for this act, since it falls under the category of shirk.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.097.part.001.segment.002', 'dua.hisn.097.part.001', 2, 'arabic', 'ar', 'Arab', 'اللّهُـمَّ لا طَيْـرَ إِلاّ طَيْـرُك، وَلا خَـيْرَ إِلاّ خَـيْرُك، وَلا إِلهَ غَيْـرُك.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.097.part.001.segment.003', 'dua.hisn.097.part.001', 3, 'transliteration', 'ar-Latn', 'Latn', 'Allahumma la tayra illa tayruk, wala khayra illa khayruk, wala ilaha ghayruk.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.097.part.001.segment.004', 'dua.hisn.097.part.001', 4, 'translation', 'en', 'Latn', '‘O Allah, there is no omen but there is reliance on You, there is no good except Your good and none has the right to be worshipped except You.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.098', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-098', 98, 'When mounting an animal or any means of transport', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.098.part.001', 'dua.hisn.098', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.098.part.001.segment.001', 'dua.hisn.098.part.001', 1, 'arabic', 'ar', 'Arab', 'بِسْـمِ اللهِ وَالْحَمْـدُ لله، سُـبْحانَ الّذي سَخَّـرَ لَنا هذا وَما كُنّا لَهُ مُقْـرِنين، وَإِنّا إِلى رَبِّنا لَمُنـقَلِبون، الحَمْـدُ لله، الحَمْـدُ لله، الحَمْـدُ لله، اللهُ أكْـبَر، اللهُ أكْـبَر، اللهُ أكْـبَر، سُـبْحانَكَ اللّهُـمَّ  إِنّي ظَلَـمْتُ نَفْسي فَاغْـفِرْ لي، فَإِنَّهُ لا يَغْفِـرُ الذُّنوبَ إِلاّ أَنْـت.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.098.part.001.segment.002', 'dua.hisn.098.part.001', 2, 'transliteration', 'ar-Latn', 'Latn', 'Bismil-lah, walhamdu lillah, subhanal-lathee sakhkhara lana hatha wama kunna lahu muqrineen, wainna ila rabbina lamunqaliboon, alhamdu lillah, alhamdu lillah, alhamdu lillah, Allahu akbar, Allahu akbar, Allahu akbar, subhanakal-lahumma innee thalamtu nafsee faghfir lee fainnahu la yaghfiruth-thunooba illa ant.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.098.part.001.segment.003', 'dua.hisn.098.part.001', 3, 'translation', 'en', 'Latn', '‘In the name of Allah and all praise is for Allah.  How perfect He is, the One Who has placed this (transport) at our service and we ourselves would not have been capable of that, and to our Lord is our final destiny.  All praise is for Allah, All praise is for Allah, All praise is for Allah,  Allah is the greatest, Allah is the greatest, Allah is the greatest. How perfect You are, O Allah, verily I have wronged my soul, so forgive me, for surely none can forgive sins except You.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.099', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-099', 99, 'For travel', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.099.part.001', 'dua.hisn.099', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.099.part.001.segment.001', 'dua.hisn.099.part.001', 1, 'arabic', 'ar', 'Arab', 'اللهُ أكبَر، اللهُ أكبَر، اللهُ أكبَر، سُـبْحانَ الَّذي سَخَّـرَ لَنا هذا وَما  كُنّا لَهُ مُقْـرِنين،  وَإِنّا إِلى رَبِّنـا لَمُنْقَـلِبون، اللّهُـمَّ إِنّا نَسْـأَلُكَ في سَفَـرِنا هذا البِـرَّ وَالتَّـقْوى، وَمِنَ الْعَمَـلِ ما تَـرْضى، اللّهُـمَّ هَوِّنْ عَلَـينا سَفَرَنا هذا وَاطْوِ عَنّا بُعْـدَه، اللّهُـمَّ أَنْـتَ الصّـاحِبُ في السَّـفَر، وَالْخَلـيفَةُ في الأهـلِ، اللّهُـمَّ  إِنّـي أَعـوذُبِكَ مِنْ وَعْـثاءِ السَّـفَر، وَكَآبَةِ الْمَنْـظَر، وَسوءِ الْمُنْـقَلَبِ في المـالِ وَالأَهْـل.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.099.part.001.segment.002', 'dua.hisn.099.part.001', 2, 'transliteration', 'ar-Latn', 'Latn', 'Allahu akbar, Allahu akbar, Allahu akbar, subhanal-lathee sakhkhara lana hatha wama kunna lahu muqrineen, wa-inna ila rabbina lamunqaliboon, allahumma inna nas-aluka fee safarina hatha albirra wattaqwa, waminal-AAamali ma tarda, allahumma hawwin AAalayna safarana hatha, watwi AAanna buAAdah, allahumma antas-sahibu fis-safar, walkhaleefatu fil-ahl, allahumma innee aAAoothu bika min waAAtha-is-safar, waka-abatil-manthar, wasoo-il-munqalabi fil-mali wal-ahl.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.099.part.001.segment.003', 'dua.hisn.099.part.001', 3, 'translation', 'en', 'Latn', '‘Allah is the greatest, Allah is the greatest, Allah is the greatest, How perfect He is, The One Who has placed this (transport) at our service, and we ourselves would not have been capable of that, and to our Lord is our final destiny.  O Allah, we ask You for birr and taqwa in this journey of ours, and we ask You for deeds which please You.  O Allah, facilitate our journey and let us cover it’s distance quickly.  O Allah, You are The Companion on the journey and The Successor over the family, O Allah, I take refuge with You from the difficulties of travel, from having a change of hearts and being in a bad predicament, and I take refuge in You from an ill fated outcome with wealth and family.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.099.part.002', 'dua.hisn.099', 2);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.099.part.002.segment.001', 'dua.hisn.099.part.002', 1, 'comment', 'en', 'Latn', 'birr and taqwa: two comprehensive terms which individually, refer to all good actions and obedience i.e. performing the commanded actions and avoiding the prohibited actions.  When combined together, birr refers to doing those actions which have been commanded and taqwa refers to avoiding those actions which have been prohibited.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.099.part.002.segment.002', 'dua.hisn.099.part.002', 2, 'comment', 'en', 'Latn', 'A successor: one who succeeds another due to the latter’s absence or death.  This is the correct meaning of the word khaleefah; thus, it is incorrect to believe that Adam is the khaleefah (vicegerent, as is commonly translated) of Allah on earth because Allah is never absent, and will never die.  This supplication proves the correct understanding of this term and shows that Allah succeeds us and guards whom we leave behind when we die or are absent.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.099.part.002.segment.003', 'dua.hisn.099.part.002', 3, 'comment', 'en', 'Latn', 'upon returning the same supplication is recited with the following addition:');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.099.part.002.segment.004', 'dua.hisn.099.part.002', 4, 'arabic', 'ar', 'Arab', 'آيِبـونَ تائِبـونَ عابِـدونَ لِرَبِّـنا حـامِـدون.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.099.part.002.segment.005', 'dua.hisn.099.part.002', 5, 'transliteration', 'ar-Latn', 'Latn', 'Ayiboona, ta-iboona, AAabidoona, lirabbina hamidoon.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.099.part.002.segment.006', 'dua.hisn.099.part.002', 6, 'translation', 'en', 'Latn', '‘We return, repent, worship and praise our Lord.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.100', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-100', 100, 'Upon entering a town or village', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.100.part.001', 'dua.hisn.100', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.100.part.001.segment.001', 'dua.hisn.100.part.001', 1, 'arabic', 'ar', 'Arab', 'أللّـهُمَّ رَبَّ السَّـمواتِ السّـبْعِ وَما أَظْلَلَـن، وَرَبَّ الأَراضيـنَ السّـبْعِ وَما أقْلَلْـن، وَرَبَّ الشَّيـاطينِ وَما أَضْلَلْـن، وَرَبَّ الرِّياحِ وَما ذَرَيْـن، أَسْـأَلُـكَ خَيْـرَ هذهِ الْقَـرْيَةِ وَخَيْـرَ أَهْلِـها، وَخَيْـرَ ما فيها، وَأَعـوذُ بِكَ مِنْ شَـرِّها وَشَـرِّ أَهْلِـها، وَشَـرِّ ما فيها.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.100.part.001.segment.002', 'dua.hisn.100.part.001', 2, 'transliteration', 'ar-Latn', 'Latn', 'Allahumma rabbas-samawatis-sabAAi wama athlaln, warabbal-aradeenas-sabAAi wama aqlaln, warabbash-shayateeni wama adlaln, warabbar-riyahi wama tharayn, as-aluka khayra hathihil-qaryah, wakhayra ahlilha wakhayra ma feeha, wa-aAAoothu bika min sharriha washarri ahliha, washarri ma feeha.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.100.part.001.segment.003', 'dua.hisn.100.part.001', 3, 'translation', 'en', 'Latn', '‘O Allah, Lord of the seven heavens and all that they envelop, Lord of the seven earths and all that they carry, Lord of the devils and all whom they misguide, Lord of the winds and all whom they whisk away. I ask You for the goodness of this village, the goodness of its inhabitants and for all the goodness found within it and I take refuge with You from the evil of this village, the evil of its inhabitants and from all the evil found within it.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.101', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-101', 101, 'When entering the market', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.101.part.001', 'dua.hisn.101', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.101.part.001.segment.001', 'dua.hisn.101.part.001', 1, 'arabic', 'ar', 'Arab', 'لا إلهَ إلاّ اللّه وحدَهُ لا شريكَ لهُ، لهُ المُلْـكُ ولهُ الحَمْـد، يُحْيـي وَيُميـتُ  وَهُوَ حَيٌّ لا يَمـوت، بِيَـدِهِ الْخَـيْرُ وَهوَ على كلّ شيءٍ قدير.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.101.part.001.segment.002', 'dua.hisn.101.part.001', 2, 'transliteration', 'ar-Latn', 'Latn', 'La ilaha illal-lah,  wahdahu la shareeka lah, lahul-mulku walahul-hamd, yuhyee wayumeetu wahuwa hayyun la yamoot, biyadihil-khayru wahuwa  AAala kulli shayin qadeer.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.101.part.001.segment.003', 'dua.hisn.101.part.001', 3, 'translation', 'en', 'Latn', '‘None has the right to be worshipped except Allah, alone, without partner, to Him belongs all sovereignty and praise.  He gives life and causes death, and He is living and does not die.  In His hand is all good and He is over all things, omnipotent.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.102', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-102', 102, 'When the mounted animal (or mean of transport) stumbles', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.102.part.001', 'dua.hisn.102', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.102.part.001.segment.001', 'dua.hisn.102.part.001', 1, 'arabic', 'ar', 'Arab', 'بِسْـمِ اللهِ.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.102.part.001.segment.002', 'dua.hisn.102.part.001', 2, 'transliteration', 'ar-Latn', 'Latn', 'Bismil-lah.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.102.part.001.segment.003', 'dua.hisn.102.part.001', 3, 'translation', 'en', 'Latn', '‘In the name of Allah.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.103', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-103', 103, 'Supplication of the traveller for the resident', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.103.part.001', 'dua.hisn.103', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.103.part.001.segment.001', 'dua.hisn.103.part.001', 1, 'arabic', 'ar', 'Arab', 'أَسْتَـوْدِعُكُـمُ اللَّهَ الَّذي لا تَضـيعُ وَدائِعُـه.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.103.part.001.segment.002', 'dua.hisn.103.part.001', 2, 'transliteration', 'ar-Latn', 'Latn', 'AstawdiAAukumul-lah, allathee la tadeeAAu wada-iAAuh.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.103.part.001.segment.003', 'dua.hisn.103.part.001', 3, 'translation', 'en', 'Latn', '‘I place you in the trust of Allah, whose trust is never misplaced.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.104', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-104', 104, 'Supplication of the resident for the traveller', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.104.part.001', 'dua.hisn.104', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.104.part.001.segment.001', 'dua.hisn.104.part.001', 1, 'arabic', 'ar', 'Arab', 'أَسْتَـوْدِعُ اللَّهَ ديـنَكَ وَأَمانَتَـكَ، وَخَـواتيـمَ عَمَـلِك.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.104.part.001.segment.002', 'dua.hisn.104.part.001', 2, 'transliteration', 'ar-Latn', 'Latn', 'AstawdiAAul-laha deenak, wa-amanatak, wakhawateema AAamalik.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.104.part.001.segment.003', 'dua.hisn.104.part.001', 3, 'translation', 'en', 'Latn', '‘I place your religion, your faithfulness and the ends of your deeds in the trust of Allah.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.104.part.002', 'dua.hisn.104', 2);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.104.part.002.segment.001', 'dua.hisn.104.part.002', 1, 'arabic', 'ar', 'Arab', 'زَوَّدَكَ اللَّهُ التقْوى، وَغَفَـرَ ذَنْـبَكَ، وَيَسَّـرَ لَكَ الخَـيْرَ حَيْـثُما كُنْـت.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.104.part.002.segment.002', 'dua.hisn.104.part.002', 2, 'transliteration', 'ar-Latn', 'Latn', 'Zawwadakal-lahut-taqwa, waghafara thanbak, wayassara lakal-khayra haythuma kunt.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.104.part.002.segment.003', 'dua.hisn.104.part.002', 3, 'translation', 'en', 'Latn', '‘May Allah endow you with taqwa, forgive your sins and facilitate all good for you, wherever you be.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.104.part.003', 'dua.hisn.104', 3);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.104.part.003.segment.001', 'dua.hisn.104.part.003', 1, 'comment', 'en', 'Latn', 'taqwa: a comprehensive term which refers to all good actions and obedience i.e. performing the commanded actions and avoiding the prohibited actions.');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.105', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-105', 105, 'Remembrance while ascending or descending', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.105.part.001', 'dua.hisn.105', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.105.part.001.segment.001', 'dua.hisn.105.part.001', 1, 'comment', 'en', 'Latn', 'Jabir said: While ascending, we would say:');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.105.part.001.segment.002', 'dua.hisn.105.part.001', 2, 'arabic', 'ar', 'Arab', 'اللهُ أَكْـبَر.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.105.part.001.segment.003', 'dua.hisn.105.part.001', 3, 'transliteration', 'ar-Latn', 'Latn', 'Allahu akbar.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.105.part.001.segment.004', 'dua.hisn.105.part.001', 4, 'translation', 'en', 'Latn', '‘Allah is the greatest.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.105.part.002', 'dua.hisn.105', 2);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.105.part.002.segment.001', 'dua.hisn.105.part.002', 1, 'comment', 'en', 'Latn', 'and when descending, we would say:');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.105.part.002.segment.002', 'dua.hisn.105.part.002', 2, 'arabic', 'ar', 'Arab', 'سُبْـحانَ الله.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.105.part.002.segment.003', 'dua.hisn.105.part.002', 3, 'transliteration', 'ar-Latn', 'Latn', 'Subhanal-lah.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.105.part.002.segment.004', 'dua.hisn.105.part.002', 4, 'translation', 'en', 'Latn', '‘How perfect Allah is.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.106', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-106', 106, 'Prayer of the traveller as dawn approaches', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.106.part.001', 'dua.hisn.106', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.106.part.001.segment.001', 'dua.hisn.106.part.001', 1, 'arabic', 'ar', 'Arab', 'سَمِـعَ سـامِعُ بِحَمْـدِ اللهِ وَحُسْـنِ بَلائِـهِ عَلَيْـنا. رَبَّنـا صـاحِبْـنا وَأَفْـضِل عَلَيْـنا عائِذاً باللهِ مِنَ النّـار.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.106.part.001.segment.002', 'dua.hisn.106.part.001', 2, 'transliteration', 'ar-Latn', 'Latn', 'SamiAAa samiAAun bihamdil-lahi wahusni bala-ihi AAalayna. Rabbana sahibna wa-afdil AAalayna AAa-ithan billahi minan-nar.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.106.part.001.segment.003', 'dua.hisn.106.part.001', 3, 'translation', 'en', 'Latn', '‘May a witness, be witness to our praise of Allah for His favours and bounties upon us.  Our Lord, protect us, show favour on us and deliver us from every evil.  I take refuge in Allah from the fire.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.107', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-107', 107, 'Stopping or lodging somewhere', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.107.part.001', 'dua.hisn.107', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.107.part.001.segment.001', 'dua.hisn.107.part.001', 1, 'arabic', 'ar', 'Arab', 'أَعـوذُ بِكَلِـماتِ اللّهِ التّـامّاتِ مِنْ شَـرِّ ما خَلَـق.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.107.part.001.segment.002', 'dua.hisn.107.part.001', 2, 'transliteration', 'ar-Latn', 'Latn', 'aAAoothu bikalimatil-lahit-tammati min sharri ma khalaq.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.107.part.001.segment.003', 'dua.hisn.107.part.001', 3, 'translation', 'en', 'Latn', '‘I take refuge in Allah’s perfect words from the evil that He has created.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.108', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-108', 108, 'While returning from travel', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.108.part.001', 'dua.hisn.108', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.108.part.001.segment.001', 'dua.hisn.108.part.001', 1, 'comment', 'en', 'Latn', 'Ibn AAumar reported that the Messenger of Allah on return from a battle or from performing the pilgrimage would say at every high point:');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.108.part.001.segment.002', 'dua.hisn.108.part.001', 2, 'arabic', 'ar', 'Arab', 'ا للهُ أَكْـبَر، ا للهُ أَكْـبَر، ا للهُ أَكْـبَر.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.108.part.001.segment.003', 'dua.hisn.108.part.001', 3, 'transliteration', 'ar-Latn', 'Latn', 'Allahu akbar, Allahu akbar, Allahu akbar.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.108.part.001.segment.004', 'dua.hisn.108.part.001', 4, 'translation', 'en', 'Latn', '‘Allah is the greatest, Allah is the greatest, Allah is the greatest.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.108.part.002', 'dua.hisn.108', 2);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.108.part.002.segment.001', 'dua.hisn.108.part.002', 1, 'comment', 'en', 'Latn', 'and then he would say:');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.108.part.002.segment.002', 'dua.hisn.108.part.002', 2, 'arabic', 'ar', 'Arab', 'لا إلهَ إلاّ اللّهُ وَحْـدَهُ لا شريكَ لهُ، لهُ الملكُ ولهُ الحَمْد، وهُوَ على كُلّ شَيءٍ قَـدير، آيِبـونَ تائِبـونَ عابِـدونَ لِرَبِّـنا حـامِـدون، صَدَقَ اللهُ وَعْـدَه، وَنَصَـرَ عَبْـدَه، وَهَزَمَ الأَحْـزابَ وَحْـدَه.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.108.part.002.segment.003', 'dua.hisn.108.part.002', 3, 'transliteration', 'ar-Latn', 'Latn', 'La ilaha illal-lahu wahdahu la shareeka lah, lahul-mulku walahul-hamd, wahuwa AAala kulli shay-in qadeer, ayiboona ta-iboon, AAabidoon, lirabbina hamidoon, sadaqal-lahu waAAdah, wanasara AAabdah, wahazamal-ahzaba wahdah.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.108.part.002.segment.004', 'dua.hisn.108.part.002', 4, 'translation', 'en', 'Latn', '‘None has the right to be worshipped except Allah, alone, without partner.  To Him belongs all sovereignty and praise, and He is over all things omnipotent.  We return, repent, worship and praise our Lord.  Allah fulfilled His promise, aided His Servant, and single-handedly defeated the allies.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.109', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-109', 109, 'What to say upon receiving pleasing or displeasing news', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.109.part.001', 'dua.hisn.109', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.109.part.001.segment.001', 'dua.hisn.109.part.001', 1, 'comment', 'en', 'Latn', 'When he used to receive pleasant news');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.109.part.001.segment.002', 'dua.hisn.109.part.001', 2, 'comment', 'en', 'Latn', 'he would say:');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.109.part.001.segment.003', 'dua.hisn.109.part.001', 3, 'arabic', 'ar', 'Arab', 'الْحَمْـدُ للهِ الَّذي بِنِـعْمَتِهِ تَتِـمُّ الصّـالِحات.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.109.part.001.segment.004', 'dua.hisn.109.part.001', 4, 'transliteration', 'ar-Latn', 'Latn', 'Alhamdu lillahil-lathee biniAAmatihi tatimmus-salihat.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.109.part.001.segment.005', 'dua.hisn.109.part.001', 5, 'translation', 'en', 'Latn', '‘All Praise is for Allah by whose favour good works are accomplished.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.109.part.002', 'dua.hisn.109', 2);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.109.part.002.segment.001', 'dua.hisn.109.part.002', 1, 'comment', 'en', 'Latn', 'and upon receiving displeasing news');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.109.part.002.segment.002', 'dua.hisn.109.part.002', 2, 'comment', 'en', 'Latn', 'he would say:');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.109.part.002.segment.003', 'dua.hisn.109.part.002', 3, 'arabic', 'ar', 'Arab', 'الْحَمْـدُ للهِ على كُـلِّ حال.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.109.part.002.segment.004', 'dua.hisn.109.part.002', 4, 'transliteration', 'ar-Latn', 'Latn', 'Alhamdu lillahi AAala kulli hal.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.109.part.002.segment.005', 'dua.hisn.109.part.002', 5, 'translation', 'en', 'Latn', '‘All Praise is for Allah in all circumstances.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.110', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-110', 110, 'Excellence of sending prayers upon the Prophet (saws)', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.110.part.001', 'dua.hisn.110', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.110.part.001.segment.001', 'dua.hisn.110.part.001', 1, 'comment', 'en', 'Latn', 'The Prophet (saws) said: ‘Whoever sends a prayer upon me, Allah sends ten upon him.’');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.110.part.001.segment.002', 'dua.hisn.110.part.001', 2, 'comment', 'en', 'Latn', 'He also said: ‘Do not take my grave as a place of habitual ceremony.  Send prayers upon me, for verily your prayers reach me wherever you are.’');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.110.part.001.segment.003', 'dua.hisn.110.part.001', 3, 'comment', 'en', 'Latn', 'He also said: ‘A miser is one whom when I am mentioned to him,  fails to send prayers upon me.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.111', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-111', 111, 'Excellence of spreading the Islamic greeting', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.111.part.001', 'dua.hisn.111', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.111.part.001.segment.001', 'dua.hisn.111.part.001', 1, 'comment', 'en', 'Latn', 'The Messenger of Allah said: ‘You shall not enter paradise until you believe, and you shall not believe until you love one another. Shall I not inform you of something, if you were to act upon it, you will indeed achieve mutual love for one another?  Spread the greeting amongst yourselves.’');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.111.part.001.segment.002', 'dua.hisn.111.part.001', 2, 'comment', 'en', 'Latn', 'AAammar said: ‘Three characteristics, whoever combines them, has completed his faith: to be just, to spread greetings to all people and to spend (charitably) out of the little you have.’');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.111.part.001.segment.003', 'dua.hisn.111.part.001', 3, 'translation', 'en', 'Latn', '‘AAabdullah Ibn AAamr reported that a man asked the Prophet (saws): ‘Which Islam is the best?’.  He replied: Feed (the poor), and greet those whom you know as well as those whom you do not.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.112', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-112', 112, 'Returning a greeting to a misbeliever', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.112.part.001', 'dua.hisn.112', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.112.part.001.segment.001', 'dua.hisn.112.part.001', 1, 'comment', 'en', 'Latn', '‘When the people of the Book greet you, reply by saying:');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.112.part.001.segment.002', 'dua.hisn.112.part.001', 2, 'arabic', 'ar', 'Arab', 'وَعَلَـيكُم.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.112.part.001.segment.003', 'dua.hisn.112.part.001', 3, 'transliteration', 'ar-Latn', 'Latn', 'WaAAalaykum.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.112.part.001.segment.004', 'dua.hisn.112.part.001', 4, 'translation', 'en', 'Latn', '‘And upon you.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.113', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-113', 113, 'Upon hearing a rooster crow or the braying of an ass', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.113.part.001', 'dua.hisn.113', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.113.part.001.segment.001', 'dua.hisn.113.part.001', 1, 'translation', 'en', 'Latn', '‘If you hear the crow of a rooster, ask Allah for his bounty for it has seen an angel and if you hear the braying of an ass, seek refuge in Allah for it has seen a devil.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.114', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-114', 114, 'Upon hearing the barking of dogs at night', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.114.part.001', 'dua.hisn.114', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.114.part.001.segment.001', 'dua.hisn.114.part.001', 1, 'translation', 'en', 'Latn', '‘If you hear the barking of dogs or the braying of asses at night, seek refuge in Allah for they see what you do not.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.115', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-115', 115, 'For one you have insulted', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.115.part.001', 'dua.hisn.115', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.115.part.001.segment.001', 'dua.hisn.115.part.001', 1, 'arabic', 'ar', 'Arab', 'اللهُمَّ فأَيُّمَا مُؤْمِنٍ سَبَبْتُهُ فَاجْعَلْ ذَلِكَ لهُ قُرْبةً إليكَ يَوْمَ القِيَامةِ.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.115.part.001.segment.002', 'dua.hisn.115.part.001', 2, 'transliteration', 'ar-Latn', 'Latn', 'Allahumma fa-ayyuma mu/minin sababtuhu fajAAal thalika lahu qurbatan ilayka yawmal-qiyamah.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.115.part.001.segment.003', 'dua.hisn.115.part.001', 3, 'translation', 'en', 'Latn', '‘O Allah, to any believer whom I have insulted, let that be cause to draw him near to You on the Day of Resurrection.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.116', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-116', 116, 'The etiquette of praising a fellow Muslim', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.116.part.001', 'dua.hisn.116', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.116.part.001.segment.001', 'dua.hisn.116.part.001', 1, 'comment', 'en', 'Latn', 'He said (saws): ‘If anyone of you is impelled to praise his brother, then he should say: ‘I deem so-and-so to beand Allah is his reckonerand I don’t praise anyone, putting it (i.e. my praising) forward, in front of Allah’s commendation, however I assume him so and so’if he knows that of him.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.117', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-117', 117, 'For the one that have been praised', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.117.part.001', 'dua.hisn.117', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.117.part.001.segment.001', 'dua.hisn.117.part.001', 1, 'arabic', 'ar', 'Arab', 'اللَّهُمَّ لاَ تُؤَاخِذْنِي بِمَا يَقُولُونَ, وَ اغْفِرْ لِي مَا لاَ يَعْلَمُونَ وَ اجْعَلْنِي خَيْرًا مِمَّا يَظُنُّون');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.117.part.001.segment.002', 'dua.hisn.117.part.001', 2, 'transliteration', 'ar-Latn', 'Latn', 'Allahumma la tu''akhidhni bi-ma yaquluna, wa ghfir li ma la yaclamun, wa jcalni khayran mimma yazunnun.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.117.part.001.segment.003', 'dua.hisn.117.part.001', 3, 'translation', 'en', 'Latn', 'O Allah, don''t punish me for what they say, forgive me for what they don''t know, (and make me better than what they think of me)');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.118', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-118', 118, 'The Talbiya for the one doing Haj or ''Omra', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.118.part.001', 'dua.hisn.118', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.118.part.001.segment.001', 'dua.hisn.118.part.001', 1, 'arabic', 'ar', 'Arab', 'لَبَّيْكَ اللَّهُمَّ لَبَّيْكَ، لَبَّيْكَ لَا شَرِيكَ لَكَ لَبَّيْكَ، إِنَّ الحّمْدَ والنِّعْمَةِ، لَكَ والمُلْكُ، لَا شَرِيكَ لَكَ.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.118.part.001.segment.002', 'dua.hisn.118.part.001', 2, 'transliteration', 'ar-Latn', 'Latn', 'Labbaykal-lahumma labbayk, labbayka la shareeka laka labbayk, innal-hamda wanniAAmata laka walmulk, la shareeka lak.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.118.part.001.segment.003', 'dua.hisn.118.part.001', 3, 'translation', 'en', 'Latn', '‘Here I am O Allah, (in response to Your call), here I am. Here I am, You have no partner, here I am.  Verily all praise, grace and sovereignty belong to You. You have no partner.');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.119', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-119', 119, 'The Takbîr passing the black stone', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.119.part.001', 'dua.hisn.119', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.119.part.001.segment.001', 'dua.hisn.119.part.001', 1, 'comment', 'en', 'Latn', 'and say:');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.119.part.001.segment.002', 'dua.hisn.119.part.001', 2, 'arabic', 'ar', 'Arab', 'اللهُ أَكْبَرُ.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.119.part.001.segment.003', 'dua.hisn.119.part.001', 3, 'transliteration', 'ar-Latn', 'Latn', 'Allahu akbar');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.119.part.001.segment.004', 'dua.hisn.119.part.001', 4, 'translation', 'en', 'Latn', '‘The Prophet (saws) circled the KaAAbah on a camel, every time he reached the black stone he would point to it with his staff');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.119.part.002', 'dua.hisn.119', 2);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.119.part.002.segment.001', 'dua.hisn.119.part.002', 1, 'translation', 'en', 'Latn', '‘Allah is the greatest’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.120', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-120', 120, 'Between the Yemeni corner and the black stone', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.120.part.001', 'dua.hisn.120', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.120.part.001.segment.001', 'dua.hisn.120.part.001', 1, 'comment', 'en', 'Latn', 'The Prophet (saws) used to say between the Yemeni corner and the black stone:');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.120.part.001.segment.002', 'dua.hisn.120.part.001', 2, 'arabic', 'ar', 'Arab', 'رَبَّنَا آتِنَا في الدُّنْيَا حسَنَةً وفي الآخِرَةِ حسَنةً وقِنَا عذَابَ النَّارِ');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.120.part.001.segment.003', 'dua.hisn.120.part.001', 3, 'transliteration', 'ar-Latn', 'Latn', 'Rabbana atina fee alddunya hasanatan wafee al-akhirati hasanatan waqina  AAathaba alnnar 	Al-Baqarah: 201');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.120.part.001.segment.004', 'dua.hisn.120.part.001', 4, 'translation', 'en', 'Latn', '‘O our Lord, grant us the best in this life and the best in the next life, and protect us from the punishment of the Fire.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.121', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-121', 121, 'When at Mount Safa and Mount Marwah', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.121.part.001', 'dua.hisn.121', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.121.part.001.segment.001', 'dua.hisn.121.part.001', 1, 'comment', 'en', 'Latn', 'Jabir said when describing the Prophet (saws)’s pilgrimage: ‘and when he approached mount Safa he recited:');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.121.part.001.segment.002', 'dua.hisn.121.part.001', 2, 'arabic', 'ar', 'Arab', 'إِنَّ الصَّفَا والمَرْوَةَ مِنْ شَعائرِ الله');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.121.part.001.segment.003', 'dua.hisn.121.part.001', 3, 'transliteration', 'ar-Latn', 'Latn', 'Innas-safa wa-almarwata min shaAAa-iri Allah.');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.121.part.002', 'dua.hisn.121', 2);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.121.part.002.segment.001', 'dua.hisn.121.part.002', 1, 'arabic', 'ar', 'Arab', 'أَبْدَأُ بِمَا بَدَأَ اللهُ بِهِ.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.121.part.002.segment.002', 'dua.hisn.121.part.002', 2, 'transliteration', 'ar-Latn', 'Latn', 'Abda-o bima badaal-lahu bih.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.121.part.002.segment.003', 'dua.hisn.121.part.002', 3, 'translation', 'en', 'Latn', '‘Indeed Safa and Marwah are from the places of worship of Allah’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.121.part.003', 'dua.hisn.121', 3);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.121.part.003.segment.001', 'dua.hisn.121.part.003', 1, 'comment', 'en', 'Latn', 'so he started with Safa and climed it until he could see the KaAAbah, he then faced it and said:');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.121.part.003.segment.002', 'dua.hisn.121.part.003', 2, 'arabic', 'ar', 'Arab', 'اللهُ أكْبَرُ، اللهُ أَكْبَرُ، اللهُ أَكْبَرُ');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.121.part.003.segment.003', 'dua.hisn.121.part.003', 3, 'transliteration', 'ar-Latn', 'Latn', 'Allahu akbar, Allahu akbar, Allahu akbar.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.121.part.003.segment.004', 'dua.hisn.121.part.003', 4, 'translation', 'en', 'Latn', '‘I begin with what Allah began with.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.121.part.004', 'dua.hisn.121', 4);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.121.part.004.segment.001', 'dua.hisn.121.part.004', 1, 'comment', 'en', 'Latn', 'and then he would say the following three times making a supplication (one should make a personal supplication) after each time:');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.121.part.004.segment.002', 'dua.hisn.121.part.004', 2, 'arabic', 'ar', 'Arab', 'لَا إِلهَ إِلَّا اللهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ المُلْكُ وَلَهُ الحَمْدُ وهُوَ عَلى كُلِّ شَيءٍ قَديرٌ، لَا إِلَهَ إِلَّا اللهُ وَحْدَهُ أَنْجَزَ وَعْدَهُ، وَنَصَرَ عَبْدَهُ وَهَزَمَ الأَحْزَابَ وَحْدَهُ.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.121.part.004.segment.003', 'dua.hisn.121.part.004', 3, 'transliteration', 'ar-Latn', 'Latn', 'La ilaha illal-lahu wahdahu la shareeka lah, lahul-mulku walahul-hamd, wahuwa AAala kulli shayin qadeer, la ilaha illal-lahu wahdah, anjaza waAAdah, wanasara AAabdah, wahazamal -ahzaba wahdah.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.121.part.004.segment.004', 'dua.hisn.121.part.004', 4, 'translation', 'en', 'Latn', '‘Allah is the greatest, Allah is the greatest, Allah is the greatest.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.121.part.005', 'dua.hisn.121', 5);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.121.part.005.segment.001', 'dua.hisn.121.part.005', 1, 'comment', 'en', 'Latn', 'he would repeat this action at Marwah.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.121.part.005.segment.002', 'dua.hisn.121.part.005', 2, 'translation', 'en', 'Latn', '‘None has the right to be worshipped except Allah, alone, without partner.To Him belongs all sovereignty and praise and He is over all things amnipotent. None has the right to be worshipped except Allah alone.  He fulfilled His promise, aided His Servant and single-handedly defeated the allies.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.122', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-122', 122, 'The Day of ''Arafah', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.122.part.001', 'dua.hisn.122', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.122.part.001.segment.001', 'dua.hisn.122.part.001', 1, 'comment', 'en', 'Latn', '‘The best of supplications is the supplication on the day of AAarafah and the best which I and the Prophet (saws)s before me have said (is):');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.122.part.001.segment.002', 'dua.hisn.122.part.001', 2, 'arabic', 'ar', 'Arab', 'لَا إِلَهَ إِلَّا اللهُ وَحْدَهُ لَا شَريكَ لَهُ، لَهُ المُلْكُ ولَهُ الحَمْدُ وهُوَ عَلَى كُلِّ شَيْءٍ قَديرٌ.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.122.part.001.segment.003', 'dua.hisn.122.part.001', 3, 'transliteration', 'ar-Latn', 'Latn', 'La ilaha illal-lahu wahdahu la shareeka lah, lahul-mulku walahul-hamd, wahuwa AAala kulli shayin qadeer.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.122.part.001.segment.004', 'dua.hisn.122.part.001', 4, 'translation', 'en', 'Latn', '‘None has the right to be worshipped except Allah, alone, without partner. To Him belongs all praise and sovereignty and He is over all things omnipotent.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.123', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-123', 123, 'Remembrance at Muzdalifa', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.123.part.001', 'dua.hisn.123', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.123.part.001.segment.001', 'dua.hisn.123.part.001', 1, 'comment', 'en', 'Latn', 'Jabir said: ‘He rode Al-Qaswa until he reached Al-MashAAar Al-Haram, he then faced the qiblah, supplicated to Allah, and extoled His greatness and oneness.  He stood until the sun shone but left before it rose.’');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.123.part.001.segment.002', 'dua.hisn.123.part.001', 2, 'comment', 'en', 'Latn', 'Al-Qaswa: The name of the Prophet (saws)’s camel.');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.124', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-124', 124, 'When throwing each pebble at the Jamarat', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.124.part.001', 'dua.hisn.124', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.124.part.001.segment.001', 'dua.hisn.124.part.001', 1, 'comment', 'en', 'Latn', 'i.e. Stoning the three areas at Mina during Hajj.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.124.part.001.segment.002', 'dua.hisn.124.part.001', 2, 'comment', 'en', 'Latn', 'Every time the Prophet (saws) threw a pebble at any of the three jamarat');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.124.part.001.segment.003', 'dua.hisn.124.part.001', 3, 'comment', 'en', 'Latn', 'he would say:');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.124.part.001.segment.004', 'dua.hisn.124.part.001', 4, 'arabic', 'ar', 'Arab', 'اللهُ أَكْبَرُ.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.124.part.001.segment.005', 'dua.hisn.124.part.001', 5, 'transliteration', 'ar-Latn', 'Latn', 'Allahu akbar.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.124.part.001.segment.006', 'dua.hisn.124.part.001', 6, 'translation', 'en', 'Latn', '‘Allah is the greatest’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.124.part.002', 'dua.hisn.124', 2);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.124.part.002.segment.001', 'dua.hisn.124.part.002', 1, 'comment', 'en', 'Latn', 'on completion of the first jamarah, he advanced a little, stood facing the qiblah, raised his hands and supplicated.  He also did this after the second jamarah but not the third.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.125', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-125', 125, 'At times of amazement and delight', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.125.part.001', 'dua.hisn.125', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.125.part.001.segment.001', 'dua.hisn.125.part.001', 1, 'arabic', 'ar', 'Arab', 'سُبْحَانَ اللهِ!');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.125.part.001.segment.002', 'dua.hisn.125.part.001', 2, 'transliteration', 'ar-Latn', 'Latn', 'Subhanal-lah!.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.125.part.001.segment.003', 'dua.hisn.125.part.001', 3, 'translation', 'en', 'Latn', '‘How perfect Allah is.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.125.part.002', 'dua.hisn.125', 2);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.125.part.002.segment.001', 'dua.hisn.125.part.002', 1, 'arabic', 'ar', 'Arab', 'اللهُ أَكْبرُ!');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.125.part.002.segment.002', 'dua.hisn.125.part.002', 2, 'transliteration', 'ar-Latn', 'Latn', 'Allahu akbar.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.125.part.002.segment.003', 'dua.hisn.125.part.002', 3, 'translation', 'en', 'Latn', '‘Allah is the greatest.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.126', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-126', 126, 'Upon receiving pleasant news', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.126.part.001', 'dua.hisn.126', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.126.part.001.segment.001', 'dua.hisn.126.part.001', 1, 'comment', 'en', 'Latn', 'The Prophet (saws) would prostrate in gratitude to Allah تبارك و تعالى  upon receiving news which pleased him or which caused pleasure.');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.127', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-127', 127, 'When feeling some pain in the body', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.127.part.001', 'dua.hisn.127', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.127.part.001.segment.001', 'dua.hisn.127.part.001', 1, 'comment', 'en', 'Latn', 'and say:');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.127.part.001.segment.002', 'dua.hisn.127.part.001', 2, 'arabic', 'ar', 'Arab', 'بِسْمِ اللهِ (ثَلاثاً)');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.127.part.001.segment.003', 'dua.hisn.127.part.001', 3, 'transliteration', 'ar-Latn', 'Latn', 'Bismil-lah (three times)');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.127.part.001.segment.004', 'dua.hisn.127.part.001', 4, 'translation', 'en', 'Latn', '‘Place your hand at the site of the pain');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.127.part.002', 'dua.hisn.127', 2);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.127.part.002.segment.001', 'dua.hisn.127.part.002', 1, 'comment', 'en', 'Latn', '…the supplicate seven times:');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.127.part.002.segment.002', 'dua.hisn.127.part.002', 2, 'arabic', 'ar', 'Arab', 'أَعُوذُ باللهِ وَقُدْرَتِهِ مَنْ شَرِّ مَا أَجِدُ وَأُحَاذِرُ. (سبع مرات)');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.127.part.002.segment.003', 'dua.hisn.127.part.002', 3, 'transliteration', 'ar-Latn', 'Latn', 'aAAoothu billahi waqudratih min sharri ma ajidu wa-ohathir. (seven times).');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.127.part.002.segment.004', 'dua.hisn.127.part.002', 4, 'translation', 'en', 'Latn', '‘In the name of Allah’	   (three times)');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.127.part.003', 'dua.hisn.127', 3);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.127.part.003.segment.001', 'dua.hisn.127.part.003', 1, 'translation', 'en', 'Latn', '‘I take refuge in Allah and within His omnipotence from the evil that I feel and am wary of.’	(seven times)');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.128', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-128', 128, 'When in fear of afflicting something or someone with one’s eye', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.128.part.001', 'dua.hisn.128', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.128.part.001.segment.001', 'dua.hisn.128.part.001', 1, 'comment', 'en', 'Latn', 'The Evil Eye: To look at something and be impressed with it, causing harm to befall it. This “looking” may or may not involve jealousy, and can occur unintentionally, indeed be part of a person’s nature! A person can even inflict harm on himself.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.128.part.001.segment.002', 'dua.hisn.128.part.001', 2, 'comment', 'en', 'Latn', 'From the supplications for the protection against the Evil Eye:');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.128.part.001.segment.003', 'dua.hisn.128.part.001', 3, 'arabic', 'ar', 'Arab', 'اللّهُـمَّ بارِك عَلَـيه.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.128.part.001.segment.004', 'dua.hisn.128.part.001', 4, 'transliteration', 'ar-Latn', 'Latn', 'Allahumma barik AAalayh.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.128.part.001.segment.005', 'dua.hisn.128.part.001', 5, 'translation', 'en', 'Latn', '‘O Allah, send blessing upon him.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.128.part.002', 'dua.hisn.128', 2);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.128.part.002.segment.001', 'dua.hisn.128.part.002', 1, 'arabic', 'ar', 'Arab', 'ما شاءَ الله، لا قُوَّةَ إلاّ بالله.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.128.part.002.segment.002', 'dua.hisn.128.part.002', 2, 'transliteration', 'ar-Latn', 'Latn', 'Ma shaal-lah, la quwwata illa billah.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.128.part.002.segment.003', 'dua.hisn.128.part.002', 3, 'translation', 'en', 'Latn', '‘(this is) that which Allah has willed, there is no power except with Allah.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.128.part.003', 'dua.hisn.128', 3);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.128.part.003.segment.001', 'dua.hisn.128.part.003', 1, 'translation', 'en', 'Latn', '‘If you see something from your brother, yourself or wealth which you find impressing, then invoke blessings for it, for the evil eye is indeed true’.');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.129', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-129', 129, 'When startled', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.129.part.001', 'dua.hisn.129', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.129.part.001.segment.001', 'dua.hisn.129.part.001', 1, 'arabic', 'ar', 'Arab', 'لا إِلهَ إلاَّ اللهُ.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.129.part.001.segment.002', 'dua.hisn.129.part.001', 2, 'transliteration', 'ar-Latn', 'Latn', 'La ilaha illal-lah.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.129.part.001.segment.003', 'dua.hisn.129.part.001', 3, 'translation', 'en', 'Latn', '‘None has the right to be worshipped except Allah.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.130', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-130', 130, 'When slaughtering or offering a sacrifice', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.130.part.001', 'dua.hisn.130', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.130.part.001.segment.001', 'dua.hisn.130.part.001', 1, 'arabic', 'ar', 'Arab', 'بِسْمِ اللهِ واللهُ أَكْبَرُ اللَّهُمَّ مِنْكَ ولَكَ اللَّهُمَّ تَقَبَّلْ مِنِّي.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.130.part.001.segment.002', 'dua.hisn.130.part.001', 2, 'transliteration', 'ar-Latn', 'Latn', 'Bismil-lah wallahu akbar, allahumma minka walak, allahumma taqabbal  minnee.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.130.part.001.segment.003', 'dua.hisn.130.part.001', 3, 'translation', 'en', 'Latn', '‘In the name of Allah, and Allah is the greatest.  O Allah, (it is) from You and belongs to You, O Allah, accept this from me.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.131', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-131', 131, 'To ward off the deception of the Obstinate Shaytans', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.131.part.001', 'dua.hisn.131', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.131.part.001.segment.001', 'dua.hisn.131.part.001', 1, 'arabic', 'ar', 'Arab', 'أَعُوذُ بكَلِمَاتِ اللهِ التَّامَّاتِ الَّتِي لَا يُجَاوِزُهُنَّ بَرٌّ ولَا فَاجرٌ مِنْ شّرِّ مَا خَلقَ، وبَرَأَ وذَرَأَ، ومِنْ شَرِّ مَا يَنْزِلُ مِنَ السَّمَاءِ وِمنْ شَرِّ مَا يَعْرُجُ فيهَا، ومِن شَرِّ مَا ذَرَأَ في الأَرْضِ ومِنْ شَرِّ مَا يَخْرُجُ مِنْهَا، وِمنْ شَرِّ فِتَنِ اللَّيْلِ والنَّهارِ، ومِنْ شَرِّ كُلِّ طارِقٍ إِلَّا طَارِقاً يَطْرُقُ بخَيْرٍ يَا رَحْمَنُ.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.131.part.001.segment.002', 'dua.hisn.131.part.001', 2, 'transliteration', 'ar-Latn', 'Latn', 'aAAoothu bikalimatil-lahit-tammat, allatee la yujawizuhunna barrun wala fajir min sharri ma khalaq, wabaraa watharaa, wamin sharri ma yanzilu minas-sama/, wamin sharri ma yaAAruju feeha, wamin sharri ma tharaa fil-ard, wamin sharri ma yakhruju minha, wamin sharri fitnanil-layli wannahar, wamin sharri kulli tariqin illa tariqan yatruqu bikhayrin ya Rahman.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.131.part.001.segment.003', 'dua.hisn.131.part.001', 3, 'translation', 'en', 'Latn', '‘I take refuge within Allah’s perfect words which no righteous or unrighteous person can transgress, from all the evil that He has created, made and originated.  (I take refuge) from the evil that descends from the sky and the evil that rises up to it.  (I take refuge) from the evil that is spread on Earth and the evil that springs from her, and I take refuge from the evil of the tribulations of night and day, and the evil of one who visits at night except the one who brings good, O Merciful One.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.132', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-132', 132, 'Seeking forgiveness and repentance', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.132.part.001', 'dua.hisn.132', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.132.part.001.segment.001', 'dua.hisn.132.part.001', 1, 'comment', 'en', 'Latn', 'He (saws) also said: ‘O People, Repent! Verily I repent to Allah, a hundred times a day.’');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.132.part.001.segment.002', 'dua.hisn.132.part.001', 2, 'comment', 'en', 'Latn', 'He (saws) also said: ‘Whoever says:');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.132.part.001.segment.003', 'dua.hisn.132.part.001', 3, 'arabic', 'ar', 'Arab', 'أَسْتَغْفِرُ اللهَ الَّذِي لَا إِلَهَ إلَّا هُوَ الحَيُّ القَيّوُمُ وأَتُوبُ إِلَيهِ.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.132.part.001.segment.004', 'dua.hisn.132.part.001', 4, 'transliteration', 'ar-Latn', 'Latn', 'Astaghfirul-lahal-lathee la ilaha illa huwal-hayyul-qayyoomu wa-atoobu ilayh.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.132.part.001.segment.005', 'dua.hisn.132.part.001', 5, 'translation', 'en', 'Latn', '‘The Messenger of Allah (saws) said: ‘By Allah, I seek forgiveness and repent to Allah, more than seventy times a day.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.132.part.002', 'dua.hisn.132', 2);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.132.part.002.segment.001', 'dua.hisn.132.part.002', 1, 'comment', 'en', 'Latn', '…Allah would forgive him even if he was one who fled during the advance of an army.’');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.132.part.002.segment.002', 'dua.hisn.132.part.002', 2, 'comment', 'en', 'Latn', 'He (saws) said: ‘The nearest the Lord comes to His servant is in the middle of the night, so if you are able to be of those who remember Allah at that time, then be so.’');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.132.part.002.segment.003', 'dua.hisn.132.part.002', 3, 'comment', 'en', 'Latn', 'He (saws) also said: ‘The nearest a servant is to his Lord is when he is prostrating, so supplicate much therein.’');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.132.part.002.segment.004', 'dua.hisn.132.part.002', 4, 'comment', 'en', 'Latn', 'He (saws) also said: ‘verily my heart becomes preoccupied, and verily I seek Allah’s forgiveness a hundred times a day.’');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.132.part.002.segment.005', 'dua.hisn.132.part.002', 5, 'comment', 'en', 'Latn', 'preoccupied: i.e. in a state of ‘forgetfulness’. The Prophet (saws) always used to increase in his remembrance of his Lord, in attaining a nearness to Allah and having consciousness of Allah to the extent that if this intensity lessened in anyway, he would regard it as a sin and would then race to seek forgiveness from Allah.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.132.part.002.segment.006', 'dua.hisn.132.part.002', 6, 'translation', 'en', 'Latn', '‘I seek Allah’s forgiveness, besides whom, none has the right to be worshipped except He, The Ever Living, The Self-Subsisting and Supporter of all, and I turn to Him in repentance.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.133', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-133', 133, 'Excellence of remembrance and glorification of Allah', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.133.part.001', 'dua.hisn.133', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.133.part.001.segment.001', 'dua.hisn.133.part.001', 1, 'comment', 'en', 'Latn', 'Abu Hurayrah reported that the Messenger of Allah (saws) said: ‘Whoever says:');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.133.part.001.segment.002', 'dua.hisn.133.part.001', 2, 'arabic', 'ar', 'Arab', 'لَا إِلهَ إِلَّا اللهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ المُلْكُ وَلَهُ الحَمْد، وهُوَ عَلى كُلِّ شَيءٍ قَديرٌ. (مائة مرة).');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.133.part.001.segment.003', 'dua.hisn.133.part.001', 3, 'transliteration', 'ar-Latn', 'Latn', 'La ilaha illal-lahu wahdahu la shareeka lah, lahul-mulku walahul-hamd, wahuwa AAala kulli shayin qadeer.(one hundred times)');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.133.part.001.segment.004', 'dua.hisn.133.part.001', 4, 'translation', 'en', 'Latn', '‘None has the right to be worshipped except Allah, alone, without partner. To Him belongs all sovereignty and praise and He is over all things omnipotent.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.133.part.002', 'dua.hisn.133', 2);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.133.part.002.segment.001', 'dua.hisn.133.part.002', 1, 'comment', 'en', 'Latn', '…a hundred times during the day, has the reward of freeing ten slaves, a hundred good deeds are recorded for him and a hundred bad deeds are wiped away and he has gained refuge from the devil that day until evening and none shall come with anything better except someone who has done more.’');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.133.part.002.segment.002', 'dua.hisn.133.part.002', 2, 'comment', 'en', 'Latn', '‘Whoever says:');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.133.part.002.segment.003', 'dua.hisn.133.part.002', 3, 'arabic', 'ar', 'Arab', 'سُبْحَانَ اللهِ وَبِحَمْدِهِ. (مائة مرة في اليوم)');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.133.part.002.segment.004', 'dua.hisn.133.part.002', 4, 'transliteration', 'ar-Latn', 'Latn', 'Subhanal-lahi wabihamdih. (one hundred times daily)');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.133.part.002.segment.005', 'dua.hisn.133.part.002', 5, 'translation', 'en', 'Latn', '‘How perfect Allah is and I praise Him.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.133.part.003', 'dua.hisn.133', 3);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.133.part.003.segment.001', 'dua.hisn.133.part.003', 1, 'comment', 'en', 'Latn', '…a hundred times during the day, his sins are wiped away, even if they are like the foam of the sea.’');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.133.part.003.segment.002', 'dua.hisn.133.part.003', 2, 'comment', 'en', 'Latn', 'Abu Hurayrah reported that the Messenger of Allah (saws) said: ‘Whoever says at morning and evening time:');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.133.part.003.segment.003', 'dua.hisn.133.part.003', 3, 'arabic', 'ar', 'Arab', 'سُبْحَانَ اللهِ وبِحَمْدِهِ (حين يصبح وحين يمسي)');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.133.part.003.segment.004', 'dua.hisn.133.part.003', 4, 'transliteration', 'ar-Latn', 'Latn', 'Subhanal-lahi wabihamdih.(at morning & evening time)');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.133.part.003.segment.005', 'dua.hisn.133.part.003', 5, 'translation', 'en', 'Latn', '‘How perfect Allah is and I praise Him.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.133.part.004', 'dua.hisn.133', 4);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.133.part.004.segment.001', 'dua.hisn.133.part.004', 1, 'comment', 'en', 'Latn', '…one hundred times, none shall come on the Day of Resurrection with anything better except someone who has said the same or even more.’');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.133.part.004.segment.002', 'dua.hisn.133.part.004', 2, 'comment', 'en', 'Latn', 'morning: after prayer until the sunrises, evening: after AAasr prayer until the sunsets, however some scholars say: after the sunsets and onwards.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.133.part.004.segment.003', 'dua.hisn.133.part.004', 3, 'comment', 'en', 'Latn', 'Aboo Ayyoob Al-Ansaree related that The Prophet (saws) said: ‘Whoever says:');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.133.part.004.segment.004', 'dua.hisn.133.part.004', 4, 'arabic', 'ar', 'Arab', 'لَا إِلهَ إِلَّا اللهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ المُلْكُ وَلَهُ الحَمْدُ وهُوَ عَلى كُلِّ شَيءٍ قَديرٌ.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.133.part.004.segment.005', 'dua.hisn.133.part.004', 5, 'transliteration', 'ar-Latn', 'Latn', 'La ilaha illal-lahu wahdahu la shareeka lah, lahul-mulku walahul-hamd, wahuwa AAala kulli shayin qadeer.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.133.part.004.segment.006', 'dua.hisn.133.part.004', 6, 'translation', 'en', 'Latn', '‘None has the right to be worshipped except Allah, alone, without partener. To Him belongs all sovereignty and praise and He is over all things omnipotent.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.133.part.005', 'dua.hisn.133', 5);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.133.part.005.segment.001', 'dua.hisn.133.part.005', 1, 'comment', 'en', 'Latn', '…..ten times is like one who has freed four souls from among the children of IsmaAAeel.’');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.133.part.005.segment.002', 'dua.hisn.133.part.005', 2, 'comment', 'en', 'Latn', 'Aboo Hurayrah reported that the Messenger of Allah (saws) said:’(There are) Two words, (which are) light on the tongue, heavy on the Scale and beloved to The Most Gracious:');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.133.part.005.segment.003', 'dua.hisn.133.part.005', 3, 'arabic', 'ar', 'Arab', 'سُبْحانَ اللهِ وَبِحَمْدِهِ وسُبْحَانَ اللهِ العَظِيمِ.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.133.part.005.segment.004', 'dua.hisn.133.part.005', 4, 'transliteration', 'ar-Latn', 'Latn', 'Subhanal-lahi wabihamdih, wasubhanal-lahil-AAatheem.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.133.part.005.segment.005', 'dua.hisn.133.part.005', 5, 'translation', 'en', 'Latn', '‘ How perfect Allah is and I praise Him. How perfect Allah is, The Supreme.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.133.part.006', 'dua.hisn.133', 6);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.133.part.006.segment.001', 'dua.hisn.133.part.006', 1, 'comment', 'en', 'Latn', 'Aboo Hurayrah reported that the Messenger of Allah (saws) said: ‘Saying:');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.133.part.006.segment.002', 'dua.hisn.133.part.006', 2, 'arabic', 'ar', 'Arab', 'سُبْحَانَ اللهِ، والحَمْدُ للهِ، لَا إِلَهَ إلَّا اللهُ واللهُ أَكْبَرُ.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.133.part.006.segment.003', 'dua.hisn.133.part.006', 3, 'transliteration', 'ar-Latn', 'Latn', 'Subhanal-lah, walhamdu lillah, la ilaha illal-lah wallahu akbar.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.133.part.006.segment.004', 'dua.hisn.133.part.006', 4, 'translation', 'en', 'Latn', '‘ How perfect Allah is, and all praise is for Allah. None has the right to be worshipped except Allah, and Allah is the greatest.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.133.part.007', 'dua.hisn.133', 7);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.133.part.007.segment.001', 'dua.hisn.133.part.007', 1, 'comment', 'en', 'Latn', '….. is more beloved to me than everything the sun has risen over.’');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.133.part.007.segment.002', 'dua.hisn.133.part.007', 2, 'comment', 'en', 'Latn', 'Sa’d said: ‘We were sitting with the Messenger of Allah (saws), and he said: ‘Are any of you unable to gain a thousand good deeds each day?’ Somebody then asked him (saws) : How does one achieve a thousand good deeds? He replied: ‘He should say:');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.133.part.007.segment.003', 'dua.hisn.133.part.007', 3, 'arabic', 'ar', 'Arab', 'سُبْحَانَ اللهِ.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.133.part.007.segment.004', 'dua.hisn.133.part.007', 4, 'transliteration', 'ar-Latn', 'Latn', 'Subhanal-lah.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.133.part.007.segment.005', 'dua.hisn.133.part.007', 5, 'translation', 'en', 'Latn', '‘How perfect Allah is.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.133.part.008', 'dua.hisn.133', 8);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.133.part.008.segment.001', 'dua.hisn.133.part.008', 1, 'comment', 'en', 'Latn', '….one hundred times, for a thousand good deeds are recorded for him or a thousand bad deeds are wiped away.’');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.133.part.008.segment.002', 'dua.hisn.133.part.008', 2, 'comment', 'en', 'Latn', 'Jabbir related that the Prophet (saws) said: ‘Whoever says:');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.133.part.008.segment.003', 'dua.hisn.133.part.008', 3, 'arabic', 'ar', 'Arab', 'سُبْحَانَ اللهِ العَظِيمِ وبِحَمْدِهِ.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.133.part.008.segment.004', 'dua.hisn.133.part.008', 4, 'transliteration', 'ar-Latn', 'Latn', 'Subhanal-lahil-AAatheemi wabihamdih.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.133.part.008.segment.005', 'dua.hisn.133.part.008', 5, 'translation', 'en', 'Latn', '‘ How perfect Allah is. The Supreme, and I praise Him.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.133.part.009', 'dua.hisn.133', 9);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.133.part.009.segment.001', 'dua.hisn.133.part.009', 1, 'comment', 'en', 'Latn', '…..a palm tree is planted for him in paradise.’');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.133.part.009.segment.002', 'dua.hisn.133.part.009', 2, 'comment', 'en', 'Latn', '‘AAabdullah Ibn Qays related that the Prophet (saws) said to him: ‘ O ‘AAabdullah Ibn Qays, shall I not inform you of a treasure from the treasures of paradise?’ He (saws) then said: ‘Say:');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.133.part.009.segment.003', 'dua.hisn.133.part.009', 3, 'arabic', 'ar', 'Arab', 'لَا حَوٍلَ وَلَا قُوَّةَ إِلَّا باللهِ.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.133.part.009.segment.004', 'dua.hisn.133.part.009', 4, 'transliteration', 'ar-Latn', 'Latn', 'La  hawla wala quwwata illa billah.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.133.part.009.segment.005', 'dua.hisn.133.part.009', 5, 'translation', 'en', 'Latn', '‘There is no might nor power except with Allah.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.133.part.010', 'dua.hisn.133', 10);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.133.part.010.segment.001', 'dua.hisn.133.part.010', 1, 'comment', 'en', 'Latn', '‘ the most beloved words to Allah are four:');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.133.part.010.segment.002', 'dua.hisn.133.part.010', 2, 'arabic', 'ar', 'Arab', 'سُبْحَانَ اللهِ، والحَمْدُ للهِ، ولَا إِلَهَ إِلاَّ اللهُ واللهُ أَكْبَرُ.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.133.part.010.segment.003', 'dua.hisn.133.part.010', 3, 'transliteration', 'ar-Latn', 'Latn', 'Subhanal-lah, walhamdu lillah, wala ilaha illal-lah, wallahu akbar.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.133.part.010.segment.004', 'dua.hisn.133.part.010', 4, 'translation', 'en', 'Latn', '‘ How perfect Allah is, all praise is for Allah. None has the right to be worshipped except Allah and Allah is the greatest.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.133.part.011', 'dua.hisn.133', 11);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.133.part.011.segment.001', 'dua.hisn.133.part.011', 1, 'comment', 'en', 'Latn', '….it does not matter which of them you start with.’');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.133.part.011.segment.002', 'dua.hisn.133.part.011', 2, 'comment', 'en', 'Latn', 'SaAAd Ibn Abee Waqqas narrated that a man came to the Messenger of Allah (saws) and said to him: ‘Teach me something which I should say?’ He said: ‘Say:');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.133.part.011.segment.003', 'dua.hisn.133.part.011', 3, 'arabic', 'ar', 'Arab', 'لَا إِلهَ إِلَّا اللهُ وَحْدَهُ لَا شَرِيكَ لَهُ، اللهُ أَكْبَرُ كَبيراَ والْحَمْدُ للهِ كَثيراً، سُبْحَانَ اللهِ رَبِّ العَالَمينَ، لَا حَوْلَ وَلَا قُوَّةَ إِلّا باللهِ العَزيزِ الْحَكِيمِ.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.133.part.011.segment.004', 'dua.hisn.133.part.011', 4, 'transliteration', 'ar-Latn', 'Latn', 'La ilaha illal-lah, wahdahu la shareeka lah, Allahu akbaru kabeera, walhamdu lillahi katheera, subhanal-lahi rabbil-AAalameen, la hawla wala quwwata illa billahil-AAazeezil-hakeem.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.133.part.011.segment.005', 'dua.hisn.133.part.011', 5, 'translation', 'en', 'Latn', '‘None has the right to be worshipped except Allah, alone without partener. Allah is most great and much praise is for Allah. How perfect Allah is, Lord of the worlds. There is no might nor power except with Allah, The Exalted in might, The Wise.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.133.part.012', 'dua.hisn.133', 12);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.133.part.012.segment.001', 'dua.hisn.133.part.012', 1, 'comment', 'en', 'Latn', '…the man then said: ‘These are for my Lord, and what is for me?’ He (saws) replied: Say:');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.133.part.012.segment.002', 'dua.hisn.133.part.012', 2, 'comment', 'en', 'Latn', 'Tariq Al-AshjaAAee said: ‘When someone would embrace Islam, the Prophet (saws) would teach him how to perform prayer and then order him to supplicate with the following words:');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.133.part.012.segment.003', 'dua.hisn.133.part.012', 3, 'arabic', 'ar', 'Arab', 'اللَّهُمَّ اغْفِرِ لِي، وارْحَمْنِي، واهْدِنِي، وعَافِنِي وارْزُقْنِي.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.133.part.012.segment.004', 'dua.hisn.133.part.012', 4, 'transliteration', 'ar-Latn', 'Latn', 'Allahummagh-fir lee, warhamnee, wahdinee, waAAafinee warzuqnee.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.133.part.012.segment.005', 'dua.hisn.133.part.012', 5, 'translation', 'en', 'Latn', '‘O Allah, forgive me, have mercy upon me, guide me, give me health and grant me sustenance.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.133.part.013', 'dua.hisn.133', 13);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.133.part.013.segment.001', 'dua.hisn.133.part.013', 1, 'comment', 'en', 'Latn', 'Jabir  Ibn ‘AAabdullah related that the Messenger of Allah (saws) said: ‘Verily, the best supplication is:');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.133.part.013.segment.002', 'dua.hisn.133.part.013', 2, 'arabic', 'ar', 'Arab', 'الْحَمْدُ للهِ.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.133.part.013.segment.003', 'dua.hisn.133.part.013', 3, 'transliteration', 'ar-Latn', 'Latn', 'Alhamdu lillah');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.133.part.013.segment.004', 'dua.hisn.133.part.013', 4, 'translation', 'en', 'Latn', '‘All praise is for Allah.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.133.part.014', 'dua.hisn.133', 14);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.133.part.014.segment.001', 'dua.hisn.133.part.014', 1, 'comment', 'en', 'Latn', '…and indeed, the best form of remembrance is:');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.133.part.014.segment.002', 'dua.hisn.133.part.014', 2, 'arabic', 'ar', 'Arab', 'لَا إِلَه إِلَّا اللهُ.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.133.part.014.segment.003', 'dua.hisn.133.part.014', 3, 'transliteration', 'ar-Latn', 'Latn', 'La ilaha illal-lah.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.133.part.014.segment.004', 'dua.hisn.133.part.014', 4, 'translation', 'en', 'Latn', '‘None has the right to be worshipped except Allah.’');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.133.part.015', 'dua.hisn.133', 15);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.133.part.015.segment.001', 'dua.hisn.133.part.015', 1, 'comment', 'en', 'Latn', '‘The everlasting righteous deeds:');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.133.part.015.segment.002', 'dua.hisn.133.part.015', 2, 'arabic', 'ar', 'Arab', 'سُبْحَانَ اللهِ، والْحَمْدُ للهِ، لَا إِلَهَ إَلَّا اللهُ واللهُ أَكْبَرُ وَلَا حَوْلَ وَلَا قُوَّةَ إلَّا باللهِ.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.133.part.015.segment.003', 'dua.hisn.133.part.015', 3, 'transliteration', 'ar-Latn', 'Latn', 'Subhanal-lah, walhamdu lillah, la ilaha illal-lah, wallahu akbar, wala hawla wala quwwata illa billah.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.133.part.015.segment.004', 'dua.hisn.133.part.015', 4, 'translation', 'en', 'Latn', '‘How perfect Allah is, and all praise is for Allah. None has the right to be worshipped except Allah, and Allah is the greatest. There is no might nor power except with Allah.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.134', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-134', 134, 'How the Prophet (saws) made tasbeeh', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.134.part.001', 'dua.hisn.134', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.134.part.001.segment.001', 'dua.hisn.134.part.001', 1, 'comment', 'en', 'Latn', 'Tasbeeh, it means here, to say:');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.134.part.001.segment.002', 'dua.hisn.134.part.001', 2, 'comment', 'en', 'Latn', 'Subhanal-lah, alhamdu lillah, Allahu akbar.');
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.134.part.001.segment.003', 'dua.hisn.134.part.001', 3, 'translation', 'en', 'Latn', '‘AAabdullah Ibn AAamr said: ’I saw the prophet (saws) make tasbeeh with his right hand.’');
INSERT INTO content_records (id, dataset_id, content_type, legacy_id, sequence, title, verification_status, created_at, updated_at) VALUES ('dua.hisn.135', 'dataset.hisn.legacy.2026-07-11-v2', 'dua', 'dua-135', 135, 'General and beneficent rules', 'pending', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT INTO content_parts (id, record_id, position) VALUES ('dua.hisn.135.part.001', 'dua.hisn.135', 1);
INSERT INTO content_segments (id, part_id, position, kind, language_code, script_code, text) VALUES ('dua.hisn.135.part.001.segment.001', 'dua.hisn.135.part.001', 1, 'comment', 'en', 'Latn', 'When night falls, restrain your children (from going out) because at such time the devils spread about. After a period of time has passed, let them be. Shut your doors and mention Allah’s name, for verily the devil does not open a shut door, tie up your water-skins and mention Allah’s name, cover your vessels with anything and mention Allah’s name and put out your lamps.');
